// ================================================================================================
//  KvUiSweepRuntime.cs — САМОПРОГОН ВСЕГО ИНТЕРФЕЙСА ВНУТРИ ПРИЛОЖЕНИЯ (VR / AR / MR).
//
//  ОТКУДА ЗАДАЧА. Требование владельца дословно: «каждая кнопочка обязана выполнять реальную
//  работу». Проверить это глазами в шлеме невозможно: в шлеме виден один экран из десятков, а
//  ручной перебор занимает часы и всё равно не пересказывается в отчёте. Поэтому проверка
//  ВСТРОЕНА В ПРИЛОЖЕНИЕ: оно само обходит элементы интерфейса, нажимает их настоящим способом
//  uGUI и печатает строку на каждый элемент. Тестировщик читает журнал и файл отчёта, а не верит
//  на слово.
//
//  ЧЕМ ПЛОХО БЫЛО ДО ЭТОГО ФАЙЛА. Единственная проверка «нет кнопок-заглушек» —
//  `KvE2eSettingsDiag` (проверка 6.6) и статический гейт `UI_STUBS` — смотрит РЕЕСТР команд и
//  ИСХОДНИКИ. То есть она отвечает на вопрос «у команды есть обработчик в коде», но НЕ на вопрос
//  «нажатие на этот элемент интерфейса действительно что-то меняет». Разница ровно та же, что
//  между «переключатель нарисован» и «onClick подключён». Кнопка без подключённого `onClick`,
//  кнопка, чей обработчик падает, и кнопка, чей обработчик пишет в журнал и больше ничего не
//  делает, — все три проходили прежние проверки.
//
//  ЧТО СТАЛО. Здесь два слоя:
//    • ЧИСТОЕ ЯДРО (`KvUiSweepKind`, `KvUiSweepNames`, `KvUiSweepElement`, `KvUiSweepPanelState`,
//      `KvUiSweepPanelSig`, `KvUiSweepSnapshot`, `KvUiSweepDiff`, `KvUiSweepRun`, `KvUiSweepFlags`,
//      `KvUiSweepExemptions`, `KvUiSweepLayout`) — без сцены и без устройств. Именно его проверяют
//      EditMode-тесты `KvUiSweepTests` (08_Tests/Editor);
//    • РАНТАЙМ (`KvUiSweepRuntime`) — обход живой сцены: настоящие `Canvas`, настоящий путь
//      нажатия, снимки состояния ДО и ПОСЛЕ, изоляция состояния между элементами.
//
//  ЗАПУСК — ТОЛЬКО ПО ЯВНОМУ ЗАПРОСУ (обычный старт приложения не меняется ни на кадр):
//    • Android: extra интента
//        adb shell am start -n com.KazistovVv.app/com.unity3d.player.UnityPlayerGameActivity \
//            -e kv_uisweep 1 -e kv_mode mr
//      (`kv_mode` необязателен: без него режим VR/MR НЕ трогается, только фиксируется в отчёте);
//    • редактор: статический метод `RunFromEditor()` из PlayMode (или пункт меню
//      «KazistovVv → Диагностика → Самопрогон интерфейса»);
//    • ПК-сборка: аргумент командной строки `-kv_uisweep 1`.
//  Без этого флага `Boot()` выходит на первой строке, и приложение работает как обычно.
//
//  ОТЧЁТ:
//    • logcat: строка ПЕРЕД нажатием `[KvUiSweep] press=… type=… индекс=<i> из <N>`;
//              строка после нажатия `[KvUiSweep] element=… type=… ok=… effect=… exempt=…`;
//              итог `[KvUiSweep] ИТОГ: элементов N · сработало P · без эффекта F ·
//              исключений E · исчезло M · прогон=<layout> · время=<сек>`,
//              покрытие `[KvUiSweep] ПОКРЫТИЕ: проверено объектов M из найденных K`;
//    • файл `Application.persistentDataPath/Reports/_ui_sweep_<layout>.txt` (vr / mr / ar / pc).
//  После записи отчёта приложение ЗАВЕРШАЕТСЯ: прогон конечен, его можно ждать по времени
//  (иначе «прогон идёт» и «прогон завис» неразличимы — урок §13.11 проекта).
//
//  ДОРАБОТКА ПО РЕЗУЛЬТАТУ ПРОГОНА НА ПЛАНШЕТЕ 12.11.2026 (дефект оказался в САМОМ прогоне):
//    1) строка `press=` печатается ДО нажатия — по ней виден виновник, даже если следующей строки
//       не будет (прогон завис на кнопке, открывшей системные настройки Android);
//    2) сторож фокуса: уход приложения в фон после первого нажатия НЕ оставляет прогон молчать —
//       элемент помечается `ok=0`, пишется ИТОГ и приложение завершается;
//    3) системные пункты («настройки приложения», «о приложении», «разрешения»…) НЕ нажимаются —
//       но ТОЛЬКО вне панелей проекта, поэтому штатная панель «Настройки» проверяется как раньше;
//    4) файл отчёта ДОПИСЫВАЕТСЯ построчно: обрыв виден по последней строке, а не теряется целиком;
//    5) снимок состояния получил ОТПЕЧАТОК ПАНЕЛЕЙ ДОКА (сторона, свёрнутость, рейл, видимость,
//       размер). Без него три РАБОЧИЕ кнопки шапки дока («свернуть», «причалить», «в рейл»)
//       получали «нет изменений»: они не скрывают панель, а меняют её вид.
//
//  ДОРАБОТКА ПО ВТОРОМУ ПРОГОНУ НА ПЛАНШЕТЕ 12.11.2026 (45 ложных «без эффекта» из 140):
//    6) ОБХОД ИДЁТ ПО ПУТЯМ, А НЕ ПО ССЫЛКАМ. Первый же переключатель панели настроек
//       перестраивает её: объекты уничтожаются, собранные ранее ссылки `Selectable` мертвеют, и
//       45 элементов подряд получали «элемент уничтожен». Теперь перед каждым нажатием элемент
//       находится ЗАНОВО по строковому пути (индекс «путь → живой элемент» пересобирается, когда
//       путь не нашёлся), а сама очередь обхода (`KvUiSweepQueue`) помнит проверенные пути и
//       дополняется после пересбора интерфейса, не теряя непроверенное и не повторяя нажатое;
//       ключ поиска — путь БЕЗ подписи (`KvUiSweepNames.KeyOf`): подпись меняется от нажатия;
//    7) ОЖИДАНИЕ УСТОЙЧИВОСТИ после нажатия вместо «двух кадров на глаз»: ждём, пока элемент
//       снова находится и число объектов интерфейса не меняется 2 кадра, но НЕ ДОЛЬШЕ 1 с
//       (`KvUiSweepSettle`) — иначе вернулось бы зависание;
//    8) ИСЧЕЗЛО — ПЯТОЕ ЧИСЛО В ИТОГЕ. Если путь не найден ни после перепоиска, ни после
//       пересборки списка, элемент получает причину «элемент исчез после перестроения интерфейса
//       (путь не найден)» и отдельный счётчик. Это НЕ «кнопка не работает» и провалом не считается:
//       проверять было нечего. Тождество отчёта: N = P + F + E + исчезло.
//    9) СНИМОК УВИДЕЛ ФЛАГИ ОБОЛОЧКИ И ТЕМУ. Переключатели панели настроек («Фонарик», «Фантомы
//       траекторий», «Автообновление дерева», «Панель метрик», «Виртуальный геймпад»…) меняют не
//       вид панели, а `KvSettings`, поэтому без этих признаков они выглядели бы мёртвыми. Флаги
//       возвращаются после каждого элемента — иначе следующий проверялся бы в чужом состоянии.
//
//  ДОРАБОТКА ПО ТРЕТЬЕМУ ПРОГОНУ НА ПЛАНШЕТЕ 12.11.2026 (обрыв на ПЕРВОМ элементе + «дублей 45»):
//   10) СИСТЕМНЫЕ ШЛЮЗЫ (предполётные заглушки разрешений) НЕ НАЖИМАЮТСЯ И НЕ ВКЛЮЧАЮТСЯ. Прогон
//       нажал `GateButton«РАЗРЕШИТЬ КАМЕРУ»` — кнопку, вызывающую СИСТЕМНЫЙ диалог разрешений
//       Android; приложение ушло в фон, и 139 элементов из 140 не проверились никогда. Теперь
//       такие элементы получают `exempt=системный шлюз…`, а их скрытая панель не включается
//       принудительно (`KvUiSweepExemptions.MayActivate`): включать можно панели ПРОЕКТА, шлюзы —
//       нет;
//   11) КЛЮЧИ ПУТЕЙ УНИКАЛЬНЫ. Из 140 элементов 45 имели ТОТ ЖЕ ключ, что и другие, — и второй
//       объект не проверялся НИКОГДА (перепоиск возвращал первый). Теперь при одноимённых соседях
//       в сегмент добавляется номер (`Switch_Фонарик#2`), вложенные канвасы не считаются дублями
//       (один объект — один раз), а оставшиеся совпадения печатаются в СТАРТ и списком в отчёте;
//   12) ПОКРЫТИЕ НАЗВАНО ЧИСЛОМ: `ПОКРЫТИЕ: проверено объектов M из найденных K` и, если есть,
//       `НЕ проверено X`. Потеря покрытия — самый опасный вид ошибки самопрогона: без этого числа
//       «всё сработало» относилось бы к меньшему набору, чем есть на экране, и выглядело зелёным.
//
//  ДОРАБОТКА ПО ЧЕТВЁРТОМУ ПРОГОНУ НА ПЛАНШЕТЕ 12.11.2026 (18 «нет изменений» из 35 проверенных):
//   13) СКРЫТЫЕ ПАНЕЛИ НЕ ВКЛЮЧАЮТСЯ СИЛОЙ ВООБЩЕ. `SetActive(true)` на скрытой панели давал
//       ФАЛЬШИВЫЕ проверки: панель команд AR заканчивается строкой `commandPanel.SetActive(false)`,
//       включённая силой панель не перестроена под состояние, и её вкладки «нажимались» впустую.
//       Теперь такой элемент получает `exempt=элемент в скрытой панели — сначала откройте её
//       штатной кнопкой` и ОТКЛАДЫВАЕТСЯ: видимая кнопка открытия добавит его в очередь сама
//       (пересборка списка), и он проверится в открытом, штатном состоянии. Панель, которая так и
//       не открылась, называется в отчёте отдельной строкой — это НАХОДКА, а не «без эффекта»;
//   14) ВТОРОЙ ПРОХОД по отложенным (исчезнувшие и скрытые) в самом конце, предел 60 с: AR-интерфейс
//       перестраивается, и часть путей к концу прогона СНОВА существует — их проверяют, а не
//       записывают «исчез» навсегда. ИТОГ пишется всегда;
//   15) СНИМОК УВИДЕЛ ПАНЕЛИ AR И ОБЩЕЕ СОСТОЯНИЕ ИНТЕРФЕЙСА: панель сообщений AR (`ArMessage`) с
//       ВИДИМОСТЬЮ и ТЕКСТОМ, панель команд, меню, счётчик созданных столов, строка состояния и
//       подсказка, а также счёт объектов по ВСЕМ активным канвасам (всего/активных) и отпечаток
//       выбранного узла дерева. Без этого честный ответ «плоскостей нет — ставить некуда» и показ
//       любой панели выглядели как молчание кнопки;
//   16) ИСКЛЮЧЕНИЕ ПО СОСТОЯНИЮ AR: при нуле найденных плоскостей действия постановки/создания
//       получают `exempt=нечего ставить: найденных плоскостей 0 (подтверждено состоянием AR)` —
//       с ФАКТИЧЕСКИМ числом, иначе «невозможно» не отличить от «сломалось».
//
//  ДОРАБОТКА ПО ПЯТОМУ ПРОГОНУ НА ПЛАНШЕТЕ 12.11.2026 (69 «нет изменений», разобраны все):
//   17) СНИМОК ЧИТАЕТ СТРОКУ СТАТУСА И ПОДСКАЗКУ. Целый класс кнопок НИЧЕГО не меняет, кроме
//       СООБЩЕНИЯ оператору («Переназначение клавиш появится позже — бинды не меняются»): они
//       пишут в строку статуса дока. Без неё работающие кнопки выглядели мёртвыми. В `effect=`
//       теперь «длина статуса: 0→42» и «статус изменён: «…»»;
//   18) СНИМОК ЧИТАЕТ СТАРТОВОЕ МЕНЮ и меню дока: показано/скрыто, открытый РАЗДЕЛ, число столов
//       и роботов, открытость меню. Нажатие раздела меняет экран меню — это и есть его работа;
//   19) ЗАКОННЫЕ «НИЧЕГО НЕ МЕНЯЮТ» — УЗКИМИ ПРАВИЛАМИ С ПРОВЕРКОЙ СОСТОЯНИЯ: (а) вкладка, которая
//       УЖЕ выбрана; (б) плашка `KvMenuBlocker`, когда меню не открыто; (в) строка дерева, которая
//       УЖЕ выбрана. Неактивная вкладка, открытое меню и невыбранная строка проверяются нажатием;
//   20) ВТОРОЙ ПРОХОД НАЗЫВАЕТ ПРИЧИНУ ПО КАЖДОМУ ЭЛЕМЕНТУ (`— путь не найден` / `— панель не
//       открыта` / `— проверен`) и итог по категориям — «обработано 0 из 32» больше ничего не
//       скрывает.
//
//  ДОРАБОТКА ПО ШЕСТОМУ ПРОГОНУ НА ПЛАНШЕТЕ 12.11.2026 (четыре класса ложных «нет изменений»):
//   21) ДОСТАВКА КЛИКА. Пять строк дерева дока получали «нет изменений» с `путь=onClick`: значит
//       `ExecuteEvents` не доставил клик до `KvTreeRow` (выбор делает ОН), и сработал запасной
//       `Button.onClick`, который у строки только завершает переименование. Теперь нажатие —
//       ПОЛНЫЙ клик (down → up → click), затем ПРЯМОЙ вызов обработчиков объекта тем же
//       интерфейсом, и только потом запасные пути. Порядок закреплён перечислением
//       `KvUiSweepPressPath` и проверяется тестом;
//   22) СТАРТОВОЕ МЕНЮ И ТУЛБАР: снимок читает `свёрнутых групп тулбара` (вкладка группы меняет
//       именно их), а «раздел меню уже открыт» и «закрывать нечего» стали УЗКИМИ исключениями с
//       проверкой фактического состояния панели;
//   23) ВОССТАНОВЛЕНИЕ ПАНЕЛЕЙ ПРОВЕРЯЕТСЯ ЯВНО: если состояние не вернулось, в журнал и ИТОГ идёт
//       предупреждение с названием панели — это скрытая причина ложных «нет эффекта» у следующих
//       элементов;
//   24) ПОТЕРЯ ПОКРЫТИЯ: во втором проходе, если полный путь не найден, элемент ищется по
//       УКОРОЧЕННОМУ ключу (единственное совпадение по префиксу; при неоднозначности — честный
//       отказ). Найденный по префиксу проверяется обычным порядком, и это видно в журнале.
//
//  ДОРАБОТКА ПО СЕДЬМОМУ ПРОГОНУ НА ПЛАНШЕТЕ 12.11.2026 (кнопки шапки панели дерева):
//   25) ОТКРЫТИЕ ПАНЕЛИ ПРОВЕРЯЕТСЯ ФАКТОМ. `ShowPanel(tree)` мог вернуть управление, а панель
//       остаться неактивной: тогда кнопки её шапки нажимались в выключенной иерархии,
//       `Button.OnPointerClick` молча выходил по `IsActive()`, и РАБОЧИЕ кнопки получали «нет
//       изменений». Теперь такой элемент честно попадает в «панель не открыта»;
//   26) ПЕРЕПОИСК ПОСЛЕ ПОДГОТОВКИ: `ShowPanel`/`Rebuild` могут пересобрать панель — ссылка на
//       кнопку устаревает, и нажатие уходит в мёртвый объект. После подготовки элемент находится
//       заново по пути;
//   27) ВОССТАНОВЛЕНИЕ ПАНЕЛЕЙ: шаги и их порядок вынесены в чистую `KvUiSweepPanelSig.RestoreSteps`
//       (сторона → рейл → свёрнутость → видимость), результат проверяется и печатается ВСЕГДА:
//       `ВОССТАНОВЛЕНИЕ ПАНЕЛЕЙ: не восстановлено N`. Плюс законные «нечего менять» с проверкой
//       состояния: `Close` у панели в рейле, `Collapse` у свёрнутой панели, стрелка строки без
//       детей, `ExpandAll`/`CollapseAll` на дереве, которое уже в этом состоянии.
//
//  ДОРАБОТКА ПО ПРОГОНУ В ШЛЕМЕ (VR/MR):
//   28) ДЕЙСТВИЯ, МЕНЯЮЩИЕ СЕССИЮ («Новый проект», «Загрузить проект», «Импорт проекта»), идут в
//       список «НАЖИМАТЬ В КОНЦЕ». На шлеме первым же элементом нажалось «Новый проект»: меню
//       закрылось, проект пересоздался, остальные пункты исчезли — из 70 элементов проверился ОДИН.
//       Кнопка при этом НЕ исключается: она рабочая, но её место — в конце;
//   29) ПАНЕЛЬ ШЛЕМА ОТКРЫВАЕТСЯ СВОИМ ШТАТНЫМ ПУТЁМ перед проверкой содержимого: `Rebuild` →
//       `KvXrStartMenu.Show()` (для панели меню) → `KvXrGroupPanel.SetArVisible(true)` (публичный
//       показ канваса панели). Состояние запоминается и возвращается после элемента. Без этого в VR
//       48 элементов из 70 оставались «в скрытой панели», и проверялся один.
//
//  ДОРАБОТКА ПО ПРОГОНУ В ШЛЕМЕ (сборка 22:40):
//   30) ПК-ОКНА В ШЛЕМЕ НЕ ПЕРЕЧИСЛЯЮТСЯ. Из 48 «исключений» 46 оказались элементами ЗАКРЫТЫХ
//       окон ПК-раскладки (`KvWorkbenchWindow` 30, `KvFeatureWindow` 12, `KvHintCard` 2, оболочка
//       ПК). В шлеме оператор их не видит: это интерфейс компьютера. Теперь в раскладках vr/mr они
//       печатаются ОДНОЙ сводной строкой (`ПК-ОКНА В ШЛЕМЕ: элементов N …`) и НЕ входят в счётчики
//       N/P/F/E. В ar/pc проверяются как раньше — правило только для шлема;
//   31) ГЛУБИНА ПАНЕЛИ ШЛЕМА = 3 и цепочка раскрывается штатными путями: иконка группы →
//       (`PressIndex`) → иконка экрана → пункты экрана, с возвратом на базовый уровень
//       (`RestoreBase`). Каждый уровень печатается строкой
//       `РАСКРЫТИЕ ПАНЕЛИ: уровень k · иконка «…» → пунктов n · новых в очереди m`, и если новых 0 —
//       это сказано прямо (значит цепочка не проходит, дело в `PressIndex`, а не в снимке).
//
//  ДОРАБОТКА ПО ПРОГОНУ В ШЛЕМЕ (сборка 23:58 — ЧИСТОЕ СТАРТОВОЕ МЕНЮ):
//   32) СТАРТОВОЕ МЕНЮ ШЛЕМА — ОТДЕЛЬНЫЙ ПРОХОД (`StartMenuPass`). В чистом состоянии весь экран
//       шлема — это стартовое меню (`MenuSec_*`, `MenuRow_*`), и нажатие раздела пересобирает меню
//       ЦЕЛИКОМ (`ClearIcons` уничтожает все иконки). В общем проходе пункты уничтожали друг друга:
//       VR — 143 найдено, 9 проверено, 123 «исчезло»; MR — 184 / 8 / 162. Показывать меню заново
//       после каждого нажатия мало: у строк в каждом разделе СВОИ подписи, поэтому путь `MenuRow_0`
//       начинал означать другой пункт. Теперь пункты меню не входят в общую очередь, а проверяются
//       ОТДЕЛЬНЫМ проходом в самом конце — по одному, и перед КАЖДЫМ меню ставится в то состояние,
//       в котором пункт был найден: открыто (`KvXrStartMenu.Show`) и на записанном разделе
//       (`KvXrGroupPanel.SelectStartSection` — тот же метод, что вызывает нажатие раздела). Ссылка
//       берётся заново по пути, номер иконки сверяется ПО ПОДПИСИ. Вторая фаза прохода открывает
//       ОСТАЛЬНЫЕ разделы и нажимает их строки: при сборе этих объектов не существовало вовсе, и
//       без второй фазы «десятки проверенных» в шлеме недостижимы. В ar/pc правило не действует;
//   33) РАЗДЕЛ, КОТОРЫЙ УЖЕ ОТКРЫТ, ПЕРЕД НАЖАТИЕМ ПЕРЕКЛЮЧАЕТСЯ НА СОСЕДНИЙ
//       (`KvUiSweepStartMenu.DifferentSection`): иначе нажатие раздела не меняет экран, и рабочая
//       кнопка получила бы «нет эффекта». Так эффект виден по факту, а не заявлен заранее;
//   34) ПУНКТ МЕНЮ ГОТОВИТСЯ БЕЗ `RestoreBase`. `RestoreBase` уводит панель на «иконки групп»
//       (`CloseScreen` у панели меню только скрывает меню, а следующий `CloseFan` переводит уровень
//       в `Groups`), после чего уровень не совпадал с ожидаемым и КАЖДЫЙ пункт меню получал
//       «не удалось подготовить». Теперь для уровня `StartMenu` панель показывается штатным путём
//       меню, а уровень остаётся прежним;
//   35) МЕНЮ, КОТОРОЕ НЕ ВЕРНУЛОСЬ, НАЗВАНО ПРЯМО: `ВОЗВРАТ МЕНЮ НЕ УДАЛСЯ после «…»` и
//       «проверено N из M». Молчаливое «3 из 12» выглядело бы как «а больше пунктов и не было».
//
//  ДОРАБОТКА ПО КРАСНОМУ ГЕЙТУ UI_SWEEP (12.11.2026, VR/MR: 209 найдено, 152 «исчезло»):
//   36) ВОССТАНОВЛЕНИЕ ЭКРАНА ПЕРЕД КАЖДЫМ ЭЛЕМЕНТОМ ПАНЕЛИ ШЛЕМА (паттерн `StartMenuPass`
//       распространен на иерархическую панель). Причина «исчез» была в самом устройстве
//       интерфейса: панель шлема пересобирает содержимое при ЛЮБОМ нажатии (`ClearIcons`),
//       открытое меню вообще гасит панель у руки (`KvXrStartMenu.Hide`), и пути остальных
//       элементов перестают существовать до конца обхода. Теперь у элемента, принадлежащего
//       панели (`PanelBound`), запоминается ЕГО уровень и ЦЕПОЧКА ШТАТНЫХ НАЖАТИЙ от базы
//       (иконка группы → иконка экрана, `KvUiSweepPanelNav.ChainFor`); когда путь не
//       находится, обход ПЕРЕД «исчез» возвращает панель на этот экран штатными путями
//       (`KvXrStartMenu.Show`/`Hide` для меню, `RestoreBase` + `PressIndex` для панели у руки,
//       `SetArVisible` для погашенного канваса), ждёт кадр пересборки и ищет путь заново —
//       ровно столько раз, сколько задано `KvUiSweepPanelNav.MaxAttempts`. Если экран так и
//       не открылся, элемент получает ЯВНУЮ причину `панель не открыта: <экран> — <деталь>`
//       (считается исключением, а не «исчез» и не «без эффекта»); тихий «исчез» остался
//       только там, где панели нет вовсе (например, интерфейс AR — там правило не действует);
//   37) СВОЙ РАЗДЕЛ КНОПКИ МЕНЮ — ЕЁ НОМЕР (`MenuSec_1` → 1), а не раздел, открытый при
//       сборе: иначе `DifferentSection(0) = 1` совпадал с нажимаемым разделом, нажатие шло на
//       уже открытый раздел и рабочая кнопка получала «нет изменений» (один из двух
//       «без эффекта» без причины в шлеме);
//   38) СТРОКА МЕНЮ С КОМАНДОЙ РЕЕСТРА ПОЛУЧАЕТ ПРИЧИНУ ТОЛЬКО ПО ФАКТУ РЕЕСТРА:
//       «Сменить робота» вызывает `robot.switch`, у которого `IsEnabled = роботов > 1`; строка
//       нажимается после удаления последнего робота, команда недоступна — и снимок не видит
//       ни одного признака (второй из двух «без эффекта» без причины). Причина
//       `команда … недоступна (состояние реестра)` даётся только когда `KvCommands` так и
//       отвечает; если команда включена, отсутствие эффекта остаётся настоящей находкой
//       (`без эффекта`), а не оправданием;
//   39) БЮДЖЕТЫ ВРЕМЕНИ ВЫШЕ (общий 600 с, второй проход 180 с, проход по меню 180 с): обход
//       «по одному элементу с восстановлением» дороже прежнего, но ОБХОД НЕ ДОЛЖЕН ОБОРВАТЬСЯ
//       по бюджету, не дойдя до конца — иначе вернётся молчаливое «не проверено».
//
//  ДОРАБОТКА ПО ПРОГОНУ 13.11.2026 (отчёт ar 12:14: 140 элементов, 60 сработало, 49 исключений,
//  31 «исчез», 0 «без эффекта»; правки A–D заказа владельца):
//   40) ЛИМИТ СБОРА СНЯТ (`MaxElements = int.MaxValue`): прежние 140 обрезали инвентарь AR
//       (41+ кнопка тулбара, динамические меню), и непроверенное не называлось ничем. Границу
//       держит бюджет времени, а его конец печатается честной строкой «ПРЕДЕЛ: …»;
//   41) ДОК-ПАНЕЛЬ ОТКРЫВАЕТСЯ ШТАТНОЙ КОМАНДОЙ ПЕРЕД ЭЛЕМЕНТОМ (`view.panel.settings` и т.п.),
//       независимо от раскладки в PlayerPrefs: команда → `ShowPanel` менеджера (сброс уехавшей
//       раскладки) → раскрытие свёрнутой панели, затем список ДОКРУЧИВАЕТСЯ к строке
//       (`ScrollDockTo`). Если панель открыть не удалось — элемент получает ЯВНУЮ причину
//       `панель не открыта: док-панель «…» — <факт>` и НЕ попадает ни в «исчез», ни в «без
//       эффекта» (ровно 31 «исчез» из отчёта 13.11 были путями `…/Dock_Настройки/…`);
//   42) НЕНАЖАТЫЙ ЭЛЕМЕНТ ВСЕГДА С ПРИЧИНОЙ: `ShouldPress == false` — решение самого прогона,
//       и без причины такой элемент считался «без эффекта», то есть прогон обвинял бы кнопку,
//       которую сам отказался нажимать (в чистом состоянии — `GateButton«РАЗРЕШИТЬ КАМЕРУ»`).
//       Причина считается ПО ПУТИ (`UnpressedReasonFor`), а не только по флагу сбора;
//   43) `uiVisible` ВОЗВРАЩАЕТСЯ В `Restore`: команда `ui.toggle` гасит оболочку целиком, и
//       раньше следующие 12 элементов `Cmd_*` проверялись в мире без интерфейса — их путей
//       там просто не существовало. Признак есть в снимке (`оболочка показана`), в решении
//       (`KvUiSweepUiVisible`) и в самом возврате;
//   44) СТРОКА «ПЕРЕМЕСТИТЬ РОБОТА» СНОВА СТРОИТСЯ в разделе «Робот» стартового меню шлема
//       (требование владельца 12.11.2026): подпись, действие и обработчик были, а строки в
//       `StartContentLabels` не было — пункт в шлеме не существовал.
//
//  ЧЕСТНАЯ ГРАНИЦА. Таймаут на элемент измеряется по ФАКТИЧЕСКОМУ времени: Unity не даёт прервать
//  вызов, который уже выполняется в главном потоке, поэтому «завис навсегда» виден как обрыв файла
//  отчёта сразу после строки `press=` (виновник назван), а «завис на 5 секунд» — как `ok=0 timeout`
//  с числом секунд. Об этом прямо сказано в шапке отчёта, а не умолчано.
// ================================================================================================

using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using KazistovVvAr;
using KazistovVvFeatures;
using KazistovVvUI;
using KazistovVvXr;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace KazistovVvDiagnostics
{
    // ============================================================================================
    //  ЧАСТЬ 1. ЧИСТОЕ ЯДРО — проверяется EditMode-тестами без сцены и без устройств.
    // ============================================================================================

    /// <summary>Вид интерактивного элемента. Имя попадает в отчёт как `type=…`.</summary>
    public enum KvUiSweepKind
    {
        Button = 0,
        Toggle = 1,
        Slider = 2,
        Dropdown = 3,
        InputField = 4,
        /// <summary>Иконка панели шлема: её строит код (`KvXrGroupPanel`), а не сцена.</summary>
        PanelIcon = 5
    }

    /// <summary>
    /// ИМЕНА И СТРОКИ, КОТОРЫЕ НУЖНЫ ОБОИМ СЛОЯМ. Здесь они в ОДНОМ месте, чтобы формат отчёта
    /// нельзя было «поправить» в обходе и забыть в тестах.
    /// </summary>
    public static class KvUiSweepNames
    {
        /// <summary>Имя вида элемента для отчёта (`Button`, `Toggle`, …, `PanelIcon`).</summary>
        public static string Kind(KvUiSweepKind kind)
        {
            switch (kind)
            {
                case KvUiSweepKind.Toggle: return "Toggle";
                case KvUiSweepKind.Slider: return "Slider";
                case KvUiSweepKind.Dropdown: return "Dropdown";
                case KvUiSweepKind.InputField: return "InputField";
                case KvUiSweepKind.PanelIcon: return "PanelIcon";
                default: return "Button";
            }
        }

        /// <summary>
        /// СТРОКА «ПЕРЕД НАЖАТИЕМ»: `press=<путь> type=<вид> индекс=<i> из <N>`.
        ///
        /// ЗАЧЕМ ОНА ОТДЕЛЬНО ОТ СТРОКИ ЭЛЕМЕНТА. Строка `element=…` печатается ПОСЛЕ нажатия.
        /// Если приложение зависло или ушло в фон внутри нажатия (а именно так и случилось на
        /// планшете: кнопка открыла системный экран настроек Android), в журнале не остаётся
        /// ничего, и «на чём встало» узнать неоткуда. `press=` печатается ДО вызова нажатия,
        /// поэтому виновник назван даже тогда, когда следующей строки уже не будет.
        /// </summary>
        public static string PressLine(string path, KvUiSweepKind kind, int index, int total)
        {
            var sb = new StringBuilder(96);
            sb.Append("[KvUiSweep] press=").Append(string.IsNullOrEmpty(path) ? "(без имени)" : path);
            sb.Append(" type=").Append(Kind(kind));
            sb.Append(" индекс=").Append(index.ToString(CultureInfo.InvariantCulture));
            sb.Append(" из ").Append(total.ToString(CultureInfo.InvariantCulture));
            return sb.ToString();
        }

        /// <summary>
        /// УСТОЙЧИВЫЙ ХЕШ СТРОКИ (FNV-1a). Нужен для отпечатков состояния: `string.GetHashCode()`
        /// в .NET рандомизирован между процессами, и отпечаток нельзя было бы сравнить в тесте с
        /// заранее известным значением.
        /// </summary>
        public static int StableHash(string text)
        {
            unchecked
            {
                int h = -2128831035;   // 2166136261 как int
                if (!string.IsNullOrEmpty(text))
                {
                    for (int i = 0; i < text.Length; i++)
                    {
                        h ^= text[i];
                        h *= 16777619;
                    }
                }
                return h;
            }
        }

        /// <summary>
        /// ИМЯ ОДНОГО СЕГМЕНТА ПУТИ С НОМЕРОМ СРЕДИ ОДНОИМЁННЫХ СОСЕДЕЙ.
        ///
        /// ЗАЧЕМ НОМЕР (найдено на планшете 12.11.2026, «путей-дублей 45»). Интерфейс строится
        /// кодом, и у соседей бывают ОДИНАКОВЫЕ имена («Row», «Switch», «Btn»). Тогда два разных
        /// объекта давали ОДИН ключ, и второй из них не проверялся НИКОГДА: перепоиск возвращал
        /// первый. Вердикт «всё сработало» относился бы к меньшему набору, чем есть на экране, —
        /// тихая потеря проверок, худший вид ошибки в самопрогоне. Поэтому при совпадении имён
        /// добавляется порядковый номер: `Body/Scroll/Content/Switch_Фонарик#2`.
        /// НОМЕР — ЧАСТЬ КЛЮЧА, ПОДПИСЬ — НЕТ.
        /// </summary>
        public static string Segment(string name, int sameNameCount, int ordinal)
        {
            if (string.IsNullOrEmpty(name)) return "(без имени)";
            if (sameNameCount <= 1) return name;
            int number = (ordinal < 0 ? 0 : ordinal) + 1;
            return name + "#" + number.ToString(CultureInfo.InvariantCulture);
        }

        /// <summary>
        /// КЛЮЧ ПОИСКА ЭЛЕМЕНТА ПО ПУТИ: путь БЕЗ ПОДПИСИ («A/B/Switch«Фонарик: вкл»» → «A/B/Switch»).
        ///
        /// ЗАЧЕМ ОТРЕЗАТЬ ПОДПИСЬ. Путь — единственный устойчивый способ найти элемент после того,
        /// как интерфейс перестроился и все объекты пересозданы (ссылка на `Selectable` к тому
        /// времени мертва). Но подпись МЕНЯЕТСЯ от самого нажатия: переключатель после клика пишет
        /// «Фонарик: вкл» вместо «Фонарик: выкл». Если бы подпись входила в ключ, элемент считался
        /// бы «исчезнувшим» РОВНО ПОСЛЕ того, как сработал, — то есть самопрогон обвинял бы
        /// работающую кнопку в исчезновении. Поэтому ключ — иерархия без подписи, а подпись
        /// остаётся только для ЧИТАЕМОСТИ строки отчёта.
        /// </summary>
        public static string KeyOf(string path)
        {
            if (string.IsNullOrEmpty(path)) return "";
            int at = path.IndexOf('«');
            return at < 0 ? path : path.Substring(0, at);
        }

        /// <summary>
        /// НАЧАЛО ТЕКСТА ДЛЯ ОТЧЁТА («статус изменён: «Переназначение клавиш…»»). Обрезает по
        /// границе слова и убирает переводы строк: строка отчёта должна оставаться одной строкой.
        /// </summary>
        public static string Preview(string text, int max)
        {
            if (string.IsNullOrEmpty(text)) return "";
            string flat = text.Replace('\n', ' ').Replace('\r', ' ').Trim();
            if (max <= 0 || flat.Length <= max) return flat;
            return flat.Substring(0, max) + "…";
        }

        /// <summary>
        /// УКОРОТИТЬ КЛЮЧ НА ОДИН СЕГМЕНТ: `A/B/C` → `A/B`. Пустая строка — короче некуда.
        /// </summary>
        public static string ShortenKey(string key)
        {
            string k = KeyOf(key);
            if (string.IsNullOrEmpty(k)) return "";
            int slash = k.LastIndexOf('/');
            return slash <= 0 ? "" : k.Substring(0, slash);
        }

        /// <summary>
        /// НАЙТИ ЖИВОЙ КЛЮЧ ПО УКОРОЧЕННОМУ — когда полный путь исчез после перестроения.
        ///
        /// Сначала ищется ТОЧНОЕ совпадение. Затем ключ укорачивается на сегмент за шагом, и
        /// берётся совпадение по префиксу — но ТОЛЬКО ЕСЛИ ОНО ЕДИНСТВЕННОЕ: нажать «похожий»
        /// объект хуже, чем честно сказать «не найден».
        /// </summary>
        public static string ResolveKey(string key, IList<string> liveKeys)
        {
            string full = KeyOf(key);
            if (string.IsNullOrEmpty(full) || liveKeys == null) return "";

            for (int i = 0; i < liveKeys.Count; i++)
                if (string.Equals(liveKeys[i], full, StringComparison.Ordinal)) return liveKeys[i];

            string shortened = ShortenKey(full);
            while (shortened.Length > 0)
            {
                string only = "";
                int matches = 0;
                for (int i = 0; i < liveKeys.Count; i++)
                {
                    string live = liveKeys[i];
                    if (string.IsNullOrEmpty(live)) continue;
                    if (live.Length <= shortened.Length + 1) continue;             // сам префикс — не объект
                    if (!live.StartsWith(shortened + "/", StringComparison.Ordinal)) continue;
                    matches++;
                    only = live;
                    if (matches > 1) break;                                        // неоднозначно
                }
                if (matches == 1) return only;
                shortened = ShortenKey(shortened);
            }
            return "";
        }
    }

    /// <summary>
    /// ОЧЕРЕДЬ ОБХОДА, УСТОЙЧИВАЯ К ПЕРЕСТРОЕНИЮ ИНТЕРФЕЙСА.
    ///
    /// ЗАЧЕМ ОТДЕЛЬНЫЙ КЛАСС (найдено на планшете 12.11.2026). Первый же переключатель панели
    /// настроек перестраивает её содержимое: объекты уничтожаются и создаются заново. Список
    /// ссылок, собранный ОДИН РАЗ в начале, после этого указывал на мёртвые объекты — и 45 из 140
    /// элементов подряд получили «не удалось подготовить: элемент уничтожен». Кнопки при этом
    /// работали: обвинение было ложным, а ложное обвинение хуже отсутствия проверки — оно
    /// заставляет «чинить» исправное и обесценивает настоящие находки.
    ///
    /// ЧТО ЗДЕСЬ. Обход идёт по ПУТЯМ (устойчивый ключ), а не по ссылкам. Очередь помнит, что уже
    /// проверено, и умеет ДОПОЛНЯТЬСЯ после пересбора интерфейса — не теряя непроверенных
    /// элементов и не проверяя дважды уже нажатые. Логика чистая: проверяется тестами без сцены.
    /// </summary>
    public class KvUiSweepQueue
    {
        private readonly List<string> order = new List<string>();
        private readonly HashSet<string> known = new HashSet<string>(StringComparer.Ordinal);
        private readonly HashSet<string> done = new HashSet<string>(StringComparer.Ordinal);
        /// <summary>Ярус каждого пути: обход идёт от 1 к 4, внутри яруса — в порядке появления.</summary>
        private readonly Dictionary<string, int> tiers = new Dictionary<string, int>(StringComparer.Ordinal);

        public KvUiSweepQueue() { }

        public KvUiSweepQueue(IEnumerable<string> initialPaths)
        {
            Merge(initialPaths);
        }

        /// <summary>ЯРУС ПУТИ (1 — открывающие, 2 — обычные, 3 — стартовое меню, 4 — разрушительные).</summary>
        public int TierOf(string path)
        {
            int value;
            return !string.IsNullOrEmpty(path) && tiers.TryGetValue(path, out value) ? value : 2;
        }

        /// <summary>Сколько элементов очередь знает всего (включая уже проверенные).</summary>
        public int Total { get { return order.Count; } }

        /// <summary>Сколько уже проверено.</summary>
        public int DoneCount
        {
            get
            {
                int n = 0;
                for (int i = 0; i < order.Count; i++) if (done.Contains(order[i])) n++;
                return n;
            }
        }

        /// <summary>Сколько осталось проверить.</summary>
        public int Count { get { return Total - DoneCount; } }

        /// <summary>
        /// Следующий непроверенный путь — СТРОГО ПО ЯРУСАМ: сначала все открывающие (они расширяют
        /// доступное), затем обычные, затем пункты стартового меню, и только в конце разрушительные
        /// и меняющие сессию. Внутри яруса порядок — тот, в котором элементы появились.
        /// </summary>
        public string Next()
        {
            for (int tier = 1; tier <= 4; tier++)
            {
                for (int i = 0; i < order.Count; i++)
                {
                    string path = order[i];
                    if (done.Contains(path)) continue;
                    if (TierOf(path) != tier) continue;
                    return path;
                }
            }
            return null;
        }

        /// <summary>Отметить элемент проверенным (повторно он не нажимается).</summary>
        public void Done(string path)
        {
            if (string.IsNullOrEmpty(path)) return;
            done.Add(path);
        }

        /// <summary>Уже проверен?</summary>
        public bool IsDone(string path)
        {
            return !string.IsNullOrEmpty(path) && done.Contains(path);
        }

        /// <summary>
        /// ДОПОЛНИТЬ ОЧЕРЕДЬ ПОСЛЕ ПЕРЕСБОРА ИНТЕРФЕЙСА. Уже известные пути не дублируются (иначе
        /// одна и та же кнопка нажималась бы дважды), непроверенные остаются на своих местах
        /// (иначе пересборка «съела» бы половину обхода), новые встают в конец.
        /// Возвращает число ДОБАВЛЕННЫХ.
        /// </summary>
        public int Merge(IEnumerable<string> freshPaths)
        {
            if (freshPaths == null) return 0;
            int added = 0;
            foreach (string path in freshPaths)
                added += Merge(path, 2);
            return added;
        }

        /// <summary>
        /// ДОБАВИТЬ ПУТЬ С ЯРУСОМ. 1 — добавлен, 0 — уже известен (повторно не нажимается).
        /// Ярус решает ПОРЯДОК: открывающие уходят вперёд, разрушительные — в самый конец, даже
        /// если элемент появился посреди обхода.
        /// </summary>
        public int Merge(string path, int tier)
        {
            if (string.IsNullOrEmpty(path)) return 0;
            if (!known.Add(path)) return 0;
            order.Add(path);
            int value = tier < 1 ? 1 : (tier > 4 ? 4 : tier);
            tiers[path] = value;
            return 1;
        }

        /// <summary>Сколько элементов в каждом ярусе (для строки СТАРТ).</summary>
        public int CountInTier(int tier)
        {
            int n = 0;
            for (int i = 0; i < order.Count; i++)
                if (TierOf(order[i]) == tier) n++;
            return n;
        }

        /// <summary>Все известные пути (для отчёта и диагностики).</summary>
        public IReadOnlyList<string> Paths { get { return order; } }
    }

    /// <summary>
    /// ОЖИДАНИЕ «ИНТЕРФЕЙС УСПОКОИЛСЯ» после нажатия.
    ///
    /// ЗАЧЕМ. Двух кадров не всегда хватало: переключатель панели настроек перестраивает её
    /// содержимое, и снимок «после» брался посреди перестроения — эффект терялся или приписывался
    /// не тому элементу. Ждать «на глаз» нельзя (вернём зависание), поэтому у ожидания ЖЁСТКИЙ
    /// предел: не дольше <see cref="MaxSeconds"/> секунд, даже если интерфейс так и не успокоился.
    /// </summary>
    public static class KvUiSweepSettle
    {
        /// <summary>ЖЁСТКИЙ ПРЕДЕЛ ожидания, секунды. Дольше — не ждём ни при каких условиях.</summary>
        public const float MaxSeconds = 1f;

        /// <summary>Сколько кадров подряд состояние должно не меняться, чтобы считать его устойчивым.</summary>
        public const int StableFrames = 2;

        /// <summary>
        /// ЖДАТЬ ЛИ ЕЩЁ ОДИН КАДР. Чистая функция — её и проверяет тест на «не висим».
        /// Ждём, если: элемент ещё не найден ИЛИ состояние меняется ИЛИ стабильных кадров мало;
        /// но ВСЕГДА перестаём ждать по пределу времени.
        /// </summary>
        public static bool ShouldWait(bool elementFound, int previousCount, int currentCount,
            int stableFrames, float elapsedSeconds)
        {
            if (elapsedSeconds >= MaxSeconds) return false;          // предел → выходим
            if (!elementFound) return true;                          // элемент ещё не появился
            if (previousCount != currentCount) return true;          // интерфейс ещё строится
            return stableFrames < StableFrames;                      // ждём N спокойных кадров
        }
    }

    /// <summary>
    /// СОСТОЯНИЕ ОДНОЙ DOCK-ПАНЕЛИ, СНЯТОЕ ДО/ПОСЛЕ НАЖАТИЯ.
    ///
    /// ЗАЧЕМ ЭТО ВООБЩЕ НУЖНО (найдено на планшете 12.11.2026). Кнопки шапки дока — «свернуть»
    /// (`Collapse`), «причалить» (`Dock`) и «закрыть в рейл» (`Close`) — РАБОЧИЕ: они вызывают
    /// `ToggleCollapsed`, `ToggleFloat`/`CycleDock` и `ToRail`. Но ни одна из них не СКРЫВАЕТ
    /// панель: она остаётся видимой, меняя только вид, сторону и размер. Снимок состояния их не
    /// видел и объявлял три живые кнопки мёртвыми. Отчёт, который обвиняет исправный интерфейс,
    /// хуже отсутствующего: он заставляет чинить то, что не сломано, и обесценивает настоящие
    /// находки.
    /// ЧТО СТАЛО: состояние панелей снимается по стороне, свёрнутости, рейлу, видимости и размеру,
    /// и попадает в отчёт числами («панель tree: свёрнута 0→1»).
    /// </summary>
    public struct KvUiSweepPanelState
    {
        /// <summary>Имя панели (`tree`, `properties`, `settings`, `hotkeys`).</summary>
        public string Id;
        /// <summary>Сторона пристыковки: 0 — лево, 1 — право, 2 — низ, 3 — плавающая.</summary>
        public int Side;
        /// <summary>Свёрнута (остался один заголовок).</summary>
        public int Collapsed;
        /// <summary>Убрана в боковую «полочку» (рейл).</summary>
        public int InRail;
        /// <summary>Панель показана.</summary>
        public int Shown;
        /// <summary>Ширина прямоугольника, квантованная (см. <see cref="KvUiSweepPanelSig.Quantize"/>).</summary>
        public int Width;
        /// <summary>Высота прямоугольника, квантованная.</summary>
        public int Height;
    }

    /// <summary>
    /// ОТПЕЧАТОК И РАЗЛИЧИЯ СОСТОЯНИЯ DOCK-ПАНЕЛЕЙ. Чистые функции: проверяются тестами без сцены.
    /// </summary>
    public static class KvUiSweepPanelSig
    {
        /// <summary>
        /// ШАГ КВАНТОВАНИЯ РАЗМЕРА, px. Размер берётся с точностью до 8 px намеренно: раскладка
        /// пересчитывается каждый кадр, и «1 px дребезга» выдавал бы вечное «есть эффект» —
        /// то есть снимок льстил бы кнопкам вместо того, чтобы обвинять их без причины. Реальные
        /// изменения от «свернуть» и «в рейл» — десятки и сотни пикселей.
        /// </summary>
        public const int SizeQuantum = 8;

        /// <summary>Размер в квантованных единицах (отрицательные и мусорные — 0).</summary>
        public static int Quantize(float pixels)
        {
            if (pixels <= 0f || float.IsNaN(pixels) || float.IsInfinity(pixels)) return 0;
            return (int)Math.Round(pixels / SizeQuantum, MidpointRounding.AwayFromZero);
        }

        /// <summary>
        /// ОТПЕЧАТОК НАБОРА ПАНЕЛЕЙ. Одинаковое состояние обязано давать ОДИН И ТОТ ЖЕ отпечаток —
        /// иначе признак «состояние панелей» менялся бы всегда, и прогон зеленел бы на мёртвых
        /// кнопках (анти-вакуум, проверяется тестом).
        /// </summary>
        public static int Fingerprint(IList<KvUiSweepPanelState> panels)
        {
            unchecked
            {
                int h = -2128831035;
                if (panels == null) return h;
                for (int i = 0; i < panels.Count; i++)
                {
                    KvUiSweepPanelState p = panels[i];
                    h = (h ^ KvUiSweepNames.StableHash(p.Id)) * 16777619;
                    h = (h ^ p.Side) * 16777619;
                    h = (h ^ p.Collapsed) * 16777619;
                    h = (h ^ p.InRail) * 16777619;
                    h = (h ^ p.Shown) * 16777619;
                    h = (h ^ p.Width) * 16777619;
                    h = (h ^ p.Height) * 16777619;
                }
                return h;
            }
        }

        /// <summary>
        /// ЧТО ИМЕННО ИЗМЕНИЛОСЬ В ПАНЕЛЯХ — числами: «панель tree: свёрнута 0→1; сторона 1→3».
        /// Пустая строка — состояние панелей не изменилось.
        /// </summary>
        public static string Describe(IList<KvUiSweepPanelState> before, IList<KvUiSweepPanelState> after)
        {
            if (before == null || after == null) return "";
            var sb = new StringBuilder(120);
            for (int i = 0; i < after.Count; i++)
            {
                KvUiSweepPanelState a = after[i];
                KvUiSweepPanelState b = Find(before, a.Id, i);
                string one = DescribeOne(a.Id, b, a);
                if (one.Length == 0) continue;
                if (sb.Length > 0) sb.Append("; ");
                sb.Append(one);
            }
            return sb.ToString();
        }

        /// <summary>
        /// ШАГИ ВОССТАНОВЛЕНИЯ СОСТОЯНИЯ ПАНЕЛИ — В ЕДИНОМ ПОРЯДКЕ. Порядок обязателен: `SetCollapsed`
        /// сбрасывает рейл, а `ToRail` сбрасывает свёрнутость, поэтому сначала сторона, потом рейл,
        /// потом свёрнутость, и только затем видимость. Логика чистая — её проверяет тест.
        /// </summary>
        public static IList<string> RestoreSteps(KvUiSweepPanelState before, KvUiSweepPanelState current)
        {
            var steps = new List<string>(4);
            if (before.Side != current.Side) steps.Add("side");
            if (before.InRail != current.InRail) steps.Add("rail");
            if (before.Collapsed != current.Collapsed) steps.Add("collapsed");
            if (before.Shown != current.Shown) steps.Add("shown");
            return steps;
        }

        /// <summary>Различия ОДНОЙ панели. `before` может быть «пустым» (панели не было).</summary>
        public static string DescribeOne(string id, KvUiSweepPanelState before, KvUiSweepPanelState after)
        {
            var sb = new StringBuilder(80);
            string name = string.IsNullOrEmpty(id) ? "панель" : "панель " + id;
            Part(sb, name, "сторона", before.Side, after.Side);
            Part(sb, name, "свёрнута", before.Collapsed, after.Collapsed);
            Part(sb, name, "в рейле", before.InRail, after.InRail);
            Part(sb, name, "видна", before.Shown, after.Shown);
            if (before.Width != after.Width) Part(sb, name, "ширина", before.Width, after.Width);
            if (before.Height != after.Height) Part(sb, name, "высота", before.Height, after.Height);
            return sb.ToString();
        }

        private static void Part(StringBuilder sb, string name, string what, int before, int after)
        {
            if (before == after) return;
            if (sb.Length > 0) sb.Append("; ");
            sb.Append(name).Append(": ").Append(what).Append(' ')
              .Append(before.ToString(CultureInfo.InvariantCulture)).Append('→')
              .Append(after.ToString(CultureInfo.InvariantCulture));
        }

        /// <summary>Панель по имени, иначе по номеру (набор панелей стабилен, но имя надёжнее).</summary>
        private static KvUiSweepPanelState Find(IList<KvUiSweepPanelState> list, string id, int fallbackIndex)
        {
            if (!string.IsNullOrEmpty(id))
            {
                for (int i = 0; i < list.Count; i++)
                    if (string.Equals(list[i].Id, id, StringComparison.Ordinal)) return list[i];
            }
            if (fallbackIndex >= 0 && fallbackIndex < list.Count) return list[fallbackIndex];
            return new KvUiSweepPanelState();
        }
    }


    /// <summary>
    /// ОДИН ПРОВЕРЕННЫЙ ЭЛЕМЕНТ. Строка отчёта собирается ЗДЕСЬ, а не в обходе: тогда формат
    /// один на всех и его можно проверить тестом (иначе формат «живёт» в трёх местах и в каждом
    /// свой).
    /// </summary>
    public class KvUiSweepElement
    {
        /// <summary>
        /// ПРИЧИНА «ЭЛЕМЕНТ ИСЧЕЗ». Формулировка обязательна и единая: «элемент уничтожен» —
        /// это утверждение о САМОМ ПРОГОНЕ (устаревшая ссылка), а не о кнопке. Выдавать его за
        /// «кнопка не работает» нельзя: на планшете так были обвинены 45 работающих переключателей
        /// панели настроек, потому что первый же из них перестроил панель и все ссылки умерли.
        /// </summary>
        public const string MissingReason = "элемент исчез после перестроения интерфейса (путь не найден)";

        /// <summary>Путь или имя элемента (для оператора: «ПанельНастроек/Кнопка VR»).</summary>
        public string Path = "";
        public KvUiSweepKind Kind = KvUiSweepKind.Button;
        /// <summary>Эффект есть (хотя бы один признак состояния изменился).</summary>
        public bool Ok;
        /// <summary>Что именно изменилось («панели: 2→3; команд выполнено: 7→8»).</summary>
        public string Effect = "";
        /// <summary>Причина исключения ("" — не исключение).</summary>
        public string ExemptReason = "";
        /// <summary>Элемент не уложился в отведённое время.</summary>
        public bool TimedOut;
        /// <summary>
        /// ЭЛЕМЕНТ ИСЧЕЗ: после перепоиска по пути и пересбора интерфейса его нет. Считается
        /// ОТДЕЛЬНЫМ числом в отчёте и НЕ попадает в «без эффекта» — иначе прогон обвинял бы
        /// кнопку в бездействии за то, что интерфейс перестроился.
        /// </summary>
        public bool Missing;
        /// <summary>Каким путём нажимали: `uGUI`, `onClick`, `isOn`, `value`, `PressIndex`…</summary>
        public string Method = "";

        /// <summary>Готовый элемент «исчез» — с обязательной причиной и пометкой для счётчика.</summary>
        public static KvUiSweepElement Vanished(string path, KvUiSweepKind kind)
        {
            return new KvUiSweepElement
            {
                Path = path,
                Kind = kind,
                Ok = false,
                Missing = true,
                Effect = MissingReason,
                Method = "не найден"
            };
        }

        /// <summary>Имя типа для отчёта (`Button`, `Toggle`, …, `PanelIcon`).</summary>
        public string KindName { get { return KvUiSweepNames.Kind(Kind); } }

        /// <summary>Это исключение из правила «нажатие обязано дать эффект»?</summary>
        public bool IsExempt { get { return !string.IsNullOrEmpty(ExemptReason); } }

        /// <summary>
        /// СТРОКА ОТЧЁТА ПО ЭЛЕМЕНТУ. Формат задан владельцем:
        /// `element=<путь> type=<вид> ok=<1|0> effect=<что изменилось> exempt=<причина|->`.
        /// Пометка `timeout` ставится сразу после `ok=` (элемент, который не уложился в 2 с),
        /// а `путь=` в конце называет СПОСОБ нажатия — требование «в отчёте укажи, какой путь
        /// использован», иначе «нажали настоящим путём» остаётся обещанием.
        /// </summary>
        public string Line
        {
            get
            {
                var sb = new StringBuilder(160);
                sb.Append("[KvUiSweep] element=").Append(string.IsNullOrEmpty(Path) ? "(без имени)" : Path);
                sb.Append(" type=").Append(KindName);
                sb.Append(" ok=").Append(Ok ? "1" : "0");
                if (TimedOut) sb.Append(" timeout");
                if (Missing) sb.Append(" исчез");
                sb.Append(" effect=").Append(string.IsNullOrEmpty(Effect) ? "нет изменений" : Effect);
                sb.Append(" exempt=").Append(string.IsNullOrEmpty(ExemptReason) ? "-" : ExemptReason);
                if (!string.IsNullOrEmpty(Method)) sb.Append(" путь=").Append(Method);
                return sb.ToString();
            }
        }
    }

    /// <summary>
    /// СНИМОК СОСТОЯНИЯ «ДО» И «ПОСЛЕ» нажатия. Набор признаков выбран так, чтобы покрыть то, что
    /// реально может измениться от нажатия: видимость панелей, содержимое оболочки, ключевые
    /// настройки (режим VR/MR, язык, комфорт), счётчик выполненных команд, число объектов сцены,
    /// число файлов (появилась запись/поза) и состояние панели шлема.
    ///
    /// ПОЧЕМУ ОТДЕЛЬНАЯ СТРУКТУРА, А НЕ «сравним всё подряд». Сравнивать `Transform`-деревья
    /// целиком дорого и шумно (перерисовался один пиксель — уже «эффект»). Здесь ровно те числа,
    /// которые оператор назвал бы «состояние». Каждое поле — ЦЕЛОЕ, поэтому различие видно без
    /// допусков и плавающих сравнений.
    /// </summary>
    public struct KvUiSweepSnapshot
    {
        /// <summary>Сколько dock-панелей оболочки показано.</summary>
        public int VisiblePanels;
        /// <summary>Сколько объектов построено в канвасе оболочки (`UiObjectCount`).</summary>
        public int UiObjects;
        /// <summary>Строк в дереве объектов.</summary>
        public int TreeRows;
        /// <summary>Строк в панели свойств.</summary>
        public int PropertyRows;
        /// <summary>Кнопок в тулбаре.</summary>
        public int ToolbarButtons;
        /// <summary>Точек траектории (нажатие «точка» обязано их прибавить).</summary>
        public int Points;
        /// <summary>Есть ли выделенный объект uGUI (открылся список/поле ввода — он получает фокус).</summary>
        public int SelectedObjects;
        /// <summary>Режим VR/MR (0 — VR, 1 — MR).</summary>
        public int ModeIndex;
        /// <summary>Номер текущего языка в списке `KvLoc.Languages` (−1 — не найден).</summary>
        public int Language;
        /// <summary>Комфорт: признак виньетки + сила в сотых (одно число, чтобы сравнение было точным).</summary>
        public int Comfort;
        /// <summary>
        /// ОБОЛОЧКА ИНТЕРФЕЙСА ПОКАЗАНА (0/1) — признак, который меняет команда `ui.toggle`
        /// («Показать/скрыть интерфейс»). Без него снимок не видит скрытия оболочки, а
        /// `Restore` не возвращает его — и следующие элементы проверяются в мире без интерфейса.
        /// </summary>
        public int UiVisible;
        /// <summary>Сколько команд выполнено за всё время (`KvCommands.ExecutedCount`).</summary>
        public int Commands;
        /// <summary>Сколько объектов в сцене (появился/исчез объект — эффект).</summary>
        public int SceneObjects;
        /// <summary>Сколько файлов в хранилище записей и поз (появилась запись — эффект).</summary>
        public int Files;
        /// <summary>Уровень панели шлема (`KvXrGroupPanel.Level`), −1 — панели нет.</summary>
        public int PanelLevel;
        /// <summary>Сколько иконок на панели шлема сейчас.</summary>
        public int PanelIcons;
        /// <summary>
        /// ОТПЕЧАТОК СОСТОЯНИЯ DOCK-ПАНЕЛЕЙ (сторона, свёрнутость, рейл, видимость, размер).
        ///
        /// ПОЧЕМУ ОН НУЖЕН, ХОТЯ «ПАНЕЛЕЙ ВИДНО» УЖЕ ЕСТЬ. Кнопки шапки дока («свернуть»,
        /// «причалить», «в рейл») панель НЕ скрывают — она остаётся видимой и меняет только вид,
        /// сторону и размер. Без этого поля три РАБОЧИЕ кнопки получали `ok=0 effect=нет
        /// изменений`, то есть самопрогон обвинял исправный интерфейс (найдено на планшете
        /// 12.11.2026). Подробная расшифровка изменений — в `KvUiSweepPanelSig.Describe`.
        /// </summary>
        public int PanelFingerprint;
        /// <summary>
        /// ПОДПИСЬ ПАНЕЛИ ШЛЕМА (уровень + иконки + раскрытая группа + страница + строка состояния).
        /// Нужна, чтобы «нажатие изменило только подпись или страницу» тоже считалось эффектом.
        /// </summary>
        public int PanelStateHash;

        // ---------------------------------------------------------------- настройки оболочки
        //
        // ЗАЧЕМ ОНИ ЗДЕСЬ (тот же принцип: «кнопка мертва» ≠ «мой снимок не видит эффекта»).
        // Переключатели панели настроек («Фонарик», «Автообновление дерева», «Фантомы траекторий»,
        // «Панель метрик», «Сингулярности», «Виртуальный геймпад»…) меняют НЕ интерфейс, а флаги
        // `KvSettings` — состояние, которое живёт в PlayerPrefs. Без этих полей снимок не видел бы
        // вообще ничего, и переключатель выглядел бы мёртвым, хотя он рабочий.

        /// <summary>Зона достижимости вкл/выкл (0/1).</summary>
        public int SetWorkspace;
        /// <summary>Ограничения суставов (0/1).</summary>
        public int SetJointLimits;
        /// <summary>Панель метрик (0/1).</summary>
        public int SetMetrics;
        /// <summary>Фонарик (0/1).</summary>
        public int SetFlashlight;
        /// <summary>Автообновление дерева моделей (0/1).</summary>
        public int SetAutoTree;
        /// <summary>Фантомы траекторий (0/1).</summary>
        public int SetPhantoms;
        /// <summary>Плотность интерфейса.</summary>
        public int SetDensity;
        /// <summary>Число рядов тулбара.</summary>
        public int SetToolbarRows;
        /// <summary>Раскладка тулбара.</summary>
        public int SetToolbarLayout;
        /// <summary>Компактный тулбар (0/1).</summary>
        public int SetToolbarCompact;
        /// <summary>Размер шрифта интерфейса.</summary>
        public int SetFontSize;
        /// <summary>Высокий контраст (0/1).</summary>
        public int SetHighContrast;
        /// <summary>Режим для дальтоников.</summary>
        public int SetColorBlind;
        /// <summary>Навигация клавиатурой (0/1).</summary>
        public int SetKeyboardNav;
        /// <summary>Геймпад-интерфейс (0/1).</summary>
        public int SetGamepadHud;
        /// <summary>Плашка ошибок (0/1).</summary>
        public int SetErrorPlate;
        /// <summary>Отпечаток темы оформления (режим + палитра).</summary>
        public int ThemeHash;

        // ---------------------------------------------------------------- панели AR (планшет)
        //
        // ЗАЧЕМ (планшет, сборка 11:21). В AR кнопка «Поставить» без найденной плоскости НЕ молчит:
        // она показывает оператору сообщение «плоскостей нет — ставить некуда» через панель
        // `ArMessage`. Снимок видел только панели дока, поэтому честный ответ кнопки выглядел как
        // «нет изменений», и рабочая кнопка попадала в дефекты.

        /// <summary>Панель сообщений AR показана (0/1).</summary>
        public int ArMessageVisible;
        /// <summary>Отпечаток текста сообщения — видно, что именно сказано оператору.</summary>
        public int ArMessageHash;
        /// <summary>Длина текста сообщения — читаемое число рядом с отпечатком.</summary>
        public int ArMessageLength;
        /// <summary>Панель команд AR открыта (0/1).</summary>
        public int ArCommandPanel;
        /// <summary>Меню AR открыто (0/1).</summary>
        public int ArMenu;
        /// <summary>Сколько кнопок в панели AR.</summary>
        public int ArButtons;
        /// <summary>Сколько столов создано из интерфейса планшета.</summary>
        public int ArTables;
        /// <summary>Отпечаток строки состояния и подсказки AR (реакция интерфейса на действие).</summary>
        public int ArStatusHash;
        /// <summary>Сколько плоскостей найдено прямо сейчас (фактическое состояние AR).</summary>
        public int ArPlanes;

        // ---------------------------------------------------------------- общий счёт объектов
        //
        // ЗАЧЕМ ПО ВСЕМ КАНВАСАМ, А НЕ ТОЛЬКО ПО ОБОЛОЧКЕ. Панели AR (`ArUiCanvas`), панель
        // сообщений, окна-попапы живут на СВОИХ канвасах. Показ/скрытие любой такой панели —
        // настоящий эффект нажатия, и без этих чисел он терялся.

        /// <summary>Сколько объектов во ВСЕХ активных канвасах сцены.</summary>
        public int UiObjectsAll;
        /// <summary>Сколько из них активно прямо сейчас (показ/скрытие панели меняет это число).</summary>
        public int UiObjectsActive;
        /// <summary>Отпечаток выбранного узла дерева (нажатие строки дерева меняет выбор).</summary>
        public int SelectedNodeHash;

        // ---------------------------------------------------------------- статус и меню дока
        //
        // ЗАЧЕМ (итерация 6 на планшете): большинство оставшихся «нет изменений» — кнопки, которые
        // ТОЛЬКО СООБЩАЮТ («Переназначение клавиш появится позже»). Они пишут в строку статуса, а
        // снимок её не читал — и работающие кнопки выглядели мёртвыми. Теперь любое сообщение
        // оператору это ЭФФЕКТ.

        /// <summary>Отпечаток строки статуса и подсказки дока (состояние + сообщение + курсор + тема).</summary>
        public int StatusHash;
        /// <summary>Длина строки статуса — читаемое число рядом с отпечатком.</summary>
        public int StatusLength;
        /// <summary>Меню дока открыто (0/1).</summary>
        public int MenuOpen;
        /// <summary>Стартовое меню шлема показано (0/1).</summary>
        public int StartMenuVisible;
        /// <summary>Открытый раздел стартового меню (номер).</summary>
        public int StartSection;
        /// <summary>Сколько столов видит стартовое меню.</summary>
        public int StartTables;
        /// <summary>Сколько роботов видит стартовое меню.</summary>
        public int StartRobots;
        /// <summary>Сколько групп тулбара свёрнуто (вкладка группы меняет именно это).</summary>
        public int ToolbarCollapsedGroups;
    }

    /// <summary>
    /// ПУТИ НАЖАТИЯ — В ПОРЯДКЕ ПРИМЕНЕНИЯ. Порядок важен и проверяется тестом: `ExecuteEvents`
    /// (события указателя) → ПРЯМОЙ вызов обработчиков объекта → `Button.onClick` → значение.
    ///
    /// ЗАЧЕМ ЯВНЫЙ ПОРЯДОК (итерация 7). У строки дерева выбор делает `KvTreeRow.OnPointerClick`, а
    /// `Button.onClick` только завершает переименование. Когда `ExecuteEvents` не доставил клик,
    /// прогон откатывался на `onClick` — и строка выглядела мёртвой, хотя оператор её нажимает и
    /// она выбирается. Прямой вызов того же интерфейса закрывает этот разрыв.
    /// </summary>
    public enum KvUiSweepPressPath
    {
        None = 0,
        PointerEvents = 1,
        DirectHandlers = 2,
        UnityEvent = 3,
        ValueToggle = 4,
        ValueSlider = 5,
        Select = 6
    }

    /// <summary>Имена путей нажатия для строки отчёта (`путь=…`).</summary>
    public static class KvUiSweepPressPathNames
    {
        /// <summary>Имя пути для отчёта.</summary>
        public static string Of(KvUiSweepPressPath path)
        {
            switch (path)
            {
                case KvUiSweepPressPath.PointerEvents: return "uGUI";
                case KvUiSweepPressPath.DirectHandlers: return "uGUI(прямой вызов)";
                case KvUiSweepPressPath.UnityEvent: return "onClick";
                case KvUiSweepPressPath.ValueToggle: return "isOn";
                case KvUiSweepPressPath.ValueSlider: return "value";
                case KvUiSweepPressPath.Select: return "select";
                default: return "нет пути";
            }
        }
    }

    /// <summary>
    /// ЯРУСЫ ОБХОДА — СТРУКТУРА, А НЕ СПИСОК СЛОВ.
    ///
    /// ЧТО БЫЛО (шлем, сборка 21:36). «Показать демо» — действие, МЕНЯЮЩЕЕ СЕССИЮ, но в список «в
    /// конец» оно не попало: список был по подписи, и его не хватило. Демо нажалось третьим,
    /// стартовое меню закрылось, и ВСЕ оставшиеся разделы меню «исчезли»: из 71 элемента проверился
    /// один. ЧТО СТАЛО: обход идёт строго по четырём ярусам, и ярус — ФУНКЦИЯ от пути, подписи и
    /// признака «открывает панель», а не догадка по словам. Правило проверяется тестом.
    /// </summary>
    public enum KvUiSweepTier
    {
        /// <summary>Ярус 1 — ОТКРЫВАЮЩИЕ: расширяют доступное, нажимаются первыми.</summary>
        Opener = 1,
        /// <summary>Ярус 2 — обычные видимые элементы (переключатели, вкладки, списки, ползунки).</summary>
        Ordinary = 2,
        /// <summary>Ярус 3 — ПУНКТЫ СТАРТОВОГО МЕНЮ: точка входа, любое действие меняет сессию.</summary>
        StartMenu = 3,
        /// <summary>Ярус 4 — РАЗРУШИТЕЛЬНЫЕ И МЕНЯЮЩИЕ СЕССИЮ: только в самом конце.</summary>
        Destructive = 4
    }

    /// <summary>ПРАВИЛА ЯРУСОВ. Чистые функции: проверяются тестами без сцены.</summary>
    public static class KvUiSweepTiers
    {
        /// <summary>
        /// ЯРУС ЭЛЕМЕНТА. Порядок проверок важен: меняющее сессию — первым (ярус 4), затем
        /// стартовое меню (ярус 3), затем «открывает панель» (ярус 1), иначе обычный (ярус 2).
        /// </summary>
        public static KvUiSweepTier TierOf(string path, string label, bool opensPanel)
        {
            if (IsDestructiveAction(path, label)) return KvUiSweepTier.Destructive;
            if (IsStartMenuItem(path, label)) return KvUiSweepTier.StartMenu;
            if (opensPanel) return KvUiSweepTier.Opener;
            return KvUiSweepTier.Ordinary;
        }

        /// <summary>
        /// ДЕЙСТВИЕ, КОТОРОЕ МЕНЯЕТ СЕССИЮ ИЛИ НЕОБРАТИМО: демо, новый/открыть/загрузить проект,
        /// удаление, сброс, очистка, запись, экспорт, выход.
        /// </summary>
        public static bool IsDestructiveAction(string path, string label)
        {
            string text = (path ?? "") + " «" + (label ?? "") + "»";
            string[] patterns =
            {
                "демо", "demo", "новый проект", "new project", "создать проект",
                "загрузить проект", "открыть проект", "импорт проект", "load project", "import project",
                "удал", "сброс", "очист", "запис", "экспорт", "выход", "выйти",
                "reset", "delete", "export", "record", "quit"
            };
            for (int i = 0; i < patterns.Length; i++)
                if (text.IndexOf(patterns[i], StringComparison.OrdinalIgnoreCase) >= 0) return true;
            return false;
        }

        /// <summary>
        /// ПУНКТ СТАРТОВОГО МЕНЮ ШЛЕМА. В шлеме меню живёт и на своём канвасе
        /// (`KvStartMenuCanvas`), и на панели (`KvXrGroupCanvas/MenuSec_*`), поэтому признаков два:
        /// канвас меню и имена его пунктов.
        /// </summary>
        public static bool IsStartMenuItem(string path, string label)
        {
            string text = (path ?? "") + " «" + (label ?? "") + "»";
            if (text.IndexOf("KvStartMenuCanvas", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (text.IndexOf("KvXrStartMenu", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (text.IndexOf("MenuSec_", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (text.IndexOf("MenuRow_", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (text.IndexOf("Menu_start", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            return false;
        }

        /// <summary>
        /// ОТКРЫВАЕТ ЛИ ЭЛЕМЕНТ ПАНЕЛЬ/ЭКРАН (ярус 1). Признаки смешанные — структурные и словарные:
        /// строка меню дока (её кнопки раскрывают выпадающие списки), иконки экранов панели шлема и
        /// подписи явного открытия («открыть», «команды», «настройки», «панель», «меню»).
        /// </summary>
        public static bool OpensPanel(string path, string label)
        {
            string text = (path ?? "") + " «" + (label ?? "") + "»";
            if (text.IndexOf("/MenuBar/", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (text.IndexOf("Icon_Screen", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (text.IndexOf("Screen_", StringComparison.OrdinalIgnoreCase) >= 0) return true;

            string[] patterns =
            {
                "открыть", "открывает", "open", "команды", "commands",
                "настройки", "settings", "панель", "panel", "меню", "menu"
            };
            for (int i = 0; i < patterns.Length; i++)
                if (text.IndexOf(patterns[i], StringComparison.OrdinalIgnoreCase) >= 0) return true;
            return false;
        }

        /// <summary>Имя яруса для отчёта.</summary>
        public static string Name(KvUiSweepTier tier)
        {
            switch (tier)
            {
                case KvUiSweepTier.Opener: return "открывающие";
                case KvUiSweepTier.StartMenu: return "стартовое меню";
                case KvUiSweepTier.Destructive: return "разрушительные";
                default: return "обычные";
            }
        }
    }

    /// <summary>
    /// ВОССТАНОВЛЕНИЕ КОНТЕКСТА: если до нажатия меню/панель были открыты, а после — закрылись,
    /// прогон обязан открыть их СНОВА штатным путём. Иначе следующие элементы «исчезают», и
    /// проверять становится нечего (именно это случилось после «Показать демо»).
    /// </summary>
    public static class KvUiSweepContext
    {
        /// <summary>Нужно ли восстановление: до нажатия было видно, после — нет.</summary>
        public static bool NeedsRestore(int before, int after)
        {
            return before != 0 && after == 0;
        }

        /// <summary>Строка отчёта о восстановлении контекста.</summary>
        public static string RestoreLine(string what, bool restored)
        {
            return "[KvUiSweep] КОНТЕКСТ: " + what + " " +
                   (restored ? "восстановлен штатным путём" : "НЕ восстановлен");
        }
    }

    /// <summary>
    /// ЭЛЕМЕНТЫ ПК-РАСКЛАДКИ, КОТОРЫХ В ШЛЕМЕ НЕ ВИДНО. Чистые функции.
    ///
    /// ЧТО БЫЛО (шлем, сборка 22:40). Из 48 «исключений» 46 оказались элементами ЗАКРЫТЫХ ОКОН
    /// ПК-раскладки: `KvWorkbenchWindow` («Верстак», 30), `KvFeatureWindow` («Палитра», 12),
    /// `KvHintCard` (2) и оболочка ПК. В шлеме оператор их не видит вовсе: это интерфейс
    /// компьютера. Считать их «исключениями прогона» значит раздувать отчёт и прятать настоящий
    /// вопрос «сколько элементов VR проверено».
    /// ЧТО СТАЛО: в раскладках vr/mr такие элементы НЕ перечисляются и НЕ входят в счётчики
    /// N/P/F/E — печатается ОДНА сводная строка с числом. В ar/pc всё проверяется как раньше.
    /// </summary>
    public static class KvUiSweepPcWindows
    {
        /// <summary>КОРНЕВЫЕ КАНВАСЫ ПК-ОБОЛОЧКИ: в шлеме их гасит сторож оверлея.</summary>
        private static readonly string[] pcCanvasRoots =
        {
            "KazistovVv_UI",
            "KazistovVvDockCanvas",
        };

        /// <summary>ОКНА ПК: живут и вне корневой оболочки, поэтому ищутся по имени компонента.</summary>
        private static readonly string[] pcWindowMarkers =
        {
            "KvWorkbenchWindow",
            "KvFeatureWindow",
            "KvHintCard",
            "KvFeatureCanvas",
        };

        /// <summary>ЭТО ЭЛЕМЕНТ ПК-ИНТЕРФЕЙСА (в шлеме не показывается)?</summary>
        public static bool IsPcOnly(string path)
        {
            if (string.IsNullOrEmpty(path)) return false;

            for (int i = 0; i < pcWindowMarkers.Length; i++)
                if (path.IndexOf(pcWindowMarkers[i], StringComparison.OrdinalIgnoreCase) >= 0) return true;

            string root = RootSegmentOf(path);
            for (int i = 0; i < pcCanvasRoots.Length; i++)
                if (string.Equals(root, pcCanvasRoots[i], StringComparison.OrdinalIgnoreCase)) return true;
            return false;
        }

        /// <summary>ПЕРВЫЙ СЕГМЕНТ ПУТИ (корневой канвас).</summary>
        public static string RootSegmentOf(string path)
        {
            string key = KvUiSweepNames.KeyOf(path);
            if (string.IsNullOrEmpty(key)) return "";
            int slash = key.IndexOf('/');
            return slash < 0 ? key : key.Substring(0, slash);
        }

        /// <summary>В ЭТОЙ РАСКЛАДКЕ ПК-ОКНА НЕ ПОКАЗЫВАЮТСЯ? Правило только для шлема.</summary>
        public static bool HiddenInLayout(string layout)
        {
            return string.Equals(layout, "vr", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(layout, "mr", StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>ВИД ПК-ЭЛЕМЕНТА для разбивки в сводной строке.</summary>
        public static string KindOf(string path)
        {
            if (string.IsNullOrEmpty(path)) return "оболочка ПК";
            if (path.IndexOf("KvWorkbenchWindow", StringComparison.OrdinalIgnoreCase) >= 0) return "KvWorkbenchWindow";
            if (path.IndexOf("KvFeatureWindow", StringComparison.OrdinalIgnoreCase) >= 0) return "KvFeatureWindow";
            if (path.IndexOf("KvHintCard", StringComparison.OrdinalIgnoreCase) >= 0) return "KvHintCard";
            return "оболочка ПК";
        }

        /// <summary>ОДНА СВОДНАЯ СТРОКА вместо десятков «элемент в скрытой панели».</summary>
        public static string SummaryLine(int total, int workbench, int feature, int hint, int shell)
        {
            if (total <= 0) return "";
            var sb = new StringBuilder(200);
            sb.Append("[KvUiSweep] ПК-ОКНА В ШЛЕМЕ: элементов ")
              .Append(total.ToString(CultureInfo.InvariantCulture))
              .Append(" не проверяются — это интерфейс компьютера, в шлеме он не показывается (")
              .Append("KvWorkbenchWindow ").Append(workbench.ToString(CultureInfo.InvariantCulture))
              .Append(", KvFeatureWindow ").Append(feature.ToString(CultureInfo.InvariantCulture))
              .Append(", KvHintCard ").Append(hint.ToString(CultureInfo.InvariantCulture))
              .Append(", оболочка ПК ").Append(shell.ToString(CultureInfo.InvariantCulture))
              .Append(")");
            return sb.ToString();
        }
    }

    /// <summary>
    /// СТАРТОВОЕ МЕНЮ ШЛЕМА — ОТДЕЛЬНЫЙ ПРОХОД.
    ///
    /// ЧТО БЫЛО (шлем, сборка 23:58, чистое состояние). Весь экран — это стартовое меню: разделы
    /// `MenuSec_*` и строки `MenuRow_*`. Нажатие раздела ПЕРЕСОБИРАЕТ меню целиком, поэтому все
    /// остальные пункты «исчезают»: 123 из 143 в VR и 162 из 184 в MR. Восстановление меню их не
    /// спасает: пересобранные объекты получают другие подписи строк, и один общий проход физически
    /// не может проверить 6 разделов, каждый из которых уничтожает остальные 5.
    /// ЧТО СТАЛО: в раскладках vr/mr пункты стартового меню НЕ нажимаются в общем проходе (одна
    /// сводная строка с числами), а проверяются ОТДЕЛЬНЫМ проходом по одному, с возвратом меню в
    /// записанный раздел перед каждым. Так разделы ПРОВЕРЕНЫ, а не потеряны. В ar/pc всё как было.
    ///
    /// ВАЖНО. Здесь только ЧИСТЫЕ функции: названия разделов передаются снаружи
    /// (`SectionTitles()` в рантайме). Так правила меню проверяются тестами без сцены, без шлема и
    /// без загрузки сборки проекта.
    /// </summary>
    public static class KvUiSweepStartMenu
    {
        /// <summary>Раскладка шлема (vr/mr) — только там меню меняет сессию.</summary>
        public static bool HelmetLayout(string layout)
        {
            return string.Equals(layout, "vr", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(layout, "mr", StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>
        /// ПУТЬ ВЕДЁТ В СТАРТОВОЕ МЕНЮ ШЛЕМА? Признаков два, потому что один и тот же пункт виден
        /// в отчёте по-разному: кнопка uGUI (`MenuSec_*`/`MenuRow_*` из `CreateIcon`) и пункт панели
        /// (`ПанельШлема/Стартовое меню/…` из `PanelPath`). «Стартовое меню» — это название УРОВНЯ
        /// панели (`KvXrGroupPanel.ScreenTitle`), то есть структурный признак, а не догадка по словам.
        /// </summary>
        public static bool IsHelmetMenuPath(string path)
        {
            if (string.IsNullOrEmpty(path)) return false;
            if (path.IndexOf("Стартовое меню", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (path.IndexOf("MenuSec_", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (path.IndexOf("MenuRow_", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            return path.IndexOf("Menu_start", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        /// <summary>
        /// РАЗДЕЛ меню? У кнопки uGUI в имени есть `MenuSec_*`. У пункта ПАНЕЛИ имени нет — там путь
        /// кончается ПОДПИСЬЮ раздела (`ПанельШлема/Стартовое меню/Стол`), поэтому подпись сверяется
        /// со списком названий разделов, который передаёт рантайм.
        /// </summary>
        public static bool IsSection(string path, IReadOnlyList<string> sectionTitles)
        {
            if (string.IsNullOrEmpty(path)) return false;
            if (path.IndexOf("MenuSec_", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (sectionTitles == null) return false;

            string last = LastSegment(path);
            if (last.Length == 0) return false;
            for (int i = 0; i < sectionTitles.Count; i++)
                if (string.Equals(last, sectionTitles[i], StringComparison.Ordinal)) return true;
            return false;
        }

        /// <summary>СТРОКА меню (`MenuRow_*`, `Menu_start.*`)? В меню всё, что не раздел, — строка.</summary>
        public static bool IsRow(string path, IReadOnlyList<string> sectionTitles)
        {
            if (string.IsNullOrEmpty(path)) return false;
            if (path.IndexOf("MenuRow_", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (path.IndexOf("Menu_start", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            if (path.IndexOf("Стартовое меню", StringComparison.OrdinalIgnoreCase) >= 0)
                return !IsSection(path, sectionTitles);
            return false;
        }

        /// <summary>ПОСЛЕДНИЙ ОТРЕЗОК ПУТИ без подписи в «ёлочках» (`…/Стол«Стол»` → `Стол`).</summary>
        public static string LastSegment(string path)
        {
            string key = KvUiSweepNames.KeyOf(path);
            if (string.IsNullOrEmpty(key)) return "";
            int slash = key.LastIndexOf('/');
            return slash < 0 ? key : key.Substring(slash + 1);
        }

        /// <summary>
        /// РАЗДЕЛ, С КОТОРОГО НАЖИМАТЬ ПРОВЕРЯЕМЫЙ РАЗДЕЛ. Если нажимать раздел, который УЖЕ
        /// открыт, экран не изменится, и рабочая кнопка получила бы «нет эффекта». Поэтому перед
        /// нажатием меню ставится на СОСЕДНИЙ раздел: тогда нажатие действительно меняет экран, и
        /// эффект виден по факту, а не по обещанию.
        /// </summary>
        public static int DifferentSection(int section, int count)
        {
            if (count <= 1) return 0;                       // менять не на что
            if (section < 0 || section >= count) return 0;   // номер вне раскладки — первый раздел
            return (section + 1) % count;
        }

        /// <summary>ОДНА СВОДНАЯ СТРОКА вместо десятков «исчез» в строке СТАРТА.</summary>
        public static string SummaryLine(int total, int sections, int rows)
        {
            if (total <= 0) return "";
            var sb = new StringBuilder(200);
            sb.Append("[KvUiSweep] СТАРТОВОЕ МЕНЮ ШЛЕМА: элементов ")
              .Append(total.ToString(CultureInfo.InvariantCulture))
              .Append(" меняют сессию (разделы ").Append(sections.ToString(CultureInfo.InvariantCulture))
              .Append(", строки ").Append(rows.ToString(CultureInfo.InvariantCulture))
              .Append(") — не нажимаются в общем проходе; проверяются отдельным проходом по одному");
            return sb.ToString();
        }

        /// <summary>СТРОКА СТАРТА ПРОХОДА: сколько пунктов будет проверено и по какому правилу.</summary>
        public static string PassLine(int total, int sections, int rows)
        {
            if (total <= 0) return "";
            var sb = new StringBuilder(180);
            sb.Append("[KvUiSweep] ПРОХОД ПО СТАРТОВОМУ МЕНЮ: пунктов ")
              .Append(total.ToString(CultureInfo.InvariantCulture))
              .Append(" (разделы ").Append(sections.ToString(CultureInfo.InvariantCulture))
              .Append(", строки ").Append(rows.ToString(CultureInfo.InvariantCulture))
              .Append(") — по одному, с возвратом меню в раздел перед каждым");
            return sb.ToString();
        }

        /// <summary>ИТОГ ПРОХОДА: проверено/не найдено/секунды — без этого «0 из 12» ничего не объясняет.</summary>
        public static string PassResultLine(int checkedNow, int total, int notFound, float seconds)
        {
            var sb = new StringBuilder(160);
            sb.Append("[KvUiSweep] СТАРТОВОЕ МЕНЮ: проверено ")
              .Append(checkedNow.ToString(CultureInfo.InvariantCulture)).Append(" из ")
              .Append(total.ToString(CultureInfo.InvariantCulture))
              .Append(" · не найдено ").Append(notFound.ToString(CultureInfo.InvariantCulture))
              .Append(" · за ").Append(seconds.ToString("0.0", CultureInfo.InvariantCulture)).Append(" с");
            return sb.ToString();
        }

        /// <summary>ЧЕСТНАЯ СТРОКА, если вернуть меню после нажатия не удалось.</summary>
        public static string RestoreFailed(string path)
        {
            return "[KvUiSweep] ВОЗВРАТ МЕНЮ НЕ УДАЛСЯ после «" + (path ?? "") +
                   "» — остальные пункты меню не проверены";
        }

        /// <summary>ПРИЧИНА «НЕ ПРОВЕРЕН» для пункта, который не появился после возврата раздела.</summary>
        public static string NotFoundReason(string path)
        {
            return "не нажимали — пункт не появился после возврата меню в раздел («" +
                   (path ?? "") + "»), нажимать нечего";
        }

        /// <summary>Причина, когда объекта меню в сцене нет вовсе.</summary>
        public const string NoMenuReason =
            "не нажимали — объекта стартового меню (KvXrStartMenu) в сцене нет";

        /// <summary>Причина, когда панель меню не нашлась.</summary>
        public const string NoPanelReason =
            "не нажимали — панель стартового меню не найдена";

        /// <summary>Причина, когда проход упёрся в свой предел времени.</summary>
        public const string BudgetReason =
            "не нажимали — предел времени прохода по стартовому меню истёк";

        /// <summary>Причина, когда меню не удалось вернуть на экран.</summary>
        public const string RestoreFailedReason =
            "не нажимали — меню не вернулось на экран после предыдущего нажатия";

        /// <summary>
        /// СВОЙ РАЗДЕЛ ЭЛЕМЕНТА МЕНЮ — ЕГО НОМЕР, а не раздел, открытый при сборе.
        ///
        /// ЧТО БЫЛО (шлем, отчёт 11.11.2026: `MenuSec_1«Робот»` — «нет изменений»). У кнопки
        /// `MenuSec_*` номер есть в ИМЕНИ, но проход по меню записывал для всех пунктов один и
        /// тот же `owner.StartSection` (раздел, открытый в момент сбора) и перед нажатием ставил
        /// `DifferentSection(записанный)`. При сборе в разделе 0 это давало `DifferentSection(0)
        /// = 1` — и кнопка раздела 1 нажималась на УЖЕ ОТКРЫТЫЙ раздел: экран не менялся, и
        /// рабочая кнопка получала «без эффекта». Теперь у раздела — собственный номер (из
        /// имени `MenuSec_N`, а у пункта панели — по подписи среди названий разделов), и перед
        /// нажатием всегда стоит СОСЕДНИЙ раздел.
        /// </summary>
        /// <returns>Номер раздела или −1, если элемент разделом не является.</returns>
        public static int OwnSection(string path, IReadOnlyList<string> sectionTitles)
        {
            if (string.IsNullOrEmpty(path)) return -1;

            string last = LastSegment(path);
            if (last.Length == 0) return -1;

            // КНОПКА uGUI: номер в имени (`MenuSec_2` → 2). Проверка на `MenuSec` обязательна:
            // без неё подпись «Проект2» получила бы номер из цифр подписи.
            if (last.IndexOf("MenuSec", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                int byName = KvUiSweepExemptions.TrailingNumber(last);
                return byName >= 0 ? byName : -1;
            }

            // ПУНКТ ПАНЕЛИ: имени нет, номер даёт подпись среди названий раскладки.
            if (sectionTitles != null)
            {
                for (int i = 0; i < sectionTitles.Count; i++)
                    if (string.Equals(last, sectionTitles[i], StringComparison.Ordinal)) return i;
            }
            return -1;
        }

        /// <summary>
        /// КОМАНДА РЕЕСТРА, КОТОРУЮ ВЫЗЫВАЕТ СТРОКА МЕНЮ (`""` — строка не вызывает команду).
        ///
        /// ЗАЧЕМ (второй «без эффекта» без причины в шлеме, отчёт 11.11.2026). «Сменить робота» →
        /// `InvokeMenuCommand("robot.switch")`, а у команды `IsEnabled = роботов &gt; 1`: строка
        /// нажимается ПОСЛЕ удаления последнего робота, команда недоступна, обработчик честно
        /// возвращается — и снимок не видит НИ ОДНОГО признака. Правило узкое: таблица ниже —
        /// это ПОДПИСИ строк, а команда всё равно сверяется с живым реестром
        /// (`KvUiSweepExemptions.CommandUnavailableReason`), поэтому выдуманная причина
        /// невозможна: нет подписи — нет правила, команда включена — нет причины.
        /// </summary>
        public static string RowCommandId(string path, string label)
        {
            string text = (path ?? "") + " «" + (label ?? "") + "»";
            for (int i = 0; i < RowCommands.Length; i += 2)
            {
                if (text.IndexOf(RowCommands[i], StringComparison.Ordinal) >= 0) return RowCommands[i + 1];
            }
            return "";
        }

        /// <summary>Пары «подпись строки → команда реестра» (плоский массив: подпись, команда, …).</summary>
        private static readonly string[] RowCommands =
        {
            "Сменить робота", "robot.switch"
        };
    }

    /// <summary>
    /// ВОССТАНОВЛЕНИЕ ЭКРАНА ПАНЕЛИ ШЛЕМА ПЕРЕД ПРОВЕРКОЙ ЭЛЕМЕНТА — ЧИСТЫЕ ПРАВИЛА.
    ///
    /// ЧТО БЫЛО (шлем, красный гейт UI_SWEEP: из 209 элементов 152 «исчезло»). Панель шлема
    /// иерархична (раздел → иконка группы → экран) и пересобирает содержимое при ЛЮБОМ нажатии
    /// (`ClearIcons`), а открытое меню вообще гасит панель у руки. Путь элемента, собранного на
    /// другом уровне, после пересборки не существует — обход откладывал такой элемент и во
    /// втором проходе честно писал «исчез». Кнопки при этом рабочие: проверять было нечего
    /// только потому, что обход не умел вернуть панель на нужный экран.
    ///
    /// ЧТО СТАЛО. У элемента панели запоминается ЕГО уровень и ЦЕПОЧКА ШТАТНЫХ НАЖАТИЙ от
    /// базы (`ChainFor`): базовый уровень — пустая цепочка, веер — подпись группы, экран —
    /// подпись его иконки. Обход проигрывает эту цепочку настоящими нажатиями панели, ждёт
    /// кадр пересборки и ищет путь заново; если за `MaxAttempts` экран не открылся — элемент
    /// получает ЯВНУЮ причину `панель не открыта: <экран> — <деталь>` (`NotOpenReason`), а не
    /// тихий «исчез». Здесь — только чистые функции: их и проверяет тест без сцены.
    /// </summary>
    public static class KvUiSweepPanelNav
    {
        /// <summary>
        /// СКОЛЬКО ПОПЫТОК ВОССТАНОВИТЬ ЭКРАН ОДНОГО ЭЛЕМЕНТА, прежде чем назвать причину.
        /// «Ограниченное число» обязано быть числом: одна попытка — хлипко, бесконечность —
        /// это уже не обход, а зависание.
        /// </summary>
        public const int MaxAttempts = 3;

        /// <summary>
        /// ЦЕПОЧКА ШТАТНЫХ НАЖАТИЙ ОТ БАЗЫ ДО УРОВНЯ (подписи иконок: сначала группа, потом
        /// экран). Пустой массив — уровень базовый, возвращаться не надо. `null` — восстановить
        /// штатными путями нечем (стартовое меню показывается своим `Show`, окно компьютера —
        /// своим окном; это решает рантайм, а здесь честно сказано «цепочки нет»).
        /// </summary>
        /// <param name="level">Уровень, на котором лежит элемент, в момент сбора.</param>
        /// <param name="openGroupIndex">Какая группа была раскрыта (для веера), −1 — неизвестно.</param>
        /// <param name="groupTitles">Подписи иконок групп на базовом уровне (по раскладке).</param>
        /// <param name="screenTitle">Подпись иконки экрана на базовом уровне («Состояние»…).</param>
        public static string[] ChainFor(KvXrPanelLevel level, int openGroupIndex,
            IList<string> groupTitles, string screenTitle)
        {
            if (level == KvXrPanelLevel.Groups) return new string[0];

            if (level == KvXrPanelLevel.GroupFan)
            {
                if (groupTitles == null || openGroupIndex < 0 || openGroupIndex >= groupTitles.Count)
                    return null;
                string group = groupTitles[openGroupIndex];
                return string.IsNullOrEmpty(group) ? null : new[] { group };
            }

            // МЕНЮ — НЕ ЦЕПОЧКА: `RestoreBase` его скрывает, а показ возможен только штатным
            // `KvXrStartMenu.Show` (иначе пункт меню проверялся бы на погашенной панели).
            if (level == KvXrPanelLevel.StartMenu) return null;

            // ЭКРАН: иконка с подписью экрана есть на базовом уровне у пяти экранов; у остальных
            // подписи нет — рантайм попробует штатный показ экрана самой панели, а если и это
            // не выйдет — элемент честно получит «панель не открыта».
            return string.IsNullOrEmpty(screenTitle) ? null : new[] { screenTitle };
        }

        /// <summary>ИМЯ УРОВНЯ ДЛЯ ПРИЧИНЫ («иконки групп», «веер», «экран «Состояние»»…).</summary>
        public static string LevelTitle(KvXrPanelLevel level, string screenTitle)
        {
            if (level == KvXrPanelLevel.Groups) return "иконки групп";
            if (level == KvXrPanelLevel.GroupFan) return "веер";
            if (level == KvXrPanelLevel.StartMenu) return "стартовое меню";
            if (!string.IsNullOrEmpty(screenTitle)) return "экран «" + screenTitle + "»";
            return "уровень " + ((int)level).ToString(CultureInfo.InvariantCulture);
        }

        /// <summary>
        /// ПРИЧИНА «ПАНЕЛЬ НЕ ОТКРЫТА» — ОБЯЗАНА НАЗЫВАТЬ ЭКРАН И ФАКТИЧЕСКУЮ ДЕТАЛЬ. Это
        /// исключение с проверяемым состоянием (считается `исключением` отчёта), а не «исчез»:
        /// «исчез» означал бы «путь не найден» и ничего не говорил бы о том, что обход ПЫТАЛСЯ
        /// вернуть экран и называет, какой именно не открылся.
        /// </summary>
        public static string NotOpenReason(string levelTitle, string detail)
        {
            string head = "панель не открыта: " +
                          (string.IsNullOrEmpty(levelTitle) ? "уровень панели" : levelTitle);
            return string.IsNullOrEmpty(detail) ? head : head + " — " + detail;
        }
    }

    /// <summary>
    /// РАЗЛИЧИЕ ДВУХ СНИМКОВ СЛОВАМИ. Пустая строка = эффекта НЕ БЫЛО, и это единственный
    /// правильный ответ на «кнопка ничего не сделала».
    /// </summary>
    public static class KvUiSweepDiff
    {
        /// <summary>
        /// Описание изменений между снимками. `""` — ни один признак не изменился.
        /// </summary>
        public static string Describe(KvUiSweepSnapshot before, KvUiSweepSnapshot after)
        {
            var sb = new StringBuilder(120);
            Append(sb, "панели", before.VisiblePanels, after.VisiblePanels);
            Append(sb, "элементы оболочки", before.UiObjects, after.UiObjects);
            // ВИДИМОСТЬ ОБОЛОЧКИ (дефект D4): «Показать/скрыть интерфейс» меняет именно её.
            Append(sb, "оболочка показана", before.UiVisible, after.UiVisible);
            Append(sb, "строки дерева", before.TreeRows, after.TreeRows);
            Append(sb, "строки свойств", before.PropertyRows, after.PropertyRows);
            Append(sb, "кнопок тулбара", before.ToolbarButtons, after.ToolbarButtons);
            Append(sb, "точек траектории", before.Points, after.Points);
            Append(sb, "выделение uGUI", before.SelectedObjects, after.SelectedObjects);
            Append(sb, "режим VR/MR", before.ModeIndex, after.ModeIndex);
            Append(sb, "язык", before.Language, after.Language);
            Append(sb, "комфорт", before.Comfort, after.Comfort);
            Append(sb, "команд выполнено", before.Commands, after.Commands);
            Append(sb, "объектов сцены", before.SceneObjects, after.SceneObjects);
            Append(sb, "файлов записи", before.Files, after.Files);
            Append(sb, "уровень панели шлема", before.PanelLevel, after.PanelLevel);
            Append(sb, "иконок на панели", before.PanelIcons, after.PanelIcons);
            // Изменение подписи панели шлема и состояния доков тоже эффект — иначе «нажатие
            // сменило только вид панели» выглядело бы как мёртвая кнопка.
            Append(sb, "подпись панели шлема", before.PanelStateHash, after.PanelStateHash);
            Append(sb, "отпечаток панелей дока", before.PanelFingerprint, after.PanelFingerprint);

            // ФЛАГИ ОБОЛОЧКИ. Переключатели панели настроек меняют именно их, а не вид панели:
            // без этих строк «Фонарик», «Фантомы», «Автообновление дерева» и им подобные
            // выглядели бы мёртвыми.
            Append(sb, "зона достижимости", before.SetWorkspace, after.SetWorkspace);
            Append(sb, "ограничения суставов", before.SetJointLimits, after.SetJointLimits);
            Append(sb, "панель метрик", before.SetMetrics, after.SetMetrics);
            Append(sb, "фонарик", before.SetFlashlight, after.SetFlashlight);
            Append(sb, "автообновление дерева", before.SetAutoTree, after.SetAutoTree);
            Append(sb, "фантомы траекторий", before.SetPhantoms, after.SetPhantoms);
            Append(sb, "плотность интерфейса", before.SetDensity, after.SetDensity);
            Append(sb, "рядов тулбара", before.SetToolbarRows, after.SetToolbarRows);
            Append(sb, "раскладка тулбара", before.SetToolbarLayout, after.SetToolbarLayout);
            Append(sb, "компактный тулбар", before.SetToolbarCompact, after.SetToolbarCompact);
            Append(sb, "размер шрифта", before.SetFontSize, after.SetFontSize);
            Append(sb, "высокий контраст", before.SetHighContrast, after.SetHighContrast);
            Append(sb, "режим для дальтоников", before.SetColorBlind, after.SetColorBlind);
            Append(sb, "навигация клавиатурой", before.SetKeyboardNav, after.SetKeyboardNav);
            Append(sb, "геймпад-интерфейс", before.SetGamepadHud, after.SetGamepadHud);
            Append(sb, "плашка ошибок", before.SetErrorPlate, after.SetErrorPlate);
            Append(sb, "тема оформления", before.ThemeHash, after.ThemeHash);

            // ПАНЕЛИ AR. Без этих строк честный ответ «плоскостей нет — ставить некуда» (панель
            // сообщений AR) выглядел бы как молчание кнопки.
            Append(sb, "сообщение AR показано", before.ArMessageVisible, after.ArMessageVisible);
            Append(sb, "текст сообщения AR", before.ArMessageHash, after.ArMessageHash);
            Append(sb, "длина сообщения AR", before.ArMessageLength, after.ArMessageLength);
            Append(sb, "панель команд AR", before.ArCommandPanel, after.ArCommandPanel);
            Append(sb, "меню AR", before.ArMenu, after.ArMenu);
            Append(sb, "кнопок в панели AR", before.ArButtons, after.ArButtons);
            Append(sb, "столов создано", before.ArTables, after.ArTables);
            Append(sb, "строка состояния AR", before.ArStatusHash, after.ArStatusHash);

            // ОБЩИЙ СЧЁТ ОБЪЕКТОВ ИНТЕРФЕЙСА И ВЫБОР В ДЕРЕВЕ: ловят показ/скрытие ЛЮБОЙ панели
            // на любом канвасе и смену выбранного узла — без них эти действия выглядели бы
            // «без эффекта».
            Append(sb, "объектов интерфейса", before.UiObjectsAll, after.UiObjectsAll);
            Append(sb, "активных объектов интерфейса", before.UiObjectsActive, after.UiObjectsActive);
            Append(sb, "выбранный узел дерева", before.SelectedNodeHash, after.SelectedNodeHash);

            // СТАТУС И МЕНЮ ДОКА: кнопки, которые «только сообщают», пишут именно сюда.
            Append(sb, "длина статуса", before.StatusLength, after.StatusLength);
            Append(sb, "текст статуса", before.StatusHash, after.StatusHash);
            Append(sb, "меню дока открыто", before.MenuOpen, after.MenuOpen);

            // СТАРТОВОЕ МЕНЮ ШЛЕМА: нажатие раздела переключает его экран.
            Append(sb, "стартовое меню показано", before.StartMenuVisible, after.StartMenuVisible);
            Append(sb, "раздел стартового меню", before.StartSection, after.StartSection);
            Append(sb, "столов в меню", before.StartTables, after.StartTables);
            Append(sb, "роботов в меню", before.StartRobots, after.StartRobots);
            Append(sb, "свёрнутых групп тулбара", before.ToolbarCollapsedGroups, after.ToolbarCollapsedGroups);
            return sb.ToString();
        }

        private static void Append(StringBuilder sb, string name, int before, int after)
        {
            if (before == after) return;
            if (sb.Length > 0) sb.Append("; ");
            sb.Append(name).Append(": ").Append(before.ToString(CultureInfo.InvariantCulture))
              .Append("→").Append(after.ToString(CultureInfo.InvariantCulture));
        }
    }

    /// <summary>
    /// ИТОГ ПРОГОНА: элементы, счётчики и две итоговые строки. Считать «успех» здесь, а не в
    /// обходе, — потому что правило успеха проверяется тестами, а обход проверяем только глазами.
    /// </summary>
    public class KvUiSweepRun
    {
        /// <summary>
        /// ПОРОГ: прогон, нашедший меньше элементов, НЕ СЧИТАЕТСЯ успехом. Иначе на пустой сцене
        /// (интерфейс не построился) «провалов ноль» означало бы «проверок ноль», и зелёный итог
        /// врал бы сильнее красного.
        /// </summary>
        public const int MinElements = 20;

        /// <summary>Макет, в котором шёл прогон: `vr`, `mr`, `ar`, `pc`.</summary>
        public string Layout = "pc";

        private readonly List<KvUiSweepElement> elements = new List<KvUiSweepElement>();

        /// <summary>Все проверенные элементы в порядке обхода.</summary>
        public IReadOnlyList<KvUiSweepElement> Elements { get { return elements; } }

        /// <summary>Сколько элементов проверено (N).</summary>
        public int Total { get { return elements.Count; } }

        /// <summary>Сработало (P): эффект есть и элемент НЕ в списке исключений.</summary>
        public int Worked
        {
            get
            {
                int n = 0;
                for (int i = 0; i < elements.Count; i++)
                {
                    KvUiSweepElement e = elements[i];
                    if (e != null && e.Ok && !e.IsExempt && !e.Missing) n++;
                }
                return n;
            }
        }

        /// <summary>Исключений (E): элементы, чей отказ объяснён явной причиной в коде.</summary>
        public int Exempted
        {
            get
            {
                int n = 0;
                for (int i = 0; i < elements.Count; i++)
                    if (elements[i] != null && elements[i].IsExempt) n++;
                return n;
            }
        }

        /// <summary>
        /// ИСЧЕЗЛО (M): элемент не найден по пути после перепоиска и пересбора интерфейса.
        /// ЭТО НЕ «БЕЗ ЭФФЕКТА»: интерфейс перестроился, и проверять стало нечего. Отдельное число
        /// нужно, чтобы прогон не обвинял кнопку за поведение панели (на планшете так были
        /// «обвинены» 45 работающих переключателей).
        /// </summary>
        public int Missing
        {
            get
            {
                int n = 0;
                for (int i = 0; i < elements.Count; i++)
                    if (elements[i] != null && elements[i].Missing) n++;
                return n;
            }
        }

        /// <summary>
        /// Без эффекта (F): нажали, эффекта нет, и причина НЕ заявлена заранее и элемент не исчез.
        /// Именно это число владелец считает дефектом. Тождество N = P + F + E + исчезло —
        /// проверяется тестом.
        /// </summary>
        public int NoEffect { get { return Total - Worked - Exempted - Missing; } }

        /// <summary>Сколько элементов не уложилось в отведённое время (для журнала).</summary>
        public int TimedOut
        {
            get
            {
                int n = 0;
                for (int i = 0; i < elements.Count; i++)
                    if (elements[i] != null && elements[i].TimedOut) n++;
                return n;
            }
        }

        /// <summary>
        /// СКОЛЬКО ЭЛЕМЕНТОВ БЫЛО НЕДОСТУПНО (`interactable=false`). Они попадают в «исключения»
        /// — нажать их нельзя в принципе, как и оператору. Но число печатается отдельно: кнопка,
        /// которая ВСЕГДА недоступна, — это дефект заполнения, и прятать его в общий счётчик
        /// исключений нельзя.
        /// </summary>
        public int Disabled
        {
            get
            {
                int n = 0;
                for (int i = 0; i < elements.Count; i++)
                    if (elements[i] != null &&
                        string.Equals(elements[i].ExemptReason, KvUiSweepExemptions.DisabledReason,
                            StringComparison.Ordinal))
                        n++;
                return n;
            }
        }

        /// <summary>
        /// ЭЛЕМЕНТ, НАЖАТИЕ КОТОРОГО ВЫПОЛНЯЕТСЯ ПРЯМО СЕЙЧАС (пусто — между нажатиями).
        /// Нужен ровно для одного: назвать виновника, если приложение ушло в фон или зависло
        /// ВНУТРИ нажатия. Без него в отчёте остаётся «сколько-то элементов проверено» и полная
        /// неизвестность о том, какой именно элемент всё сломал.
        /// </summary>
        public string PressingPath { get; private set; }

        /// <summary>Вид элемента, который нажимается сейчас.</summary>
        public KvUiSweepKind PressingKind { get; private set; }

        /// <summary>Причина прерывания ("" — прогон не прерывался).</summary>
        public string Interrupted { get; private set; }

        /// <summary>
        /// ЭЛЕМЕНТ, НА КОТОРОМ ПРЕРВАЛИСЬ (null — прервались между нажатиями). Обход обязан
        /// напечатать его строку `element=… ok=0 …`: «элемент попал в отчёт» — это значит, что
        /// тестировщик ВИДИТ его в списке, а не только в счётчике.
        /// </summary>
        public KvUiSweepElement InterruptedElement { get; private set; }

        /// <summary>Добавить элемент. Возвращает готовую строку отчёта (её же пишем в журнал).</summary>
        public string Add(KvUiSweepElement element)
        {
            if (element == null) return "";
            elements.Add(element);
            // Нажатие завершилось — «текущего» элемента больше нет.
            PressingPath = "";
            return element.Line;
        }

        /// <summary>
        /// НАЧАТЬ НАЖАТИЕ. Возвращает строку `press=…`, которую обход печатает ДО вызова нажатия.
        /// Именно эта строка остаётся последней в журнале, если приложение ушло в фон или зависло.
        /// </summary>
        public string BeginPress(string path, KvUiSweepKind kind, int index, int total)
        {
            PressingPath = path ?? "";
            PressingKind = kind;
            return KvUiSweepNames.PressLine(PressingPath, kind, index, total);
        }

        /// <summary>
        /// ПРЕРВАНО: приложение ушло в фон. Возвращает строку журнала; элемент, нажатие которого
        /// выполнялось, ПОПАДАЕТ В ОТЧЁТ как `ok=0` с причиной «приложение ушло в фон» — терять его
        /// нельзя, иначе виновник останется неизвестным, а прогон будет выглядеть «просто не
        /// дошедшим до конца».
        /// </summary>
        public string Interrupt(string why)
        {
            string reason = string.IsNullOrEmpty(why) ? "приложение ушло в фон" : why;
            if (!string.IsNullOrEmpty(Interrupted)) return "";   // второй сигнал не удваиваем

            Interrupted = reason;
            if (string.IsNullOrEmpty(PressingPath))
                return "[KvUiSweep] ПРЕРВАНО: " + reason +
                       " между элементами (нажатие в этот момент не выполнялось)";

            string guilty = PressingPath;
            var element = new KvUiSweepElement
            {
                Path = guilty,
                Kind = PressingKind,
                Ok = false,
                Effect = "ПРЕРВАНО: " + reason + " — нажатие, вероятно, открыло системный экран",
                Method = "не завершено"
            };
            elements.Add(element);
            InterruptedElement = element;
            PressingPath = "";
            return "[KvUiSweep] ПРЕРВАНО: " + reason + " на элементе «" + guilty + "» " +
                   "(нажатие, вероятно, открыло системный экран)";
        }

        /// <summary>Прогон признан успешным?</summary>
        public bool Succeeded { get { return string.IsNullOrEmpty(FailureReason); } }

        /// <summary>
        /// ПРИЧИНА ПРОВАЛА ПРОГОНА (пусто — прогон успешен).
        ///
        /// ПОРЯДОК ПРОВЕРОК ВЫБРАН ОСОЗНАННО. Сначала ПРЕРЫВАНИЕ (прогона не было вовсе —
        /// это главное), потом «элементов вообще нет» (интерфейс не построился), потом «есть без
        /// эффекта» — находка, ради которой прогон делается, — и только затем «меньше порога».
        /// Обратный порядок прятал бы главное: при 18 элементах, из которых 9 не сработали, отчёт
        /// сказал бы только «мало элементов», и владелец не увидел бы ни одной сломанной кнопки.
        /// </summary>
        public string FailureReason
        {
            get
            {
                if (!string.IsNullOrEmpty(Interrupted))
                    return "ПРЕРВАНО: " + Interrupted +
                           (Total > 0 ? " · успели проверить: " + Total : "");
                if (Total == 0)
                    return "панели не построены: интерактивных элементов 0 — проверять нечего";
                if (NoEffect > 0)
                    return "без эффекта " + NoEffect + " из " + Total +
                           " (вне списка разрешённых исключений)" +
                           (Total < MinElements ? " · элементов меньше порога " + MinElements : "");
                if (Total < MinElements)
                    return "найдено " + Total + " интерактивных элементов, порог " + MinElements +
                           " — такой прогон ничего не доказывает";
                return "";
            }
        }

        /// <summary>
        /// ИТОГ ВТОРОГО ПРОХОДА ПО КАТЕГОРИЯМ. Отдельная чистая строка: «обработано 0 из 32» ничего
        /// не объясняло — непонятно, почему ноль. Здесь названы ВСЕ три категории числами.
        /// </summary>
        public string RetrySummaryLine(int checkedNow, int hiddenNow, int notFound, float seconds)
        {
            var sb = new StringBuilder(160);
            sb.Append("[KvUiSweep] ВТОРОЙ ПРОХОД: проверено ")
              .Append(checkedNow.ToString(CultureInfo.InvariantCulture))
              .Append(" · панель не открыта ").Append(hiddenNow.ToString(CultureInfo.InvariantCulture))
              .Append(" · путь не найден ").Append(notFound.ToString(CultureInfo.InvariantCulture))
              .Append(" · время ").Append(seconds.ToString("0.0", CultureInfo.InvariantCulture));
            return sb.ToString();
        }

        /// <summary>
        /// ИТОГОВАЯ СТРОКА. Формат задан владельцем; все числа обязаны быть на месте —
        /// «элементов N · сработало P · без эффекта F · исключений E · исчезло M» (пятое число
        /// добавлено после планшета: перестроение интерфейса — не «без эффекта», но и не тишина).
        /// </summary>
        public string TotalLine(float seconds)
        {
            var sb = new StringBuilder(160);
            sb.Append("[KvUiSweep] ИТОГ: элементов ").Append(Total.ToString(CultureInfo.InvariantCulture));
            sb.Append(" · сработало ").Append(Worked.ToString(CultureInfo.InvariantCulture));
            sb.Append(" · без эффекта ").Append(NoEffect.ToString(CultureInfo.InvariantCulture));
            sb.Append(" · исключений ").Append(Exempted.ToString(CultureInfo.InvariantCulture));
            sb.Append(" · исчезло ").Append(Missing.ToString(CultureInfo.InvariantCulture));
            sb.Append(" · прогон=").Append(string.IsNullOrEmpty(Layout) ? "pc" : Layout);
            sb.Append(" · время=").Append(seconds.ToString("0.0", CultureInfo.InvariantCulture));
            return sb.ToString();
        }

        /// <summary>
        /// СТРОКА ПОКРЫТИЯ: «проверено объектов M из найденных K».
        ///
        /// ЗАЧЕМ ОТДЕЛЬНОЕ ЧИСЛО. Потеря покрытия — самый опасный вид ошибки самопрогона: если
        /// часть найденных элементов не проверена (оборвался предел, элемент исчез, путь совпал с
        /// чужим), вердикт «всё сработало» относится к МЕНЬШЕМУ набору, чем есть на экране, и
        /// выглядит при этом зелёным. Число `K − M` называет эту потерю прямо.
        /// </summary>
        public string CoverageLine(int found)
        {
            int checkedCount = Total;
            int missed = found > checkedCount ? found - checkedCount : 0;
            var sb = new StringBuilder(120);
            sb.Append("[KvUiSweep] ПОКРЫТИЕ: проверено объектов ")
              .Append(checkedCount.ToString(CultureInfo.InvariantCulture))
              .Append(" из найденных ").Append(found.ToString(CultureInfo.InvariantCulture));
            if (missed > 0) sb.Append(" · НЕ проверено ").Append(missed.ToString(CultureInfo.InvariantCulture));
            return sb.ToString();
        }

        /// <summary>Строка вердикта — отдельной строкой, чтобы формат ИТОГа остался неизменным.</summary>
        public string VerdictLine()
        {
            string why = FailureReason;
            if (why.Length != 0) return "[KvUiSweep] ВЕРДИКТ: НЕ успешно — " + why;

            var sb = new StringBuilder(160);
            sb.Append("[KvUiSweep] ВЕРДИКТ: успешно — эффект дали все ")
              .Append(Worked.ToString(CultureInfo.InvariantCulture)).Append(" элементов вне исключений");
            if (Exempted > 0) sb.Append(", исключений ").Append(Exempted.ToString(CultureInfo.InvariantCulture));
            if (Missing > 0)
                sb.Append(" · исчезло ").Append(Missing.ToString(CultureInfo.InvariantCulture))
                  .Append(" (интерфейс перестроился — эти проверять было нечем, см. строки «исчез»)");
            return sb.ToString();
        }
    }

    /// <summary>
    /// РАЗБОР ФЛАГОВ ЗАПУСКА. Отдельный класс — потому что именно здесь живёт защита
    /// «прогон не стартует в обычной работе», и её надо проверять тестом, а не надеждой.
    /// </summary>
    public static class KvUiSweepFlags
    {
        /// <summary>Extra интента / аргумент командной строки, включающий прогон.</summary>
        public const string ExtraKey = "kv_uisweep";

        /// <summary>Extra интента, задающий режим перед обходом (`vr` / `mr`).</summary>
        public const string ModeExtraKey = "kv_mode";

        /// <summary>
        /// ЗАПУСК РАЗРЕШЁН? Читаются ОБА источника: extra интента (Android) и аргументы
        /// командной строки (ПК/редактор). Флага нет — `false`, и приложение живёт как обычно.
        /// </summary>
        public static bool Requested(IDictionary<string, string> extras, string[] args)
        {
            string value = null;
            if (extras != null && extras.ContainsKey(ExtraKey)) value = extras[ExtraKey];
            if (IsOn(value)) return true;

            if (args != null)
            {
                for (int i = 0; i < args.Length; i++)
                {
                    string a = args[i];
                    if (string.IsNullOrEmpty(a)) continue;

                    // Форма «--kv_uisweep=1».
                    if (a.StartsWith("--" + ExtraKey + "=", StringComparison.OrdinalIgnoreCase))
                    {
                        if (IsOn(a.Substring(ExtraKey.Length + 3))) return true;
                        continue;
                    }

                    // Форма «-kv_uisweep 1» и «kv_uisweep 1».
                    string head = a.TrimStart('-', '/');
                    if (!string.Equals(head, ExtraKey, StringComparison.OrdinalIgnoreCase)) continue;
                    if (i + 1 < args.Length && IsOn(args[i + 1])) return true;
                    if (i + 1 >= args.Length) return true;   // флаг без значения — сам факт флага
                }
            }
            return false;
        }

        /// <summary>
        /// РЕЖИМ, КОТОРЫЙ НАДО ВЫСТАВИТЬ ПЕРЕД ОБХОДОМ: индекс `KvXrSettings`, либо −1 —
        /// «не трогать» (флага нет или он не распознан). Неизвестное значение НЕ считается
        /// запросом VR: молча включить не тот режим хуже, чем не включить никакой.
        /// </summary>
        public static int ModeIndexOf(string value)
        {
            if (string.IsNullOrEmpty(value)) return -1;
            string v = value.Trim().ToLowerInvariant();
            if (v == "vr" || v == "virtual" || v == "виртуальная") return KvXrSettings.ModeVr;
            if (v == "mr" || v == "mixed" || v == "смешанная") return KvXrSettings.ModeMr;
            return -1;
        }

        /// <summary>Значение режима из extra/аргументов (пусто — флага нет).</summary>
        public static string ModeRequested(IDictionary<string, string> extras)
        {
            string value;
            if (extras != null && extras.TryGetValue(ModeExtraKey, out value) && value != null) return value;
            return "";
        }

        /// <summary>«1», «true», «yes», «on», «да» — включено. Всё остальное (в том числе «0») — нет.</summary>
        public static bool IsOn(string value)
        {
            if (string.IsNullOrEmpty(value)) return false;
            string v = value.Trim().ToLowerInvariant();
            return v == "1" || v == "true" || v == "yes" || v == "on" || v == "да" || v == "y";
        }
    }

    /// <summary>
    /// РАЗРЕШЁННЫЕ ИСКЛЮЧЕНИЯ. Явный список с причиной у каждого: элемент, который физически не
    /// может сработать без железа, не должен ни краснить прогон, ни прятаться. Гейт
    /// (`Tools/ui-sweep-device.ps1`) требует, чтобы ВНЕ этого списка не было ни одного `ok=0`.
    /// </summary>
    public static class KvUiSweepExemptions
    {
        /// <summary>Правило исключения: по какому признаку и почему.</summary>
        public class Rule
        {
            /// <summary>Фрагмент пути/имени элемента (без учёта регистра).</summary>
            public string Pattern;
            /// <summary>Причина — её видит тестировщик в строке `exempt=…`.</summary>
            public string Reason;
            /// <summary>Нажимать ли элемент вообще (опасные — нет: они завершают прогон).</summary>
            public bool Press;
        }

        /// <summary>
        /// СПИСОК. Каждая строка — осознанное решение, а не «не получилось». Причины короткие:
        /// строка отчёта читается на телефоне через adb.
        /// </summary>
        private static readonly Rule[] rules =
        {
            new Rule
            {
                Pattern = "голос", Reason = "голосовой ввод: нужен микрофон и appId PICO", Press = true
            },
            new Rule
            {
                Pattern = "voice", Reason = "голосовой ввод: нужен микрофон и appId PICO", Press = true
            },
            new Rule
            {
                Pattern = "калибр", Reason = "калибровка: нужен реальный трекинг шлема", Press = true
            },
            new Rule
            {
                Pattern = "calib", Reason = "калибровка: нужен реальный трекинг шлема", Press = true
            },
            new Rule
            {
                Pattern = "сквозн", Reason = "сквозной вид: нужна камера устройства", Press = true
            },
            new Rule
            {
                Pattern = "passthrough", Reason = "сквозной вид: нужна камера устройства", Press = true
            },
            new Rule
            {
                Pattern = "кист", Reason = "трекинг кистей: нужен датчик рук шлема", Press = true
            },
            new Rule
            {
                Pattern = "hand track", Reason = "трекинг кистей: нужен датчик рук шлема", Press = true
            },
            new Rule
            {
                Pattern = "перчатк", Reason = "трекинг кистей: нужен датчик рук шлема", Press = true
            },
            new Rule
            {
                Pattern = "вибро", Reason = "виброотклик: нужен контроллер в руке", Press = true
            },
            new Rule
            {
                Pattern = "haptic", Reason = "виброотклик: нужен контроллер в руке", Press = true
            },

            // ОПАСНЫЕ ДЛЯ ПРОГОНА: нажатие «Выход» завершает приложение раньше итоговой строки,
            // и прогон выглядит как «завис». Поэтому такие элементы НЕ нажимаются, но и не
            // прячутся: они остаются в отчёте с причиной.
            new Rule
            {
                // НАЙДЕНО НА УСТРОЙСТВЕ 12.11.2026: прогон нажал «Выйти из приложения» и завершил
                // приложение — правило знало «Выход», но не «Выйти». Формулировок у выхода много,
                // и каждая новая означала бы, что прогон убивает себя. Поэтому здесь ловится КОРЕНЬ:
                // «выйти», «выход», плюс формы «покид»/«заверш».
                Pattern = "выйти", Reason = "выход: нажатие завершает прогон, проверяется вручную",
                Press = false
            },
            new Rule
            {
                Pattern = "выход из приложения", Reason = "выход: нажатие завершает прогон, проверяется вручную",
                Press = false
            },
            new Rule
            {
                Pattern = "закрыть приложение", Reason = "выход: нажатие завершает прогон, проверяется вручную",
                Press = false
            },
            new Rule
            {
                Pattern = "quit", Reason = "выход: нажатие завершает прогон, проверяется вручную",
                Press = false
            },
            // ПРОСТО «Выход» — раздел стартового меню шлема (`MenuSec_5«Выход»`): по коду он ведёт
            // к `Application.Quit()`. Нажатие оборвало бы прогон, поэтому проверяется вручную.
            new Rule
            {
                Pattern = "«выход»",
                Reason = "выход: нажатие может завершить приложение — проверяется вручную",
                Press = false
            },
        };

        /// <summary>Причина для «элемент недоступен» — отдельная формулировка, она про состояние, а не про железо.</summary>
        public const string DisabledReason = "элемент недоступен (interactable=false)";

        /// <summary>
        /// ПРИЧИНА ДЛЯ ЭЛЕМЕНТОВ СИСТЕМНОГО ШЛЮЗА (предполётной заглушки).
        ///
        /// ЧТО БЫЛО (планшет, сборка 10:45). Первым же элементом прогон нажал
        /// `KvArCameraGateCanvas/GatePanel/GateButton«РАЗРЕШИТЬ КАМЕРУ»` — кнопку, которая вызывает
        /// СИСТЕМНЫЙ диалог разрешений Android. Приложение ушло в фон, сторож фокуса честно
        /// прервал прогон — и 139 элементов из 140 не проверились НИКОГДА.
        /// ЧЕМ ЭТО ПЛОХО. Заглушка — не интерфейс оператора, а системный шлюз: проверять её
        /// нажатием бессмысленно (её «работа» — увести приложение из себя) и вредно (обрывает
        /// прогон). Поэтому такие элементы пропускаются ЦЕЛИКОМ — с причиной в отчёте.
        ///
        /// ВАЖНО: ЭТИ ПРАВИЛА ДЕЙСТВУЮТ ВСЕГДА, независимо от принадлежности панелям проекта.
        /// `KvArCameraGateCanvas` создаётся кодом проекта, и по признаку «свой» он считался бы
        /// штатной панелью — а он шлюз.
        /// </summary>
        public const string GateReason =
            "системный шлюз (разрешения/предполётная заглушка): нажатие уводит приложение в системный диалог";

        /// <summary>Признаки системного шлюза — по пути элемента (включая подпись).</summary>
        private static readonly string[] gatePatterns =
        {
            "KvArCameraGateCanvas",
            "GatePanel",
            "GateButton",
            "разрешить камеру",
            "разрешение камеры",
            "allow camera",
            "grant camera",
            "grant permission",
        };

        /// <summary>ЭТО ЭЛЕМЕНТ СИСТЕМНОГО ШЛЮЗА? Чистая функция по строке пути.</summary>
        public static bool IsGatePath(string path)
        {
            if (string.IsNullOrEmpty(path)) return false;
            for (int i = 0; i < gatePatterns.Length; i++)
            {
                string pattern = gatePatterns[i];
                if (string.IsNullOrEmpty(pattern)) continue;
                if (path.IndexOf(pattern, StringComparison.OrdinalIgnoreCase) >= 0) return true;
            }
            return false;
        }

        /// <summary>
        /// МОЖНО ЛИ ВКЛЮЧИТЬ СКРЫТУЮ ПАНЕЛЬ, чтобы добраться до её элементов.
        ///
        /// ОБЩЕЕ ПРАВИЛО (планшет, сборка 11:21): СКРЫТЫЕ ПАНЕЛИ НЕ ВКЛЮЧАЮТСЯ ВООБЩЕ.
        /// Принудительное `SetActive(true)` создавало ФАЛЬШИВЫЕ ПРОВЕРКИ: панель команд AR
        /// заканчивается строкой `commandPanel.SetActive(false)`, и включённая силой панель не
        /// перестроена под текущее состояние — её вкладки «нажимались» и не давали эффекта, хотя
        /// виноваты были не вкладки. Штатный путь — нажать ВИДИМУЮ кнопку, которая панель
        /// открывает; её элементы появятся в обходе сами (пересборка списка).
        /// Метод оставлен как ЯВНОЕ правило: `MayActivate` возвращает false всегда, и это видно
        /// в коде, а не спрятано в комментарии.
        /// </summary>
        public static bool MayActivate(string panelPath)
        {
            return false;
        }

        /// <summary>
        /// ПРИЧИНА ДЛЯ ЭЛЕМЕНТА В СКРЫТОЙ ПАНЕЛИ. Честнее имитации открытия: элемент не
        /// проверялся, и это названо, а не выдано за «кнопка не работает».
        /// </summary>
        public const string HiddenPanelReason =
            "элемент в скрытой панели — сначала откройте её штатной кнопкой";

        /// <summary>
        /// ЗАКОННОЕ «НИЧЕГО НЕ МЕНЯЕТ»: НАЖАТИЕ НА УЖЕ ВЫБРАННУЮ ВКЛАДКУ.
        ///
        /// Правило УЗКОЕ и с ПРОВЕРКОЙ ФАКТИЧЕСКОГО СОСТОЯНИЯ: исключение даётся только когда
        /// элемент — сегмент переключателя и он УЖЕ активен. Неактивная вкладка проверяется
        /// нажатием как обычно, иначе правило скрыло бы настоящий дефект.
        /// </summary>
        public const string AlreadyActiveTabReason = "вкладка уже выбрана — нажатие не меняет состояние";

        /// <summary>
        /// ЗАКОННОЕ «НИЧЕГО НЕ МЕНЯЕТ»: НАЖАТИЕ НА УЖЕ ВЫБРАННУЮ СТРОКУ ДЕРЕВА.
        /// `KvTreeView.Select(node)` вызывает `onSelect(node)` и при повторном нажатии на тот же
        /// узел: выбор не меняется, свойства пересобираются тем же содержимым. Правило узкое и с
        /// проверкой фактического выбора (`ui.SelectedNode == row.Node`).
        /// </summary>
        public const string TreeRowAlreadySelectedReason = "строка дерева уже выбрана — нажатие не меняет выбор";

        /// <summary>
        /// ЗАКОННОЕ «НИЧЕГО НЕ МЕНЯЕТ»: НАЖАТИЕ НА УЖЕ ОТКРЫТЫЙ РАЗДЕЛ СТАРТОВОГО МЕНЮ.
        /// `KvXrGroupPanel.SelectStartSection` пересобирает меню тем же разделом — состояние не
        /// меняется. Правило узкое и с проверкой фактического раздела.
        /// </summary>
        public const string StartSectionAlreadyOpenReason = "раздел меню уже открыт — нажатие не меняет экран";

        /// <summary>ЗАКОННОЕ «НИЧЕГО НЕ МЕНЯЕТ»: «Закрыть», когда закрывать нечего.</summary>
        public const string NothingToCloseReason = "закрывать нечего: экран не открыт — нажатие ничего не меняет";

        // ------------------------------------------------ законные «нечего менять» (состояние)

        /// <summary>ЗАКОННОЕ «НИЧЕГО НЕ МЕНЯЕТ»: кнопка панели, которая УЖЕ в целевом состоянии.</summary>
        public const string PanelAlreadyInStateReason = "панель уже в этом состоянии — нажатие ничего не меняет";

        /// <summary>ЗАКОННОЕ «НИЧЕГО НЕ МЕНЯЕТ»: стрелка строки БЕЗ дочерних узлов.</summary>
        public const string LeafRowReason = "у строки нет вложенных узлов — раскрывать нечего";

        /// <summary>ЗАКОННОЕ «НИЧЕГО НЕ МЕНЯЕТ»: дерево уже полностью раскрыто / свёрнуто.</summary>
        public const string TreeAlreadyInStateReason = "дерево уже в этом состоянии — нажатие ничего не меняет";

        /// <summary>
        /// ПРИЧИНА ДЛЯ КНОПКИ ШАПКИ ПАНЕЛИ, ЕСЛИ ОНА УЖЕ В ЦЕЛЕВОМ СОСТОЯНИИ.
        ///
        /// ПОЧЕМУ ТОЛЬКО `Close` И `Collapse`. По коду: `Close` → `ToRail()`, а он просто ставит
        /// `InRail = true` — на уже убранной в рейл панели это НИЧЕГО не меняет. А `Collapse` →
        /// `ToggleCollapsed()` и `Dock` → `ToggleFloat()` — это ПЕРЕКЛЮЧАТЕЛИ: они меняют
        /// состояние ВСЕГДА, поэтому «уже в состоянии» для них невозможно, и правило им не даётся
        /// (иначе исключение скрыло бы настоящий дефект).
        /// </summary>
        public static string PanelHeaderAlreadyInStateReasonFor(string elementName, bool collapsed, bool inRail)
        {
            if (string.IsNullOrEmpty(elementName)) return "";
            if (elementName.IndexOf("Close", StringComparison.OrdinalIgnoreCase) >= 0 && inRail)
                return PanelAlreadyInStateReason;
            if (elementName.IndexOf("Collapse", StringComparison.OrdinalIgnoreCase) >= 0 && collapsed)
                return PanelAlreadyInStateReason;
            return "";
        }

        /// <summary>Причина для стрелки строки без детей или `""`.</summary>
        public static string LeafRowReasonFor(bool hasChildren)
        {
            return hasChildren ? "" : LeafRowReason;
        }

        /// <summary>
        /// Причина для `ExpandAll`/`CollapseAll`, когда менять нечего, или `""`.
        /// `expanded` — сколько узлов раскрыто, `expandable` — сколько вообще можно раскрыть.
        /// </summary>
        public static string TreeAlreadyInStateReasonFor(string elementName, int expanded, int expandable)
        {
            if (string.IsNullOrEmpty(elementName)) return "";
            if (expandable <= 0) return "";                       // раскрывать нечего в принципе
            if (elementName.IndexOf("ExpandAll", StringComparison.OrdinalIgnoreCase) >= 0 &&
                expanded >= expandable) return TreeAlreadyInStateReason;
            if (elementName.IndexOf("CollapseAll", StringComparison.OrdinalIgnoreCase) >= 0 &&
                expanded <= 0) return TreeAlreadyInStateReason;
            return "";
        }

        /// <summary>НОМЕР РАЗДЕЛА ИЗ ИМЕНИ (`MenuSec_2` → 2). −1 — это не раздел меню.</summary>
        public static int MenuSectionIndexOfName(string name)
        {
            if (string.IsNullOrEmpty(name)) return -1;
            if (name.IndexOf("MenuSec", StringComparison.OrdinalIgnoreCase) < 0) return -1;
            return TrailingNumber(name);
        }

        /// <summary>
        /// ЧИСЛО В КОНЦЕ ИМЕНИ (`Seg2` → 2, `MenuSec_5` → 5). −1 — числа нет.
        /// Одна функция на все правила «номер из имени», чтобы они не разъезжались.
        /// </summary>
        public static int TrailingNumber(string name)
        {
            if (string.IsNullOrEmpty(name)) return -1;
            int digits = 0;
            int value = 0;
            for (int i = name.Length - 1; i >= 0; i--)
            {
                char c = name[i];
                if (c < '0' || c > '9') break;
                value += (c - '0') * (int)Math.Pow(10, digits);
                digits++;
                if (digits > 3) break;
            }
            return digits == 0 ? -1 : value;
        }

        /// <summary>Причина для уже открытого раздела меню или `""`.</summary>
        public static string StartSectionAlreadyOpenReasonFor(int currentSection, int elementSection)
        {
            if (elementSection < 0) return "";
            if (currentSection != elementSection) return "";
            return StartSectionAlreadyOpenReason;
        }

        /// <summary>
        /// ПРИЧИНА «КОМАНДА РЕЕСТРА СЕЙЧАС НЕДОСТУПНА» — ТОЛЬКО ПО ФАКТУ РЕЕСТРА.
        ///
        /// ОТКУДА (шлем, отчёт 11.11.2026: «Сменить робота» — `ok=0 effect=нет изменений` без
        /// причины). Строка вызывает `robot.switch`, у которого `IsEnabled = роботов &gt; 1`;
        /// нажатие идёт после удаления последнего робота, `InvokeMenuCommand` видит
        /// `Enabled = false` и честно возвращается — снимок не видит НИ ОДНОГО признака, и
        /// рабочая строка выглядит мёртвой. Правило узкое: причина даётся только когда сам
        /// реестр отвечает «не найдена»/«недоступна», и в причину идёт ФАКТИЧЕСКОЕ состояние
        /// (`detail` — например, число роботов в сцене). Команда включена → `""` → отсутствие
        /// эффекта остаётся настоящей находкой гейта, а не оправданием.
        /// </summary>
        /// <param name="commandId">Идентификатор команды (`robot.switch`).</param>
        /// <param name="registered">Команда есть в реестре (`KvCommands.Get` вернул не null).</param>
        /// <param name="enabled">Команда включена прямо сейчас (`command.Enabled`).</param>
        /// <param name="detail">Фактическое состояние для причины («роботов в сцене 0») или `""`.</param>
        public static string CommandUnavailableReason(string commandId, bool registered, bool enabled,
            string detail)
        {
            if (string.IsNullOrEmpty(commandId)) return "";
            string tail = string.IsNullOrEmpty(detail) ? "" : " · " + detail;
            if (!registered)
                return "команда «" + commandId + "» не найдена в реестре — нажатие не выполняет " +
                       "работу (проверено реестром" + tail + ")";
            if (!enabled)
                return "команда «" + commandId + "» недоступна — нажатие не выполняет работу " +
                       "(состояние реестра: Enabled=false" + tail + ")";
            return "";
        }

        /// <summary>
        /// Причина «закрывать нечего» или `""`. `level` — текущий уровень панели, `groupsLevel` —
        /// уровень «иконки групп» (ничего не открыто).
        /// </summary>
        public static string NothingToCloseReasonFor(int level, int groupsLevel)
        {
            if (level != groupsLevel) return "";          // экран открыт — закрытие даст эффект
            return NothingToCloseReason;
        }

        /// <summary>
        /// НОМЕР СЕГМЕНТА ИЗ ИМЕНИ ОБЪЕКТА (`Seg0` → 0, `Seg2` → 2). −1 — это не сегмент.
        /// </summary>
        public static int SegmentIndexOfName(string name)
        {
            if (string.IsNullOrEmpty(name)) return -1;
            if (name.IndexOf("Seg", StringComparison.OrdinalIgnoreCase) < 0) return -1;
            return TrailingNumber(name);
        }

        /// <summary>
        /// Причина для активной вкладки или `""`. `currentIndex` — что выбрано сейчас,
        /// `elementIndex` — номер самого элемента (−1 — это не сегмент).
        /// </summary>
        public static string AlreadyActiveTabReasonFor(int currentIndex, int elementIndex)
        {
            if (elementIndex < 0) return "";
            if (currentIndex != elementIndex) return "";
            return AlreadyActiveTabReason;
        }

        /// <summary>ЭТО ПЛАШКА, ЗАКРЫВАЮЩАЯ МЕНЮ (`KvMenuBlocker`)?</summary>
        public static bool IsMenuBlocker(string path)
        {
            return !string.IsNullOrEmpty(path) &&
                   path.IndexOf("KvMenuBlocker", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        /// <summary>
        /// ПРИЧИНА ДЛЯ ПЛАШКИ-БЛОКИРОВЩИКА или `""`. Когда меню НЕ открыто, закрывать нечего —
        /// это законное «ничего не меняет». Когда открыто — нажатие закрывает меню, и это эффект.
        /// </summary>
        public static string MenuBlockerReasonFor(string path, bool menuOpen)
        {
            if (!IsMenuBlocker(path)) return "";
            if (menuOpen) return "";
            return "закрывающая плашка: меню не открыто — нажимать нечего";
        }

        /// <summary>Причина для скрытой панели с названием самой панели.</summary>
        public static string HiddenPanelReasonFor(string panelPath)
        {
            return string.IsNullOrEmpty(panelPath)
                ? HiddenPanelReason
                : HiddenPanelReason + " (" + panelPath + ")";
        }

        /// <summary>Все признаки шлюза (для шапки отчёта).</summary>
        public static IReadOnlyList<string> GatePatterns { get { return gatePatterns; } }

        /// <summary>
        /// ДЕЙСТВИЯ, КОТОРЫМ НУЖНА НАЙДЕННАЯ ПЛОСКОСТЬ (постановка и создание объектов в AR).
        /// Список намеренно узкий: «стол» и «робот» сами по себе не признак — так называются и
        /// строки свойств, и обычные кнопки. Расширять его можно только по факту из журнала.
        /// </summary>
        private static readonly string[] planePatterns =
        {
            "поставить",
            "переставить",
            "постановк",
            "разместить",
            "квадратный стол",
            "авто стол",
            "создать стол",
            "создать робота",
            "демо",
            "place",
            "spawn",
        };

        /// <summary>Нужна ли элементу найденная плоскость (по пути/подписи).</summary>
        public static bool NeedsPlane(string path)
        {
            if (string.IsNullOrEmpty(path)) return false;
            for (int i = 0; i < planePatterns.Length; i++)
            {
                string pattern = planePatterns[i];
                if (string.IsNullOrEmpty(pattern)) continue;
                if (path.IndexOf(pattern, StringComparison.OrdinalIgnoreCase) >= 0) return true;
            }
            return false;
        }

        /// <summary>
        /// ПРИЧИНА ПО СОСТОЯНИЮ AR: «ставить некуда» — с ФАКТИЧЕСКИМ ЧИСЛОМ плоскостей.
        ///
        /// ЗАЧЕМ ЧИСЛО В ТЕКСТЕ. Без него тестировщик не отличит «невозможно в этом состоянии» от
        /// «кнопка сломалась». `0` — это утверждение о мире (ARCore не построил карту), а не
        /// оправдание; поэтому оно и печатается.
        /// Правило действует ТОЛЬКО при нуле плоскостей и ТОЛЬКО для действий постановки —
        /// обычная кнопка панели при том же состоянии проверяется как всегда.
        /// </summary>
        public static string PlaneReasonFor(string path, int planesFound)
        {
            if (planesFound > 0) return "";
            if (!NeedsPlane(path)) return "";
            return "нечего ставить: найденных плоскостей " + planesFound.ToString(CultureInfo.InvariantCulture) +
                   " (подтверждено состоянием AR)";
        }

        /// <summary>
        /// ПУНКТЫ, КОТОРЫЕ ВЕДУТ ИЗ ПРИЛОЖЕНИЯ В СИСТЕМУ (найдено на планшете 12.11.2026).
        ///
        /// ЧТО БЫЛО. Прогон нажал кнопку «НАСТРОЙКИ ПРИЛОЖЕНИЯ» (её строит `KvArCameraGate`, и
        /// единственное, что она делает, — открывает `android.settings.APPLICATION_DETAILS_SETTINGS`).
        /// Открылся системный экран MIUI, приложение ушло в фон, кадры остановились, корутина
        /// встала — и прогон висел до ручного вмешательства, не написав ни итога, ни причины.
        /// ЧЕМ ПЛОХО БЫЛО БЕЗ ЭТОГО СПИСКА. Самопрогон не должен УВОДИТЬ приложение из себя:
        /// проверяются кнопки интерфейса, а не переходы в настройки Android.
        /// ЧТО СТАЛО. Такие элементы НЕ нажимаются и честно помечаются `exempt=…`.
        ///
        /// ВАЖНОЕ РАЗЛИЧЕНИЕ (иначе правка хуже дефекта). Одноимённые ШТАТНЫЕ панели проекта
        /// («Настройки», «Настройки ПК», ряд «Разрешения» в свойствах) обязаны проверяться
        /// нажатием: они не уводят из приложения. Поэтому система сравнивается ТОЛЬКО у элементов
        /// ВНЕ панелей проекта (`projectOwned == false`). Если различить нельзя — не нажимаем:
        /// повешенный прогон дороже непроверенной кнопки.
        /// </summary>
        private static readonly Rule[] systemRules =
        {
            new Rule
            {
                Pattern = "настройки android",
                Reason = "системные настройки Android: нажатие уводит из приложения", Press = false
            },
            new Rule
            {
                Pattern = "android settings",
