                Reason = "системные настройки Android: нажатие уводит из приложения", Press = false
            },
            new Rule
            {
                Pattern = "настройки устройства",
                Reason = "системные настройки Android: нажатие уводит из приложения", Press = false
            },
            new Rule
            {
                Pattern = "настройки приложения",
                Reason = "настройки приложения Android: открывает системный экран (KvArCameraGate)", Press = false
            },
            new Rule
            {
                Pattern = "открыть настройки",
                Reason = "открывает системные настройки: нажатие уводит из приложения", Press = false
            },
            new Rule
            {
                Pattern = "app settings",
                Reason = "настройки приложения Android: открывает системный экран", Press = false
            },
            new Rule
            {
                Pattern = "application settings",
                Reason = "настройки приложения Android: открывает системный экран", Press = false
            },
            new Rule
            {
                Pattern = "информация о приложении",
                Reason = "сведения о приложении: открывает системный экран Android", Press = false
            },
            new Rule
            {
                Pattern = "о приложении",
                Reason = "сведения о приложении: открывает системный экран Android", Press = false
            },
            new Rule
            {
                Pattern = "app info",
                Reason = "сведения о приложении: открывает системный экран Android", Press = false
            },
            new Rule
            {
                Pattern = "разрешения",
                Reason = "разрешения Android: открывает системный экран", Press = false
            },
            new Rule
            {
                Pattern = "permissions",
                Reason = "разрешения Android: открывает системный экран", Press = false
            },
            new Rule
            {
                Pattern = "settings",
                Reason = "вне панелей проекта: возможно системный экран — не нажимаем", Press = false
            },
        };

        /// <summary>
        /// ПОХОЖЕ ЛИ НА ПУНКТ, ВЕДУЩИЙ В СИСТЕМУ (по пути/подписи элемента).
        /// Само по себе это ещё не приговор: приговор выносит <see cref="SystemScreenReason"/>
        /// с учётом принадлежности панелям проекта.
        /// </summary>
        public static bool LooksLikeSystemScreen(string path)
        {
            if (string.IsNullOrEmpty(path)) return false;
            for (int i = 0; i < systemRules.Length; i++)
            {
                Rule r = systemRules[i];
                if (r == null || string.IsNullOrEmpty(r.Pattern)) continue;
                if (path.IndexOf(r.Pattern, StringComparison.OrdinalIgnoreCase) >= 0) return true;
            }
            return false;
        }

        /// <summary>
        /// ПРИЧИНА ИСКЛЮЧЕНИЯ ДЛЯ СИСТЕМНОГО ПУНКТА (`""` — элемент можно нажимать).
        /// `projectOwned == true` — элемент принадлежит панелям САМОГО приложения, поэтому даже
        /// подпись «Настройки» на нём ничего не значит: это штатная панель, её и надо проверить.
        /// </summary>
        public static string SystemScreenReason(string path, bool projectOwned)
        {
            if (projectOwned) return "";
            if (string.IsNullOrEmpty(path)) return "";
            for (int i = 0; i < systemRules.Length; i++)
            {
                Rule r = systemRules[i];
                if (r == null || string.IsNullOrEmpty(r.Pattern)) continue;
                if (path.IndexOf(r.Pattern, StringComparison.OrdinalIgnoreCase) >= 0) return r.Reason;
            }
            return "";
        }

        /// <summary>Все правила исключений (для шапки отчёта: тестировщик видит список целиком).</summary>
        public static IReadOnlyList<Rule> Rules { get { return rules; } }

        /// <summary>Правила «системных» пунктов (для шапки отчёта).</summary>
        public static IReadOnlyList<Rule> SystemRules { get { return systemRules; } }

        /// <summary>
        /// Причина исключения для элемента или `""`. Проверяются: недоступность элемента и
        /// совпадение пути с одним из правил. Регистр не важен: имена в интерфейсе пишут
        /// по-разному («ГОЛОС», «Голосовой ввод», «voice»).
        /// </summary>
        public static string ReasonFor(string path, bool interactable)
        {
            if (!interactable) return DisabledReason;
            return ReasonFor(path);
        }

        /// <summary>Причина исключения по одному пути (без учёта доступности).</summary>
        public static string ReasonFor(string path)
        {
            if (string.IsNullOrEmpty(path)) return "";
            for (int i = 0; i < rules.Length; i++)
            {
                Rule r = rules[i];
                if (r == null || string.IsNullOrEmpty(r.Pattern)) continue;
                if (path.IndexOf(r.Pattern, StringComparison.OrdinalIgnoreCase) >= 0) return r.Reason;
            }
            return "";
        }

        /// <summary>Нажимать ли элемент (ложь только у опасных: «Выход» и подобные).</summary>
        public static bool ShouldPress(string path)
        {
            // Без сведений о принадлежности считаем элемент «своим»: безусловные запреты
            // (выход из приложения) действуют всегда, а системные пункты так не отсекаются —
            // для них есть перегрузка с `projectOwned`.
            return ShouldPress(path, true);
        }

        /// <summary>
        /// НАЖИМАТЬ ЛИ ЭЛЕМЕНТ с учётом принадлежности панелям проекта.
        /// `projectOwned == false` — элемент вне панелей приложения: если его подпись похожа на
        /// системный пункт, он не нажимается (иначе прогон уводит приложение в настройки Android).
        /// </summary>
        public static bool ShouldPress(string path, bool projectOwned)
        {
            if (string.IsNullOrEmpty(path)) return true;
            // СИСТЕМНЫЙ ШЛЮЗ — НИКОГДА, при любой принадлежности: это не интерфейс оператора.
            if (IsGatePath(path)) return false;

            for (int i = 0; i < rules.Length; i++)
            {
                Rule r = rules[i];
                if (r == null || string.IsNullOrEmpty(r.Pattern)) continue;
                if (path.IndexOf(r.Pattern, StringComparison.OrdinalIgnoreCase) >= 0) return r.Press;
            }
            if (!projectOwned && LooksLikeSystemScreen(path)) return false;
            return true;
        }

        /// <summary>
        /// РАЗРУШИТЕЛЬНОЕ ДЕЙСТВИЕ (удаление, сброс, экспорт, запись). Такие элементы нажимаются
        /// В КОНЦЕ прогона: если один из них что-то испортит, остальные проверки уже выполнены, и
        /// в отчёте видно, на чём именно прогон закончился.
        /// </summary>
        public static bool IsDestructive(string path)
        {
            if (string.IsNullOrEmpty(path)) return false;
            string[] patterns = { "удал", "сброс", "очист", "экспорт", "запис", "reset", "delete", "export", "record" };
            for (int i = 0; i < patterns.Length; i++)
                if (path.IndexOf(patterns[i], StringComparison.OrdinalIgnoreCase) >= 0) return true;
            return IsSessionChanging(path);
        }

        /// <summary>
        /// ДЕЙСТВИЕ, МЕНЯЮЩЕЕ СЕССИЮ: «Новый проект», «Загрузить проект», «Импорт проекта».
        ///
        /// ЧТО БЫЛО (шлем, свежая сборка). Первым же элементом нажалось `Menu_start.new«Новый
        /// проект»`: стартовое меню закрылось, проект пересоздался — и все остальные пункты меню
        /// «исчезли», а панели шлема остались скрытыми. Из 70 элементов проверился ОДИН.
        /// ПОЧЕМУ «В КОНЕЦ», А НЕ «НЕ НАЖИМАТЬ». Кнопка рабочая, и проверить её надо; но её место —
        /// в самом конце, когда остальное уже проверено. Так сохраняются И покрытие, И проверка
        /// самой кнопки — в отличие от исключения, которое просто выключило бы её из прогона.
        /// </summary>
        public static bool IsSessionChanging(string path)
        {
            if (string.IsNullOrEmpty(path)) return false;
            string[] patterns =
            {
                "новый проект", "new project", "создать проект", "загрузить проект",
                "открыть проект", "импорт проект", "load project", "import project"
            };
            for (int i = 0; i < patterns.Length; i++)
                if (path.IndexOf(patterns[i], StringComparison.OrdinalIgnoreCase) >= 0) return true;
            return false;
        }

        /// <summary>
        /// ПРИЧИНА ДЛЯ ЭЛЕМЕНТА, КОТОРЫЙ ПРОГОН СОЗНАТЕЛЬНО НЕ НАЖАЛ (`""` не бывает никогда).
        ///
        /// ОТКУДА (дефект D3, чистое состояние 13.11.2026). Кнопка
        /// `KvArCameraGateCanvas/GateButton«РАЗРЕШИТЬ КАМЕРУ»` получала «без эффекта», хотя прогон
        /// её НЕ нажимает: причина исключения читалась только из флага `SystemGate`, поставленного
        /// при СБОРЕ элемента, а решение «не нажимать» (`ShouldPress`) принимается по ПУТИ — два
        /// источника могли разойтись, и ненажатый элемент оставался без объяснения.
        /// Теперь причина считается по тому же пути, что и запрет нажатия, и пустой быть не может:
        /// иначе самопрогон обвинял бы в бездействии кнопку, которую сам же трогать отказался.
        /// </summary>
        public const string NotPressedReason =
            "не нажимали — правило запрещает (опасно для прогона)";

        /// <summary>Причина для ненажатого элемента: системный шлюз → системный экран → правило → общая.</summary>
        public static string UnpressedReasonFor(string path, bool projectOwned)
        {
            if (IsGatePath(path)) return GateReason;
            string system = SystemScreenReason(path, projectOwned);
            if (system.Length > 0) return system;
            string rule = ReasonFor(path);
            if (rule.Length > 0) return rule;
            return NotPressedReason;
        }
    }

    /// <summary>
    /// РЕШЕНИЕ ПО ВОЗВРАТУ ВИДИМОСТИ ОБОЛОЧКИ (`ui.toggle` → `Restore`).
    ///
    /// ОТКУДА (дефект D4, 13.11.2026). `Restore` возвращал док-панели, режим, язык и `KvSettings`,
    /// но НЕ `uiVisible`: после команды «Показать/скрыть интерфейс» оболочка оставалась скрытой,
    /// и 12 элементов `Cmd_*` не проверялись вторым проходом — их путей в мире без интерфейса
    /// просто не существовало. Решение вынесено в чистую функцию, чтобы его проверял тест.
    /// </summary>
    public static class KvUiSweepUiVisible
    {
        /// <summary>Надо ли вернуть оболочку к состоянию до нажатия (значение `UiVisible` снимка).</summary>
        public static bool NeedsRestore(int before, bool nowVisible)
        {
            return (before != 0) != nowVisible;
        }

        /// <summary>В какое состояние вернуть: true — показать, false — скрыть.</summary>
        public static bool Target(int before)
        {
            return before != 0;
        }
    }

    /// <summary>
    /// ДОК-ПАНЕЛИ ОБОЛОЧКИ: ШТАТНАЯ КОМАНДА ОТКРЫТИЯ И ЧЕСТНАЯ ПРИЧИНА, ЕСЛИ НЕ ОТКРЫЛАСЬ.
    ///
    /// ОТКУДА (дефект D2, отчёт 13.11.2026 12:14, макет ar): 31 элемент из 140 — все
    /// `…/KazistovVvDockCanvas/Dock_Настройки/Body/Scroll/Content/Switch_*` — получили
    /// «исчез (путь не найден)». Канвас док-панелей гаснет, когда запрошенных панелей нет, а
    /// раскладка хранится в PlayerPrefs: панель «Настройки» остаётся свёрнутой/узкой, и
    /// «восстановление экрана» её не раскрывает. Лечение — ОТКРЫВАТЬ панель штатной командой
    /// (та же, что у кнопки оператора), а если не вышло — называть причину «панель не открыта».
    /// </summary>
    public static class KvUiSweepDockNav
    {
        /// <summary>Четыре dock-панели оболочки — в порядке `KazistovVvUIManager.DockById`.</summary>
        public static readonly string[] Ids = { "tree", "properties", "settings", "hotkeys" };

        /// <summary>
        /// ШТАТНАЯ КОМАНДА ОТКРЫТИЯ ПАНЕЛИ (`""` — для неизвестной панели команды нет).
        /// Настройки открываются `view.panel.settings`, А НЕ `ui.settings`: та переключает вкладку
        /// на «Функции» и спрятала бы строки других вкладок — элемент остался бы непроверенным.
        /// </summary>
        public static string OpenCommandFor(string dockId)
        {
            switch (dockId)
            {
                case "tree": return "view.panel.tree";
                case "properties": return "view.panel.properties";
                case "settings": return "view.panel.settings";
                case "hotkeys": return "help.hotkeys";
                default: return "";
            }
        }

        /// <summary>Это путь элемента док-панели? (Путь строится от корня `Dock_&lt;название&gt;`.)</summary>
        public static bool IsDockPath(string path)
        {
            if (string.IsNullOrEmpty(path)) return false;
            return path.IndexOf("/Dock_", StringComparison.Ordinal) >= 0;
        }

        /// <summary>Честная причина для элемента, чью панель открыть не удалось.</summary>
        public static string NotOpenReasonFor(string dockId, string detail)
        {
            return KvUiSweepPanelNav.NotOpenReason("док-панель «" + dockId + "»", detail);
        }
    }

    /// <summary>Имя макета для отчёта: `vr`, `mr`, `ar`, `pc`.</summary>
    public static class KvUiSweepLayout
    {
        /// <summary>
        /// МАКЕТ ПРОГОНА. AR определяется СЦЕНОЙ (в проекте это отдельная сцена `ArMain`), ПК —
        /// тем, что приложение не на устройстве. Порядок важен: на планшете в AR сцена важнее
        /// режима, иначе прогон в AR назывался бы `vr` и отчёты двух разных приложений
        /// перепутались бы.
        /// </summary>
        public static string NameOf(string sceneName, int modeIndex, bool onDevice)
        {
            if (IsArScene(sceneName)) return "ar";
            if (!onDevice) return "pc";
            return modeIndex == KvXrSettings.ModeMr ? "mr" : "vr";
        }

        /// <summary>
        /// СЦЕНА ДОПОЛНЕННОЙ РЕАЛЬНОСТИ. В проекте это `ArMain`, а перед ней грузится
        /// загрузчик `BootAr` — обе называются «Ar» на краю имени. Ищем именно КРАЙ, а не
        /// подстроку: «MainScene» и «XrMain» не должны попасть в AR по случайной букве.
        /// </summary>
        public static bool IsArScene(string sceneName)
        {
            string scene = sceneName ?? "";
            if (scene.Length == 0) return false;
            if (scene.StartsWith("Ar", StringComparison.OrdinalIgnoreCase)) return true;
            return scene.EndsWith("Ar", StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>Человеческое название режима для строки СТАРТ: «VR», «MR», «режим не трогали».</summary>
        public static string ModeName(int index)
        {
            if (index == KvXrSettings.ModeVr) return "vr";
            if (index == KvXrSettings.ModeMr) return "mr";
            return "не трогали";
        }
    }

    // ============================================================================================
    //  ЧАСТЬ 2. РАНТАЙМ — обход живой сцены. Проверяется на устройстве (`Tools/ui-sweep-device.ps1`).
    // ============================================================================================

    /// <summary>
    /// САМОПРОГОН ИНТЕРФЕЙСА. Живёт на объекте, созданном ТОЛЬКО по явному запросу.
    /// </summary>
    public class KvUiSweepRuntime : MonoBehaviour
    {
        /// <summary>Сколько секунд отводится ОДНОМУ элементу (дольше — `ok=0 timeout`).</summary>
        public const float ElementBudgetSeconds = 2f;

        /// <summary>
        /// Общий предел прогона: по его истечении прогон завершается с честным отчётом.
        /// ПОДНЯТ С 240 ДО 600 (пункт 39 шапки): обход «по одному элементу с восстановлением
        /// экрана» дороже прежнего (каждый элемент панели — показ/возврат панели + кадр
        /// пересборки), а прогон ОБЯЗАН дойти до конца — оборванный по бюджету обход вернул бы
        /// молчаливое «не проверено» вместо итога.
        /// </summary>
        public const float TotalBudgetSeconds = 600f;

        /// <summary>
        /// ПРЕДЕЛ ЧИСЛА ЭЛЕМЕНТОВ СНЯТ (дефект D1, 13.11.2026).
        ///
        /// ЧТО БЫЛО. Старое значение 140 обрезало СБОР: в отчёте 13.11 стояло «СТАРТ: элементов=140»
        /// — ровно предел, то есть инвентарь AR (41+ кнопка тулбара, динамические меню) в прогон не
        /// попадал вовсе и проверить его было нельзя. Потерянное при обрезке не называлось ничем.
        ///
        /// ЧТО СТАЛО. Границу держит БЮДЖЕТ ВРЕМЕНИ (`TotalBudgetSeconds`): по его истечении обход
        /// печатает честную строку «ПРЕДЕЛ: … с истекли — проверено X из Y; остальные НЕ
        /// ПРОВЕРЯЛИСЬ», то есть непроверенное видно числом, а не теряется молча. Замер 13.11:
        /// 140 элементов за 18,6 с (~0,13 с на элемент) — 600 с бюджета хватает на порядок больше
        /// элементов, чем старый предел. КОМБИНАТОРНЫЙ ВЗРЫВ УРОВНЕЙ тот же бюджет гасит сам:
        /// очередь всё равно ограничена тем, что реально построено в интерфейсе.
        /// </summary>
        public const int MaxElements = int.MaxValue;

        /// <summary>На сколько уровней вглубь раскрывать панель шлема (0 — только иконки групп).</summary>
        public const int MaxPanelDepth = 3;

        /// <summary>Сколько секунд ждать, пока сцена устоится и интерфейс построится.</summary>
        public const float UiReadyWaitSeconds = 45f;

        /// <summary>Сколько кадров подряд имя сцены должно не меняться, чтобы считать её загруженной.</summary>
        public const int StableSceneFrames = 10;

        private const int SettleFrames = 3;       // кадров «остывания» после смены режима

        private static KvUiSweepRuntime active;
        private static bool started;

        private IDictionary<string, string> extras = new Dictionary<string, string>();
        private KvUiSweepRun run;
        private readonly StringBuilder report = new StringBuilder(8192);
        private float startedAt;
        private string sceneName = "";
        private int requestedMode = -1;
        private int skippedScrollbars, skippedTemplates, skippedWindowPanels, notPressed;

        /// <summary>Пункты стартового меню шлема: проверяются ОТДЕЛЬНЫМ проходом по одному.</summary>
        private readonly List<StartMenuItem> startMenuItems = new List<StartMenuItem>();
        private readonly HashSet<string> startMenuKeys = new HashSet<string>(StringComparer.Ordinal);
        private int startMenuIndex;               // сквозной номер нажатия в проходе по меню
        private int startMenuCollectSection = -1; // раздел, который был открыт при СБОРЕ меню
        private int startMenuPlanned;             // сколько пунктов меню запланировано (растёт по ходу)
        private const int StartMenuPassBudgetSeconds = 180;  // две фазы: пункты сбора + строки разделов; поднят с 90 (пункт 39 шапки)

        /// <summary>
        /// ПУНКТ СТАРТОВОГО МЕНЮ ВМЕСТЕ С РАЗДЕЛОМ, в котором он был виден при сборе.
        ///
        /// ЗАЧЕМ РАЗДЕЛ. Имена строк меню — НОМЕР, а не содержимое: `MenuRow_0` есть в каждом
        /// разделе, и обозначает он РАЗНЫЕ пункты («Стол: …» в «Столах», «Добавить стол» — там же,
        /// «Вернуться к работе» в «Работе»). Чтобы путь снова означал ТОТ ЖЕ элемент, перед
        /// проверкой меню ставится на записанный раздел. Без этого прогон нажал бы не тот пункт и
        /// записал бы эффект не той кнопке.
        /// </summary>
        private sealed class StartMenuItem
        {
            public Candidate Candidate;
            public int Section;
            public bool IsSection;
            /// <summary>Пункт УЖЕ попал в отчёт (проверен или назван причиной) — второй раз не пишем.</summary>
            public bool Done;
        }

        /// <summary>Сколько элементов ПК-раскладки пропущено в шлеме (одной строкой в отчёте).</summary>
        private int pcSkipped, pcWorkbench, pcFeature, pcHint, pcShell;

        /// <summary>Файл отчёта текущего макета (может смениться после уточнения сцены/режима).</summary>
        private string reportPath = "";

        /// <summary>Файл уже создан и содержит накопленное (иначе первая запись — полная, не дозапись).</summary>
        private bool reportFileReady;

        /// <summary>Прогон закончился (обычным путём или прерыванием) — второй раз не завершаем.</summary>
        private bool finished;

        /// <summary>
        /// ХОТЯ БЫ ОДНО НАЖАТИЕ УЖЕ БЫЛО. Сторож фокуса включается ТОЛЬКО после него: на холодном
        /// старте Android штатно отдаёт фокус системному диалогу разрешений, и «уход в фон» там —
        /// норма, а не сбой прогона.
        /// </summary>
        private bool pressStarted;

        /// <summary>
        /// ОЧЕРЕДЬ ОБХОДА ПО ПУТЯМ. Главное отличие от списка ссылок: путь переживает
        /// перестроение интерфейса, ссылка — нет.
        /// </summary>
        private KvUiSweepQueue queue;

        /// <summary>Кандидаты по ключу пути — чтобы по пути из очереди найти описание элемента.</summary>
        private readonly Dictionary<string, Candidate> byKey =
            new Dictionary<string, Candidate>(StringComparer.Ordinal);

        /// <summary>Живые `Selectable` по ключу пути: пересобирается, когда путь не нашёлся.</summary>
        private readonly Dictionary<string, Selectable> pathIndex =
            new Dictionary<string, Selectable>(StringComparer.Ordinal);

        /// <summary>Сколько путей совпало (одинаковые имена в иерархии) — печатается в строке СТАРТ.</summary>
        private int duplicatePaths;

        /// <summary>Совпавшие ключи и сколько объектов на каждый — печатается в отчёт списком.</summary>
        private readonly Dictionary<string, int> collisions =
            new Dictionary<string, int>(StringComparer.Ordinal);

        /// <summary>
        /// Предел второго прохода по отложенным элементам, секунды. ПОДНЯТ С 60 ДО 180 (пункт 39
        /// шапки): отложенным элементам панели теперь ВОССТАНАВЛИВАЕТСЯ экран (до `MaxAttempts`
        /// попыток каждому), и 60 с не хватило бы на полный второй проход в шлеме.
        /// </summary>
        public const float RetryBudgetSeconds = 180f;

        /// <summary>Элемент, отложенный до второго прохода (в скрытой панели или пока исчез).</summary>
        private class DeferredElement
        {
            public Candidate Candidate;
            public bool Hidden;
            public string PanelPath = "";
        }

        /// <summary>Отложенные элементы первого прохода — их проверяет второй проход.</summary>
        private readonly List<DeferredElement> deferred = new List<DeferredElement>();

        /// <summary>Ключи отложенных (без повторов).</summary>
        private readonly HashSet<string> deferredKeys = new HashSet<string>(StringComparer.Ordinal);

        /// <summary>Идёт второй проход — внутри него откладывать уже нельзя, только записывать.</summary>
        private bool inRetryPass;

        /// <summary>Номер элемента во втором проходе (для строки `press=`).</summary>
        private int retryIndex;

        /// <summary>Сколько раз контекст (меню/панель) восстанавливался после нажатия.</summary>
        private int contextRestores;

        /// <summary>Сколько раз состояние панели не удалось вернуть (печатается в ИТОГе).</summary>
        private int restoreFailures;

        /// <summary>Панели, которые так и не открылись: «не открывается ни одной кнопкой».</summary>
        private readonly HashSet<string> stuckPanels = new HashSet<string>(StringComparer.Ordinal);

        // ------------------------------------------------------------------ запуск

        /// <summary>
        /// АВТОЗАПУСК. Проверяется ЯВНЫЙ запрос (extra интента или аргумент командной строки).
        /// Нет флага — выход на первой строке: обычный старт приложения не меняется НИ НА КАДР.
        ///
        /// ПОЧЕМУ `AfterSceneLoad`, А НЕ `BeforeSceneLoad`. К этому моменту активность уже создана,
        /// и extra интента читаются надёжно; сама сцена на Android здесь ещё ЗАГРУЗОЧНАЯ
        /// (`BootAr`), поэтому имя сцены и макет раннер берёт не сейчас, а после ожидания
        /// устойчивой сцены в `Sweep()`.
        /// </summary>
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        private static void Boot()
        {
            started = false;
            active = null;

            var collected = new Dictionary<string, string>();
            string flag = ReadExtra(KvUiSweepFlags.ExtraKey);
            if (flag != null) collected[KvUiSweepFlags.ExtraKey] = flag;
            string mode = ReadExtra(KvUiSweepFlags.ModeExtraKey);
            if (mode != null) collected[KvUiSweepFlags.ModeExtraKey] = mode;

            // ЗАЩИТА ОТ ЗАПУСКА В ОБЫЧНОЙ РАБОТЕ — здесь, до создания объекта: без флага в сцене
            // не появляется ни один новый объект.
            if (!KvUiSweepFlags.Requested(collected, Environment.GetCommandLineArgs())) return;

            Debug.Log("[KvUiSweep] запрос принят: extra=" + flag + " режим=" +
                      (string.IsNullOrEmpty(mode) ? "не трогать" : mode));
            Spawn(collected);
        }

        /// <summary>
        /// ЗАПУСК ИЗ РЕДАКТОРА (PlayMode). Тот же прогон, что и по extra-флагу, но без adb:
        /// тестировщик нажимает Play и вызывает этот метод из меню. Режим не указывается —
        /// в редакторе VR/MR один и тот же макет `pc`, и подмена режима тут только запутала бы.
        /// </summary>
        public static bool RunFromEditor()
        {
            return RunFromEditor("");
        }

        /// <summary>Запуск из редактора с явным режимом: `"vr"` или `"mr"` (пусто — не трогать).</summary>
        public static bool RunFromEditor(string mode)
        {
            if (!Application.isPlaying)
            {
                Debug.LogError("[KvUiSweep] RunFromEditor вызван ВНЕ PlayMode: " +
                               "сначала войдите в PlayMode, потом запускайте прогон");
                return false;
            }
            var collected = new Dictionary<string, string>
            {
                { KvUiSweepFlags.ExtraKey, "1" }
            };
            if (!string.IsNullOrEmpty(mode)) collected[KvUiSweepFlags.ModeExtraKey] = mode;
            return Spawn(collected);
        }

        /// <summary>Единственная точка создания раннера (и защита от второго прогона сразу).</summary>
        private static bool Spawn(IDictionary<string, string> collected)
        {
            if (started)
            {
                Debug.LogWarning("[KvUiSweep] прогон уже идёт — второй не начинаю");
                return false;
            }
            started = true;
            GameObject go = new GameObject("KvUiSweepRunner");
            UnityEngine.Object.DontDestroyOnLoad(go);
            active = go.AddComponent<KvUiSweepRuntime>();
            active.extras = collected ?? new Dictionary<string, string>();
            return true;
        }

        /// <summary>
        /// ЧТЕНИЕ EXTRA ИНТЕНТА. На Android `am start … -e kv_uisweep 1` кладёт значение в Intent;
        /// аргументы командной строки этого не видят. `currentActivity` может быть null
        /// (например, при старте без активности) — тогда возвращается null, а не исключение.
        /// </summary>
        private static string ReadExtra(string key)
        {
            if (Application.platform != RuntimePlatform.Android) return null;
            try
            {
                using (var player = new AndroidJavaClass("com.unity3d.player.UnityPlayer"))
                using (var activity = player.GetStatic<AndroidJavaObject>("currentActivity"))
                {
                    if (activity == null) return null;
                    using (var intent = activity.Call<AndroidJavaObject>("getIntent"))
                    {
                        if (intent == null) return null;
                        string value = intent.Call<string>("getStringExtra", key);
                        if (!string.IsNullOrEmpty(value)) return value;
                        // «am start --ei kv_uisweep 1» кладёт число, а не строку.
                        int number = intent.Call<int>("getIntExtra", key, -1);
                        return number >= 0 ? number.ToString(CultureInfo.InvariantCulture) : null;
                    }
                }
            }
            catch (Exception e)
            {
                Debug.LogWarning("[KvUiSweep] extra «" + key + "» не прочитан: " + e.GetType().Name +
                                 ": " + e.Message);
                return null;
            }
        }

        // ------------------------------------------------------------------ жизненный цикл

        private void Start()
        {
            StartCoroutine(Sweep());
        }

        private void OnEnable()
        {
            Application.focusChanged -= OnFocusChanged;
            Application.focusChanged += OnFocusChanged;
        }

        private void OnDisable()
        {
            Application.focusChanged -= OnFocusChanged;
        }

        /// <summary>
        /// СТОРОЖ ФОКУСА. Если приложение ушло в фон — обход НЕ продолжается молча.
        ///
        /// ЗАЧЕМ. На планшете 12.11.2026 самопрогон нажал кнопку, открывшую системный экран
        /// настроек Android: приложение ушло в фон, Unity перестал получать кадры, корутина
        /// встала навсегда. Снаружи это неотличимо от «прогон ещё идёт»: ни итога, ни причины,
        /// только ожидание по общему таймауту. Теперь такой уход превращается в ЯВНЫЙ вердикт с
        /// названным виновником.
        /// </summary>
        private void OnApplicationFocus(bool hasFocus)
        {
            if (!hasFocus) NoteBackground();
        }

        /// <summary>Пауза приложения (Android: `onPause`) — тот же случай, что и потеря фокуса.</summary>
        private void OnApplicationPause(bool paused)
        {
            if (paused) NoteBackground();
        }

        private void OnFocusChanged(bool hasFocus)
        {
            if (!hasFocus) NoteBackground();
        }

        /// <summary>
        /// ПРИЛОЖЕНИЕ УШЛО В ФОН. До первого нажатия это штатный диалог разрешений Android —
        /// выходим молча. После первого нажатия — прерываем прогон, пишем отчёт и завершаемся:
        /// кадров больше не будет, и продолжать нечего.
        ///
        /// ПОЧЕМУ ТОЛЬКО НА УСТРОЙСТВЕ. В редакторе и в ПК-сборке потеря фокуса окна НЕ
        /// останавливает кадры: прогон продолжается, и объявлять его прерванным значило бы выдать
        /// ложный вердикт из-за переключения окна тестировщиком. Сторож нужен там, где фон
        /// действительно останавливает рендер и корутину (Android/PICO — ровно случай планшета).
        /// </summary>
        private void NoteBackground()
        {
            if (finished || !pressStarted || run == null) return;
            if (!Application.isMobilePlatform) return;
            EmergencyFinish("приложение ушло в фон");
        }

        private void OnDestroy()
        {
            Application.focusChanged -= OnFocusChanged;
            if (active == this) active = null;
        }

        // ------------------------------------------------------------------ основной обход

        private IEnumerator Sweep()
        {
            startedAt = Time.realtimeSinceStartup;
            sceneName = SceneManager.GetActiveScene().name;
            run = new KvUiSweepRun();
            requestedMode = KvUiSweepFlags.ModeIndexOf(
                KvUiSweepFlags.ModeRequested(extras));
            SetLayout(KvUiSweepLayout.NameOf(sceneName, KvXrSettings.GetModeIndex(),
                Application.platform == RuntimePlatform.Android));

            // 1. ЖДЁМ ДВЕ ВЕЩИ СРАЗУ: СЦЕНА ПЕРЕСТАЛА МЕНЯТЬСЯ и интерфейс построен.
            //
            // ЧЕМ ЭТО ПЛОХО БЫЛО БЫ БЕЗ ОЖИДАНИЯ СЦЕНЫ. Первой в сборке грузится `BootAr`
            // (`KvArBoot`): она ждёт инициализацию XR, спрашивает разрешение камеры и только потом
            // грузит НАСТОЯЩУЮ сцену (`XrMain` / `ArMain`). Если начинать обход сразу после
            // первой сцены, интерфейса там ещё нет — прогон нашёл бы ноль элементов и объявил
            // провал в приложении, которое работает правильно.
            // ЧТО СТАЛО: ждём, пока имя активной сцены не повторится N кадров подряд И интерфейс
            // не поднимется. Ожидание ограничено ВРЕМЕНЕМ, а не кадрами: на холодном старте в
            // шлеме частота кадров низкая, и «600 кадров» — это не 10 секунд, а минуты.
            float waitDeadline = Time.realtimeSinceStartup + UiReadyWaitSeconds;
            string lastScene = "";
            int stable = 0;
            while (Time.realtimeSinceStartup < waitDeadline)
            {
                string now = SceneManager.GetActiveScene().name;
                if (now == lastScene && UiReady())
                {
                    if (++stable >= StableSceneFrames) break;
                }
                else
                {
                    stable = 0;
                    lastScene = now;
                }
                yield return null;
            }
            sceneName = SceneManager.GetActiveScene().name;
            // МАКЕТ УТОЧНЁН ПОСЛЕ ЗАГРУЗКИ НАСТОЯЩЕЙ СЦЕНЫ: на Android первой грузится `BootAr`,
            // и «vr» по ней означал бы не тот макет. Имя файла отчёта следует за макетом, поэтому
            // здесь именно `SetLayout`, а не прямое присваивание поля.
            SetLayout(KvUiSweepLayout.NameOf(sceneName, KvXrSettings.GetModeIndex(),
                Application.platform == RuntimePlatform.Android));

            // 2. ПОДГОТОВКА РЕЖИМА — ТОЛЬКО ПО ЯВНОМУ ФЛАГУ. Без флага режим VR/MR не трогается:
            // прогон обязан работать в том режиме, в который загрузилось приложение.
            if (requestedMode >= 0) yield return ApplyMode(requestedMode);

            // 3. ФАКТИЧЕСКИЙ РЕЖИМ — В ОТЧЁТ (запрошенный и фактический рядом: тестировщик должен
            // видеть, что переключение ПРОИЗОШЛО, а не только было запрошено).
            int factMode = KvXrSettings.GetModeIndex();
            SetLayout(KvUiSweepLayout.NameOf(sceneName, factMode,
                Application.platform == RuntimePlatform.Android));

            // ШАПКА ОТЧЁТА — ПОСЛЕ подготовки режима: иначе в ней стоял бы макет, посчитанный
            // ДО переключения VR/MR, и отчёт противоречил бы собственной строке «режим: факт=…».
            Header();

            // ПЛАТФОРМА — ЭТО НЕ ТО ЖЕ САМОЕ, ЧТО НАСТРОЙКА. `KvXrSettings` хранит ВЫБОР
            // оператора, а фактический режим приложения решает `KvXrPlatformModeSelector` по
            // возможностям устройства И применяет его при запуске. Печатаем оба: иначе
            // «запрошен=mr факт=mr» читалось бы как «приложение работает в MR», хотя сквозной вид
            // включается только после перезапуска (это прямо написано в самой панели настроек).
            KvXrPlatformMode platform = KvXrPlatformModeSelector.Current;
            Line("[KvUiSweep] режим: запрошен=" + KvUiSweepLayout.ModeName(requestedMode) +
                 " факт=" + KvUiSweepLayout.ModeName(factMode) +
                 " · платформа=" + platform +
                 " · сцена=" + sceneName + " · макет=" + run.Layout);
            if (requestedMode == KvXrSettings.ModeMr && platform != KvXrPlatformMode.Mr)
                Line("[KvUiSweep] ВНИМАНИЕ: настройка MR выставлена, но приложение запущено в " +
                     platform + " — сквозной вид применяется после ПЕРЕЗАПУСКА. Прогон идёт в " +
                     "фактическом режиме, и отчёт называет именно его");

            // 4. ПАНЕЛИ ПОСТРОЕНЫ? Ноль панелей — это ПРОВАЛ с причиной, а не «нечего проверять».
            int panels = CountPanels();
            if (panels == 0)
            {
                Line("[KvUiSweep] ПАНЕЛИ: ни одной не построено — обходить нечего");
                yield return Finish("панели не построены: интерактивных элементов 0 — проверять нечего");
                yield break;
            }

            // 5. СБОР ЭЛЕМЕНТОВ ИЗ ЖИВОЙ СЦЕНЫ (не из статического списка) И ОЧЕРЕДЬ ПО ПУТЯМ.
            //
            // ПОЧЕМУ ОЧЕРЕДЬ, А НЕ СПИСОК ССЫЛОК. Первый же переключатель панели настроек
            // перестраивает её содержимое: объекты уничтожаются, ссылки умирают. Обход по путям
            // позволяет найти пересозданный элемент заново и не обвинять работающую кнопку.
            var fresh = new List<Candidate>();
            CollectTargets(fresh);

            byKey.Clear();
            queue = new KvUiSweepQueue();
            ResetPcCounters();
            for (int i = 0; i < fresh.Count; i++)
            {
                Candidate c = fresh[i];
                if (string.IsNullOrEmpty(c.Key) || byKey.ContainsKey(c.Key)) continue;

                // ПК-ОКНА В ШЛЕМЕ НЕ ПЕРЕЧИСЛЯЮТСЯ: в раскладке vr/mr интерфейс компьютера
                // оператору не показывается, и десятки строк «элемент в скрытой панели» только
                // раздували отчёт. Печатается одна сводная строка, в счётчики они не входят.
                if (SkipAsPcWindow(c)) continue;

                // ПУНКТЫ СТАРТОВОГО МЕНЮ ШЛЕМА — В ОТДЕЛЬНЫЙ ПРОХОД: в общем проходе они
                // уничтожали бы друг друга (меню пересобирается целиком), но проверены быть обязаны.
                if (DeferStartMenuItem(c)) continue;

                byKey[c.Key] = c;
                // ЯРУС — по функции от пути/подписи/«открывает панель». Открывающие уйдут первыми,
                // разрушительные — в самый конец, даже если появятся посреди обхода.
                queue.Merge(c.Key, (int)KvUiSweepTiers.TierOf(c.Path, LabelOf(c), c.OpensPanel));
            }

            // 6. СТРОКА СТАРТА — ДО ПЕРВОГО НАЖАТИЯ. По ней видно, на каком элементе упало
            // приложение, если оно упадёт в середине обхода.
            //
            // ПУНКТЫ СТАРТОВОГО МЕНЮ СЧИТАЮТСЯ ЗДЕСЬ ЖЕ: они проверяются отдельным проходом и в
            // очередь не входят, но «элементов» обязано означать «сколько будет проверено» —
            // иначе в шлеме число выглядело бы обвалившимся, а порог `MinElements` объявил бы
            // провалом прогон, который на самом деле проверит десятки элементов.
            int menuItems = startMenuItems.Count;
            int plannedElements = queue.Total + menuItems;
            Line("[KvUiSweep] СТАРТ: режим=" + KvUiSweepLayout.ModeName(factMode) +
                 " сцена=" + sceneName + " элементов=" + plannedElements +
                 (menuItems > 0 ? " (в очереди " + queue.Total + ", меню отдельным проходом " +
                                  menuItems + ")" : "") +
                 " · панелей " + panels +
                 " · пропущено: ползунков прокрутки " + skippedScrollbars +
                 ", шаблонов списков " + skippedTemplates +
                 ", окон компьютера " + skippedWindowPanels +
                 " · путей-дублей " + duplicatePaths +
                 " · ярусы: открывающие " + queue.CountInTier(1) + ", обычные " + queue.CountInTier(2) +
                 ", стартовое меню " + queue.CountInTier(3) + ", разрушительные " + queue.CountInTier(4));
            ReportDuplicatePaths();
            string pcLine = KvUiSweepPcWindows.SummaryLine(pcSkipped, pcWorkbench, pcFeature, pcHint, pcShell);
            if (pcLine.Length > 0) Line(pcLine);
            EmitStartMenuSummary();

            if (plannedElements < KvUiSweepRun.MinElements)
            {
                yield return Finish("найдено " + plannedElements + " интерактивных элементов, порог " +
                                    KvUiSweepRun.MinElements + " — такой прогон ничего не доказывает");
                yield break;
            }

            // 7. ОБХОД ПО ОЧЕРЕДИ ПУТЕЙ. Очередь может расти по ходу (панель шлема раскрывает
            // уровни, интерфейс перестраивается), поэтому следующий путь запрашивается каждый раз.
            var seenPanelLevels = new HashSet<int>();
            int index = 0;
            while (true)
            {
                // ОБХОД ОСТАНОВЛЕН АВАРИЙНО (приложение ушло в фон) — дальше не нажимаем ничего.
                if (finished) yield break;

                // ОБЩИЙ ПРЕДЕЛ ВРЕМЕНИ. Проверка стоит ДО элемента, поэтому после её срабатывания
                // управление уходит в `Finish` и ИТОГ пишется ВСЕГДА — «остановить обход и не
                // написать итог» это и был дефект, из-за которого прогон на планшете не дал
                // вердикта вовсе.
                if (Time.realtimeSinceStartup - startedAt > TotalBudgetSeconds)
                {
                    Line("[KvUiSweep] ПРЕДЕЛ: " + TotalBudgetSeconds.ToString("0", CultureInfo.InvariantCulture) +
                         " с истекли — проверено " + index + " из " + queue.Total +
                         "; остальные НЕ ПРОВЕРЯЛИСЬ, итог ниже");
                    break;
                }

                string key = queue.Next();
                if (key == null) break;                       // очередь исчерпана

                Candidate c;
                if (!byKey.TryGetValue(key, out c)) { queue.Done(key); continue; }

                // ПЕРЕПОИСК ПЕРЕД НАЖАТИЕМ: ссылка могла умереть при перестроении интерфейса,
                // путь — нет. Работаем с НОВОЙ ссылкой.
                bool found = Locate(c);

                // ВОССТАНОВЛЕНИЕ ЭКРАНА ПАНЕЛИ ШЛЕМА (пункт 36 шапки). Путь элемента панели
                // существует ТОЛЬКО на его уровне, а панель пересобирается при каждом нажатии
                // (а открытое меню вообще гасит панель у руки). Поэтому до решения «исчез»
                // панель возвращается на экран элемента штатными путями — и если путь нашёлся
                // НЕ на своём экране (`Screen_Close` есть на каждом), тоже восстанавливаем.
                if (c.PanelBound && (!found || !PanelLevelMatches(c)))
                {
                    yield return RestorePanelElement(c);
                    found = Locate(c) && PanelLevelMatches(c);
                }

                if (!found)
                {
                    // НЕ НАЙДЕН — интерфейс мог измениться: пересобираем список и пробуем снова.
                    MergeFreshTargets();
                    found = Locate(c);
                    if (c.PanelBound && (!found || !PanelLevelMatches(c)))
                    {
                        yield return RestorePanelElement(c);
                        found = Locate(c) && PanelLevelMatches(c);
                    }
                    if (!found)
                    {
                        // ДОК-ПАНЕЛЬ ОБОЛОЧКИ (дефект D2, отчёт 13.11.2026): 31 элемент
                        // `…/KazistovVvDockCanvas/Dock_Настройки/…` «исчез», потому что канвас
                        // доков выключен, пока ни одна панель не запрошена, а раскладка из
                        // PlayerPrefs держит панель свёрнутой. Такой путь сначала ОТКРЫВАЕТСЯ
                        // штатной командой (`view.panel.settings` и т.п.) — и только если панель
                        // так и не открылась, элемент получает честную причину «панель не
                        // открыта», а НЕ «исчез».
                        string dockId = DockIdOfPath(KazistovVvUIManager.Instance, c.Path);
                        if (dockId.Length > 0)
                        {
                            yield return OpenDockPanelStep(c, dockId);
                            found = Locate(c);
                            if (!found)
                            {
                                RecordDockNotOpen(c, dockId);
                                queue.Done(key);
                                continue;
                            }
                        }
                        else
                        {
                            // ОТКЛАДЫВАЕМ: путь может снова появиться к концу прогона (AR-интерфейс
                            // перестраивается). Второй проход восстановит экран ЕЩЁ РАЗ и либо
                            // проверит элемент, либо назовёт «панель не открыта» с именем экрана —
                            // тихий «исчез» для элементов панели больше невозможен.
                            Defer(c, false, "");
                            queue.Done(key);
                            continue;
                        }
                    }
                }

                index++;
                yield return CheckOne(c, index, queue.Total);
                queue.Done(key);
                // РАСКРЫТИЕ УРОВНЯ — ПОСЛЕ проверки: состояние «что открылось» известно только
                // сразу после нажатия, и добавленные пункты встают в очередь этого же цикла.
                ExpandPanelLevels(c, seenPanelLevels);
            }

            // ВТОРОЙ ПРОХОД ПО ОТЛОЖЕННЫМ: исчезнувшие пути и элементы скрытых панелей, которые
            // могли открыться позже. Свой предел времени, ИТОГ пишется всегда.
            yield return RetryPass();

            // ОТДЕЛЬНЫЙ ПРОХОД ПО СТАРТОВОМУ МЕНЮ ШЛЕМА — В САМОМ КОНЦЕ. Именно в конце: пункты меню
            // меняют сессию (демо, новый проект) и закрывают меню, поэтому после них проверять
            // что-либо ещё было бы нельзя.
            yield return StartMenuPass();

            yield return Finish("");
        }

        /// <summary>
        /// ПРОВЕРКА ОДНОГО ЭЛЕМЕНТА: подготовка → строка `press=` → снимок ДО → нажатие →
        /// ОЖИДАНИЕ УСТОЙЧИВОСТИ (не дольше 1 с) → снимок ПОСЛЕ → строка отчёта → возврат
        /// состояния. Всё, что может бросить, поймано: одна упавшая кнопка не должна отменять
        /// прогон остальных (иначе «упало на 3-м из 80» = «не проверили 77»).
        /// </summary>
        private IEnumerator CheckOne(Candidate c, int index, int total)
        {
            if (finished) yield break;

            // СИСТЕМНЫЙ ШЛЮЗ ПРОПУСКАЕТСЯ ЦЕЛИКОМ — без подготовки и без нажатия.
            //
            // ЧТО БЫЛО (планшет, сборка 10:45). Первым же элементом нажалась кнопка
            // `GateButton«РАЗРЕШИТЬ КАМЕРУ»`: она вызывает системный диалог разрешений, приложение
            // ушло в фон, и 139 элементов из 140 не проверились никогда.
            if (c.SystemGate)
            {
                Record(new KvUiSweepElement
                {
                    Path = c.Path,
                    Kind = c.Kind,
                    Ok = false,
                    Effect = "не нажимали — системный шлюз",
                    ExemptReason = KvUiSweepExemptions.GateReason,
                    Method = "пропущен"
                });
                yield break;
            }

            // ССЫЛКА УМЕРЛА МЕЖДУ ПЕРЕПОИСКОМ И ПОДГОТОВКОЙ — это тоже «исчез», а НЕ «кнопка не
            // работает». Такое бывает, если интерфейс перестроился в том же кадре.
            if (!c.IsPanelIcon && c.Target == null)
            {
                yield return DeferOrRecordVanished(c);
                yield break;
            }

            string prepDetail;
            PrepResult prep = Prepare(c, out prepDetail);
            if (prep == PrepResult.HiddenPanel)
            {
                // СКРЫТАЯ ПАНЕЛЬ: не нажимаем и не обвиняем. Откладываем до второго прохода —
                // штатная кнопка может открыть панель позже, и тогда элемент проверится как надо.
                yield return DeferOrRecordHidden(c, prepDetail);
                yield break;
            }
            if (prep == PrepResult.Failed)
            {
                var blocked = new KvUiSweepElement
                {
                    Path = c.Path,
                    Kind = c.Kind,
                    Ok = false,
                    Effect = "не удалось подготовить: " + prepDetail,
                    Method = "нет"
                };
                Record(blocked);
                yield break;
            }

            // ПЕРЕПОИСК ПОСЛЕ ПОДГОТОВКИ. `ShowPanel`/`Rebuild` могли пересобрать панель — тогда
            // ссылка на кнопку устарела, и нажатие уходило в мёртвый объект («нет изменений» у
            // заведомо рабочих кнопок шапки дока). Путь переживает перестройку, ссылка — нет.
            if (!c.IsPanelIcon && !Locate(c))
            {
                yield return DeferOrRecordVanished(c);
                yield break;
            }

            var beforePanels = new List<KvUiSweepPanelState>(4);
            KvUiSweepSnapshot before = Capture(beforePanels);

            // РАЗДЕЛ МЕНЮ ДО НАЖАТИЯ — для правила «раздел уже открыт» (пункт 37 шапки).
            // Сверять состояние ПОСЛЕ нельзя: после удачного нажатия раздел и так открылся бы
            // на нужном номере, и правило вычёркивало бы УСПЕШНОЕ нажатие из «сработало».
            int sectionBefore = -1;
            KvXrGroupPanel sectionPanel = c.IsPanelIcon ? c.Panel : c.PanelOwner;
            if (sectionPanel != null) sectionBefore = (int)sectionPanel.StartSection;

            float t0 = Time.realtimeSinceStartup;

            // ОПАСНЫЕ ЭЛЕМЕНТЫ НЕ НАЖИМАЕМ: «Выход из приложения» завершает прогон раньше
            // итоговой строки, а пункт, ведущий в настройки Android, уводит приложение в фон и
            // останавливает кадры. Признак «свой/чужой» берётся из принадлежности панелям проекта,
            // поэтому штатная кнопка «Настройки» самого приложения остаётся нажимаемой.
            bool mayPress = KvUiSweepExemptions.ShouldPress(c.Path, c.ProjectOwned);
            if (!mayPress) notPressed++;

            string method = mayPress ? "" : "не нажимали";
            if (mayPress)
            {
                // СТРОКА ПЕРЕД НАЖАТИЕМ. Если приложение уйдёт в фон или зависнет ВНУТРИ нажатия,
                // эта строка останется последней в журнале и в файле отчёта — по ней виден виновник.
                pressStarted = true;
                Line(run.BeginPress(c.Path, c.Kind, index, total));
                try
                {
                    method = Press(c);
                }
                catch (Exception e)
                {
                    method = "исключение " + e.GetType().Name;
                    Line("[KvUiSweep] ОШИБКА нажатия «" + c.Path + "»: " + e.GetType().Name + ": " + e.Message);
                }
            }

            // ОЖИДАНИЕ УСТОЙЧИВОСТИ, а не «два кадра на глаз». Переключатель панели настроек
            // перестраивает её содержимое за несколько кадров, и снимок «после», взятый посреди
            // перестроения, терял эффект. Ожидание ограничено ЖЁСТКИМ пределом
            // (`KvUiSweepSettle.MaxSeconds`) — иначе вернулось бы зависание.
            yield return Settle(c);

            float spent = Time.realtimeSinceStartup - t0;
            var afterPanels = new List<KvUiSweepPanelState>(4);
            KvUiSweepSnapshot after = Capture(afterPanels);

            // ЭФФЕКТ СОБИРАЕТСЯ ИЗ ДВУХ ИСТОЧНИКОВ: общий отпечаток состояния (числа) и подробная
            // расшифровка изменений панелей («панель tree: свёрнута 0→1»). Одного отпечатка мало —
            // по нему не понять, ЧТО изменилось; одной расшифровки мало — если панель изменила
            // что-то, чего нет в списке полей, эффект потерялся бы.
            string effect = KvUiSweepDiff.Describe(before, after);
            string panelText = KvUiSweepPanelSig.Describe(beforePanels, afterPanels);
            if (panelText.Length > 0)
                effect = effect.Length > 0 ? effect + "; " + panelText : panelText;

            // ЧТО СКАЗАНО ОПЕРАТОРУ. Кнопки-сообщения («переназначение появится позже», «выполнять
            // нечего») меняют ТОЛЬКО строку статуса — без её текста в отчёте такие рабочие кнопки
            // выглядели бы мёртвыми.
            if (before.StatusHash != after.StatusHash)
            {
                string preview = StatusPreview(80);
                if (preview.Length > 0)
                    effect = (effect.Length > 0 ? effect + "; " : "") + "статус изменён: «" + preview + "»";
            }

            // ЧТО ИЗМЕНИЛОСЬ НА ПАНЕЛИ ШЛЕМА — запоминаем ДО возврата состояния: после `Restore`
            // панель уже на базовом уровне, и раскрывать следующий уровень было бы не из чего.
            if (c.IsPanelIcon && c.Panel != null)
            {
                c.ResultLevel = after.PanelLevel;
                c.ResultIcons = after.PanelIcons;
                int titles = c.Panel.IconCount;
                c.ResultTitles = new string[titles];
                for (int t = 0; t < titles; t++) c.ResultTitles[t] = c.Panel.TitleAt(t);
            }

            bool timedOut = spent > ElementBudgetSeconds;
            var element = new KvUiSweepElement
            {
                Path = c.Path,
                Kind = c.Kind,
                Ok = effect.Length > 0,
                Effect = mayPress ? effect : "не нажимали — правило запрещает (опасно для прогона)",
                Method = string.IsNullOrEmpty(c.PreparedBy) ? method : method + " · открыто: " + c.PreparedBy,
                TimedOut = timedOut
            };
            element.ExemptReason = ExemptReasonFor(c, sectionBefore);
            // НЕНАЖАТЫЙ ЭЛЕМЕНТ ОБЯЗАН БЫТЬ С ПРИЧИНОЙ (дефект D3, 13.11.2026). `mayPress == false`
            // — решение САМОГО прогона: он сознательно не трогает такой элемент (системный шлюз,
            // системный экран, выход). Без причины этот элемент считался «без эффекта», то есть
            // прогон обвинял бы кнопку, которую сам отказался нажимать (чистое состояние:
            // `GateButton«РАЗРЕШИТЬ КАМЕРУ»`).
            if (!mayPress && string.IsNullOrEmpty(element.ExemptReason))
                element.ExemptReason = KvUiSweepExemptions.UnpressedReasonFor(c.Path, c.ProjectOwned);

            if (timedOut)
            {
                element.Ok = false;
                element.Effect = "таймаут " + spent.ToString("0.0", CultureInfo.InvariantCulture) + " с" +
                                 (effect.Length > 0 ? " · " + effect : "");
            }

            Record(element);
            Restore(c, before, beforePanels);
            yield return null;
        }

        /// <summary>
        /// ПРИЧИНА ИСКЛЮЧЕНИЯ ДЛЯ ЭЛЕМЕНТА: недоступность → железо → системный экран вне панелей
        /// проекта. Порядок важен: «недоступен» — самое точное объяснение, и оно не должно
        /// подменяться общим «системный экран».
        /// </summary>
        /// <param name="sectionBefore">
        /// Открытый раздел стартового меню ДО нажатия (−1 — панель меню не участвует). Сверяется
        /// состояние ДО: после удачного нажатия раздел и так открылся бы на нужном номере, и
        /// правило закрывало бы УСПЕШНОЕ нажатие, вычёркивая его из «сработало».
        /// </param>
        private static string ExemptReasonFor(Candidate c, int sectionBefore)
        {
            // СИСТЕМНЫЙ ШЛЮЗ — САМОЕ ПЕРВОЕ И САМОЕ ТОЧНОЕ объяснение: это не «недоступен» и не
            // «нужно железо», а «это шлюз, а не интерфейс оператора». ФЛАГ ПРОВЕРЯЕТСЯ ВМЕСТЕ С
            // ПУТЁМ (дефект D3): решение «не нажимать» принимается по пути, поэтому и причина
            // обязана считаться по пути — иначе кандидат, собранный без флага, оставался бы
            // без объяснения и попадал в «без эффекта».
            if (c.SystemGate || KvUiSweepExemptions.IsGatePath(c.Path)) return KvUiSweepExemptions.GateReason;

            // СОСТОЯНИЕ AR: «ставить некуда» — с ФАКТИЧЕСКИМ числом плоскостей.
            string plane = KvUiSweepExemptions.PlaneReasonFor(c.Path, CountArPlanes());
            if (plane.Length > 0) return plane;

            if (!IsInteractable(c)) return KvUiSweepExemptions.DisabledReason;

            // ЗАКОННЫЕ «НИЧЕГО НЕ МЕНЯЮТ» — только с проверкой ФАКТИЧЕСКОГО состояния.
            // 1) Активная вкладка: нажатие на уже выбранный сегмент законно ничего не меняет.
            if (c.Target != null)
            {
                int elementIndex = KvUiSweepExemptions.SegmentIndexOfName(c.Target.gameObject.name);
                if (elementIndex >= 0)
                {
                    KvSegmented segmented = c.Target.GetComponentInParent<KvSegmented>();
                    if (segmented != null)
                    {
                        string tab = KvUiSweepExemptions.AlreadyActiveTabReasonFor(segmented.Index, elementIndex);
                        if (tab.Length > 0) return tab;
                    }
                }
            }

            // 2) Плашка, закрывающая меню: когда меню не открыто, закрывать нечего.
            string blocker = KvUiSweepExemptions.MenuBlockerReasonFor(c.Path, MenuOpenNow());
            if (blocker.Length > 0) return blocker;

            // 3) Строка дерева, которая УЖЕ выбрана: повторное нажатие выбор не меняет.
            if (c.Target != null)
            {
                KvTreeRow row = c.Target.GetComponent<KvTreeRow>();
                KazistovVvUIManager ui = KazistovVvUIManager.Instance;
                if (row != null && row.Node != null && ui != null && ui.SelectedNode == row.Node)
                    return KvUiSweepExemptions.TreeRowAlreadySelectedReason;
            }

            // 4) РАЗДЕЛ СТАРТОВОГО МЕНЮ, КОТОРЫЙ УЖЕ ОТКРЫТ ДО НАЖАТИЯ — законное «ничего не
            //    меняет», с проверкой ФАКТИЧЕСКОГО состояния ДО нажатия. Правило работает и для
            //    кнопки uGUI `MenuSec_*`, и для пункта панели (путь кончается подписью раздела):
            //    раньше оно смотрело только на `IsPanelIcon` и на имя «MenuSec» в пути, то есть
            //    не срабатывало ВООБСЕ (пункт 37 шапки). Состояние после нажатия сверять нельзя:
            //    после удачного нажатия раздел открылся бы на нужном номере, и правило вычёркивало
            //    бы УСПЕШНОЕ нажатие из «сработало».
            int elementSection = KvUiSweepStartMenu.IsSection(c.Path, SectionTitles())
                ? KvUiSweepStartMenu.OwnSection(c.Path, SectionTitles())
                : -1;
            if (elementSection >= 0)
            {
                string section = KvUiSweepExemptions.StartSectionAlreadyOpenReasonFor(
                    sectionBefore, elementSection);
                if (section.Length > 0) return section;
            }

            // 4b) СТРОКА МЕНЮ, ВЫЗЫВАЮЩАЯ КОМАНДУ РЕЕСТРА: если САМ реестр сейчас отвечает
            //     «недоступна», нажатие законно ничего не меняет — обработчик честно
            //     возвращается (пункт 38 шапки: «Сменить робота» → `robot.switch`, у которого
            //     `Enabled = роботов > 1`, а роботов к тому моменту ноль). Причина обязана
            //     опираться на ФАКТИЧЕСКОЕ состояние: команда читается из живого реестра здесь же,
            //     и если она включена — причины НЕТ, отсутствие эффекта остаётся находкой.
            string commandId = KvUiSweepStartMenu.RowCommandId(c.Path, LabelOf(c));
            if (commandId.Length > 0)
            {
                KvCommand command = KvCommands.Get(commandId);
                string detail = commandId == "robot.switch"
                    ? "роботов в сцене " + CountSceneRobots()
                    : "";
                string unavailable = KvUiSweepExemptions.CommandUnavailableReason(
                    commandId, command != null, command != null && command.Enabled, detail);
                if (unavailable.Length > 0) return unavailable;
            }

            // «ЗАКРЫТЬ», когда закрывать нечего: экран панели уже закрыт.
            if (c.IsPanelIcon && c.Panel != null &&
                c.Path.IndexOf("Screen_Close", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                string close = KvUiSweepExemptions.NothingToCloseReasonFor(
                    (int)c.Panel.Level, (int)KvXrPanelLevel.Groups);
                if (close.Length > 0) return close;
            }

            // 5) КНОПКА ШАПКИ ПАНЕЛИ, КОТОРАЯ УЖЕ В ЦЕЛЕВОМ СОСТОЯНИИ, И СТРЕЛКА ЛИСТА.
            if (c.Target != null)
            {
                KazistovVvUIManager manager = KazistovVvUIManager.Instance;
                KvDockPanel owner = c.Target.GetComponentInParent<KvDockPanel>();
                if (manager != null && owner != null)
                {
                    string inState = KvUiSweepExemptions.PanelHeaderAlreadyInStateReasonFor(
                        c.Target.gameObject.name, owner.Collapsed, owner.InRail);
                    if (inState.Length > 0) return inState;
                }

                // Стрелка раскрытия строки дерева: если у узла НЕТ детей — раскрывать нечего.
                if (c.Target.gameObject.name.IndexOf("Arrow", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    KvTreeRow row = c.Target.GetComponentInParent<KvTreeRow>();
                    if (row != null && row.Node != null)
                    {
                        bool hasChildren = row.Node.Children != null && row.Node.Children.Count > 0;
                        string leaf = KvUiSweepExemptions.LeafRowReasonFor(hasChildren);
                        if (leaf.Length > 0) return leaf;
                    }
                }

                // `ExpandAll`/`CollapseAll`, когда дерево уже в этом состоянии.
                KvTreeView tree = UnityEngine.Object.FindAnyObjectByType<KvTreeView>();
                if (tree != null)
                {
                    string treeReason = KvUiSweepExemptions.TreeAlreadyInStateReasonFor(
                        c.Target.gameObject.name, tree.ExpandedCount, tree.ExpandableCount);
                    if (treeReason.Length > 0) return treeReason;
                }
            }

            string reason = KvUiSweepExemptions.ReasonFor(c.Path);
            if (reason.Length > 0) return reason;
            return KvUiSweepExemptions.SystemScreenReason(c.Path, c.ProjectOwned);
        }

        /// <summary>
        /// СКОЛЬКО РОБОТОВ В СЦЕНЕ СЕЙЧАС — ФАКТИЧЕСКОЕ СОСТОЯНИЕ для причины про команду
        /// `robot.switch` (её `Enabled = роботов &gt; 1`). Счётчик менеджера для этого приватный,
        /// поэтому считаем сами тем же поиском: в причине идёт число, а не «наверное, мало».
        /// </summary>
        private static int CountSceneRobots()
        {
            RobotController[] robots = UnityEngine.Object.FindObjectsByType<RobotController>(
                FindObjectsInactive.Include);
            return robots != null ? robots.Length : 0;
        }

        /// <summary>
        /// ПРОПУСТИТЬ ЛИ ЭЛЕМЕНТ КАК ПК-ОКНО. Правило ТОЛЬКО для раскладок vr/mr: в шлеме окна
        /// компьютера (`KvWorkbenchWindow`, `KvFeatureWindow`, `KvHintCard`, оболочка ПК) не
        /// показываются, и десятки строк «элемент в скрытой панели» только раздували отчёт.
        /// В ar/pc возвращается false — там эти окна ПРОВЕРЯЮТСЯ как раньше.
        /// </summary>
        private bool SkipAsPcWindow(Candidate c)
        {
            if (c == null || run == null) return false;
            if (!KvUiSweepPcWindows.HiddenInLayout(run.Layout)) return false;
            if (!KvUiSweepPcWindows.IsPcOnly(c.Path)) return false;

            pcSkipped++;
            string kind = KvUiSweepPcWindows.KindOf(c.Path);
            if (kind == "KvWorkbenchWindow") pcWorkbench++;
            else if (kind == "KvFeatureWindow") pcFeature++;
            else if (kind == "KvHintCard") pcHint++;
            else pcShell++;
            return true;
        }

        /// <summary>
        /// ОТЛОЖИТЬ ЛИ ЭЛЕМЕНТ В ОТДЕЛЬНЫЙ ПРОХОД ПО СТАРТОВОМУ МЕНЮ.
        ///
        /// Только в раскладках vr/mr и только для пунктов меню: их нажатие пересобирает меню целиком
        /// и уничтожает остальные пункты (123 из 143 «исчезло» в VR). В ar/pc правило НЕ действует —
        /// там прогон уже зелёный, и ломать его нельзя.
        /// </summary>
        private bool DeferStartMenuItem(Candidate c)
        {
            if (c == null || run == null) return false;
            if (!KvUiSweepStartMenu.HelmetLayout(run.Layout)) return false;
            if (!KvUiSweepStartMenu.IsHelmetMenuPath(c.Path) &&
                !KvUiSweepTiers.IsStartMenuItem(c.Path, LabelOf(c))) return false;

            KvXrGroupPanel owner = c.PanelOwner != null ? c.PanelOwner : c.Panel;
            bool isSection = KvUiSweepStartMenu.IsSection(c.Path, SectionTitles());

            // РАЗДЕЛ, ОТКРЫТЫЙ ПРИ СБОРЕ: его строки проверяются в первой фазе (по путям uGUI),
            // поэтому во второй фазе он пропускается — иначе те же строки нажались бы дважды.
            // Для САМОГО раздела это НЕ его номер — см. ниже.
            if (startMenuCollectSection < 0)
                startMenuCollectSection = owner != null ? (int)owner.StartSection : 0;

            // СВОЙ РАЗДЕЛ ЭЛЕМЕНТА (пункт 37 шапки). У КНОПКИ РАЗДЕЛА — ЕЁ НОМЕР из имени
            // (`MenuSec_1` → 1): проход перед нажатием ставит `DifferentSection(записанный)`, и
            // если записан раздел СБОРА (0), а нажимается раздел 1, то `DifferentSection(0) = 1`
            // — и нажатие идёт на УЖЕ ОТКРЫТЫЙ раздел: экран не меняется, и рабочая кнопка
            // получает «нет изменений» (ровно так в отчёте 11.11.2026 провалился
            // `MenuSec_1«Робот»`). У СТРОКИ — раздел, в котором она была видна при сборе.
            IReadOnlyList<string> titles = SectionTitles();
            int section = isSection
                ? KvUiSweepStartMenu.OwnSection(c.Path, titles)
                : (owner != null ? (int)owner.StartSection : 0);
            if (section < 0) section = owner != null ? (int)owner.StartSection : 0;

            // КЛЮЧ УНИКАЛЬНОСТИ — С РАЗДЕЛОМ: `MenuRow_0` разных разделов это РАЗНЫЕ пункты, и
            // схлопывать их в один (как делает общий список путей) значило бы не проверить часть.
            string identity = c.Key + "·раздел" + section.ToString(CultureInfo.InvariantCulture);
            if (!startMenuKeys.Add(identity)) return false;

            // ССЫЛКА НЕ ХРАНИТСЯ: меню всё равно пересоберётся, и объект будет НОВЫЙ. Ищем по пути.
            if (!c.IsPanelIcon) c.Target = null;

            startMenuItems.Add(new StartMenuItem { Candidate = c, Section = section, IsSection = isSection });
            return true;
        }

        /// <summary>Обнулить счётчики ПК-окон перед первой сборкой (пересборка их НЕ сбрасывает).</summary>
        private void ResetPcCounters()
        {
            pcSkipped = 0;
            pcWorkbench = 0;
            pcFeature = 0;
            pcHint = 0;
            pcShell = 0;
        }

        /// <summary>ПОДПИСЬ КАНДИДАТА (для правил ярусов).</summary>
        private static string LabelOf(Candidate c)
        {
            return c != null ? (c.Label ?? "") : "";
        }

        /// <summary>ПОДПИСЬ ЭЛЕМЕНТА (для правил ярусов): текст своей или дочерней надписи.</summary>
        private static string LabelOf(GameObject go)
        {
            if (go == null) return "";
            Text own = go.GetComponent<Text>();
            Text label = own != null ? own : go.GetComponentInChildren<Text>(true);
            return label != null ? (label.text ?? "") : "";
        }

        /// <summary>Последний сегмент пути (имя объекта без подписи): `A/B/MenuSec_2«Стол»` → `MenuSec_2`.</summary>
        private static string LastSegmentOf(string path)
        {
            string key = KvUiSweepNames.KeyOf(path);
            if (string.IsNullOrEmpty(key)) return "";
            int slash = key.LastIndexOf('/');
            return slash < 0 ? key : key.Substring(slash + 1);
        }

        /// <summary>Открыто ли меню дока сейчас (для правила про закрывающую плашку).
        /// типу, а не через `ui.Menu`: это ТОТ ЖЕ объект, но поиск не зависит от того, какой из
        /// двух менеджеров (рантайм или его подмена в проверке) сейчас активен.
        /// </summary>
        private static bool MenuOpenNow()
        {
            KvMenuBar menu = UnityEngine.Object.FindAnyObjectByType<KvMenuBar>();
            return menu != null && menu.AnyOpen;
        }

        /// <summary>
        /// СПИСОК СОВПАВШИХ ПУТЕЙ. Молча выбросить дубль нельзя: два объекта с одним ключом — это
        /// ПОТЕРЯ ПОКРЫТИЯ (второй не будет проверен никогда), и она обязана быть видна числом и
        /// путями. После уникализации имён (`KvUiSweepNames.Segment`) дублей быть не должно, и
        /// строка «путей-дублей 0» это подтверждает.
        /// </summary>
        private void ReportDuplicatePaths()
        {
            if (collisions.Count == 0) return;

            Line("[KvUiSweep] ДУБЛИ ПУТЕЙ — ПОТЕРЯ ПОКРЫТИЯ (второй объект с тем же ключом не " +
                 "будет проверен никогда):");
            int shown = 0;
            foreach (KeyValuePair<string, int> pair in collisions)
            {
                if (shown >= 20)
                {
                    Line("  · …и ещё " + (collisions.Count - shown));
                    break;
                }
                Line("  · " + pair.Key + " — объектов " + (pair.Value + 1));
                shown++;
            }
        }

        /// <summary>
        /// СВОДКА ПО СТАРТОВОМУ МЕНЮ в строке СТАРТА: сколько пунктов ушло в отдельный проход и
        /// сколько из них разделов/строк. Без этой строки пункты меню просто «пропали» бы из чисел
        /// N/P/F/E, и покрытие выглядело бы хуже, чем есть.
        /// </summary>
        private void EmitStartMenuSummary()
        {
            if (startMenuItems.Count == 0) return;

            int sections = 0;
            int rows = 0;
            for (int i = 0; i < startMenuItems.Count; i++)
            {
                if (startMenuItems[i] == null) continue;
                if (startMenuItems[i].IsSection) sections++;
                else rows++;
            }
            Line(KvUiSweepStartMenu.SummaryLine(startMenuItems.Count, sections, rows));
        }

        /// <summary>Записать строку элемента в журнал и в отчёт.</summary>
        private void Record(KvUiSweepElement element)
        {
            Line(run.Add(element));
        }

        /// <summary>
        /// ОТЛОЖИТЬ ЭЛЕМЕНТ ДО ВТОРОГО ПРОХОДА (он в скрытой панели или временно исчез).
        /// Первый проход обязан идти дальше: панель может открыться от нажатия другой кнопки, и
        /// тогда элемент проверится в нормальном, штатном состоянии.
        /// </summary>
        private IEnumerator DeferOrRecordHidden(Candidate c, string panelPath)
        {
            if (inRetryPass)
            {
                // ВТОРОЙ ПРОХОД УЖЕ ИДЁТ — панель так и не открылась. Это НАХОДКА, и она
                // называется прямо: «панель не открывается ни одной кнопкой».
                Record(new KvUiSweepElement
                {
                    Path = c.Path,
                    Kind = c.Kind,
                    Ok = false,
                    Effect = "не нажимали — панель так и не открылась",
                    ExemptReason = KvUiSweepExemptions.HiddenPanelReasonFor(panelPath),
                    Method = "пропущен"
                });
                if (!string.IsNullOrEmpty(panelPath)) stuckPanels.Add(panelPath);
                yield break;
            }

            Defer(c, true, panelPath);
            yield break;
        }

        /// <summary>Отложить исчезнувший элемент: второй проход проверит, не появился ли он снова.</summary>
        private IEnumerator DeferOrRecordVanished(Candidate c)
        {
            if (inRetryPass)
            {
                Record(KvUiSweepElement.Vanished(c.Path, c.Kind));
                yield break;
            }
            Defer(c, false, "");
            yield break;
        }

        /// <summary>Положить элемент в список отложенных (без записи в отчёт).</summary>
        private void Defer(Candidate c, bool hidden, string panelPath)
        {
            if (c == null) return;
            if (!deferredKeys.Add(c.Key)) return;    // один элемент — одна отложенная запись
            deferred.Add(new DeferredElement { Candidate = c, Hidden = hidden, PanelPath = panelPath });
        }

        /// <summary>
        /// ВТОРОЙ ПРОХОД ПО ОТЛОЖЕННЫМ (исчезнувшие и скрытые в панелях). Один раз, в самом конце,
        /// с собственным пределом времени: AR-интерфейс перестраивается, и часть путей к концу
        /// прогона СНОВА существует — их надо проверить, а не записывать «исчез» навсегда.
        /// </summary>
        private IEnumerator RetryPass()
        {
            if (deferred.Count == 0) yield break;

            Line("[KvUiSweep] ВТОРОЙ ПРОХОД: отложенных элементов " + deferred.Count +
                 " (исчезнувшие и в скрытых панелях) — проверяем ещё раз");
            inRetryPass = true;
            float t0 = Time.realtimeSinceStartup;
            int checkedNow = 0;
            int notFound = 0;
            int notOpen = 0;
            int hiddenNow = 0;
            int stuckBefore = stuckPanels.Count;

            for (int i = 0; i < deferred.Count; i++)
            {
                if (finished) { inRetryPass = false; yield break; }

                if (Time.realtimeSinceStartup - t0 > RetryBudgetSeconds)
                {
                    Line("[KvUiSweep] ВТОРОЙ ПРОХОД: предел " +
                         RetryBudgetSeconds.ToString("0", CultureInfo.InvariantCulture) +
                         " с истекли — остальные отложенные остаются как есть, итог ниже");
                    break;
                }

                DeferredElement d = deferred[i];
                if (d == null || d.Candidate == null) continue;

                Candidate rc = d.Candidate;

                // ВОССТАНОВЛЕНИЕ ЭКРАНА ПАНЕЛИ — ПЕРЕД ЛЮБЫМ ОТКАЗОМ (пункт 36 шапки). Второй
                // проход — последняя возможность вернуть панель на экран элемента штатными
                // путями; только ПОСЛЕ неё элемент получает явную причину, а не «исчез».
                if (rc.PanelBound && (!Locate(rc) || !PanelLevelMatches(rc)))
                    yield return RestorePanelElement(rc);

                // ПРИЧИНА ПО КАЖДОМУ ЭЛЕМЕНТУ — иначе «обработано 0 из 32» ничего не объясняет.
                // НАЙДЕН = путь найден И панель на СВОЁМ уровне: путь, нашедшийся на чужом
                // экране (`Screen_Close`), — это не найденный элемент, а нажатие не туда.
                bool located = Locate(rc) && PanelLevelMatches(rc);
                if (!located) located = LocateShortened(rc) && PanelLevelMatches(rc);
                if (!located)
                {
                    // ЭКРАН ПАНЕЛИ НЕ ВОССТАНОВИЛСЯ — ЯВНАЯ ПРИЧИНА с именем экрана и деталью
                    // попыток. Это исключение (`панель не открыта`), а НЕ тихий «исчез»:
                    // обход обязан сказать, КАКОЙ именно экран не открылся.
                    if (rc.PanelBound)
                    {
                        notOpen++;
                        RecordPanelNotOpen(rc);
                        continue;
                    }

                    // ДОК-ПАНЕЛЬ ОБОЛОЧКИ (дефект D2): последняя попытка — ОТКРЫТЬ панель
                    // штатной командой и найти строку ещё раз. Если не вышло — честная
                    // «панель не открыта» с деталью, а НЕ «исчез» (31 «исчез» из отчёта 13.11).
                    string dockId = DockIdOfPath(KazistovVvUIManager.Instance, rc.Path);
                    if (dockId.Length > 0)
                    {
                        yield return OpenDockPanelStep(rc, dockId);
                        located = Locate(rc) && PanelLevelMatches(rc);
                        if (!located)
                        {
                            notOpen++;
                            RecordDockNotOpen(rc, dockId);
                            Line("[KvUiSweep] ВТОРОЙ ПРОХОД: " + rc.Path + " — панель не открыта");
                            continue;
                        }
                    }

                    notFound++;
                    Line("[KvUiSweep] ВТОРОЙ ПРОХОД: " + rc.Path + " — путь не найден");
                    if (d.Hidden)
                    {
                        Record(new KvUiSweepElement
                        {
                            Path = rc.Path,
                            Kind = rc.Kind,
                            Ok = false,
                            Effect = "не нажимали — панель так и не открылась",
                            ExemptReason = KvUiSweepExemptions.HiddenPanelReasonFor(d.PanelPath),
                            Method = "пропущен"
                        });
                        if (!string.IsNullOrEmpty(d.PanelPath)) stuckPanels.Add(d.PanelPath);
                    }
                    else
                    {
                        Record(KvUiSweepElement.Vanished(rc.Path, rc.Kind));
                    }
                    continue;
                }

                // ПОЯВИЛСЯ — проверяем обычным порядком. Если панель так и закрыта, `CheckOne`
                // запишет исключение и отметит панель как «не открывается».
                int hiddenBefore = stuckPanels.Count;
                retryIndex++;
                yield return CheckOne(d.Candidate, retryIndex, queue != null ? queue.Total : retryIndex);
                if (stuckPanels.Count > hiddenBefore)
                {
                    hiddenNow++;
                    Line("[KvUiSweep] ВТОРОЙ ПРОХОД: " +
                         d.Candidate.Path + " — панель не открыта");
                }
                else
                {
                    checkedNow++;
                    Line("[KvUiSweep] ВТОРОЙ ПРОХОД: " + d.Candidate.Path + " — проверен");
                }
            }

            inRetryPass = false;
            Line(run.RetrySummaryLine(checkedNow, hiddenNow, notFound,
                Time.realtimeSinceStartup - t0));
            if (notOpen > 0)
                Line("[KvUiSweep] ВТОРОЙ ПРОХОД: панель не открыта " + notOpen +
                     " — эти элементы получили причину «панель не открыта» с именем экрана " +
                     "(см. строки element=), а не «исчез»");
            if (stuckPanels.Count > stuckBefore)
                Line("[KvUiSweep] ВТОРОЙ ПРОХОД: панелей так и не открылось " +
                     (stuckPanels.Count - stuckBefore) + " — см. список ниже");
        }

        /// <summary>
        /// ОТДЕЛЬНЫЙ ПРОХОД ПО СТАРТОВОМУ МЕНЮ ШЛЕМА.
        ///
        /// ЧТО БЫЛО (шлем, сборка 23:58, чистое состояние). Меню открыто на весь экран, в обход
        /// попадают все его пункты сразу. Но нажатие раздела (`MenuSec_*`) и части строк
        /// (`MenuRow_*`) ПЕРЕСОБИРАЕТ меню целиком: `ClearIcons` уничтожает все иконки, и остальные
        /// пункты «исчезают» — 123 из 143 в VR, 162 из 184 в MR. Показывать меню заново после
        /// каждого нажатия мало: пересобранные объекты получают ДРУГИЕ подписи строк (в каждом
        /// разделе свои), поэтому путь `MenuRow_0` начинает означать не тот пункт.
        /// ЧТО СТАЛО. Пункты меню не входят в общую очередь (`DeferStartMenuItem`), а проверяются
        /// ЗДЕСЬ — по одному, в ДВЕ фазы:
        ///   ФАЗА 1 — пункты, собранные до нажатий (кнопки разделов и строки открытого раздела).
        ///     Перед КАЖДЫМ меню ставится в то состояние, в котором пункт был найден: открыто
        ///     (`KvXrStartMenu.Show`) и на записанном разделе (`KvXrGroupPanel.SelectStartSection` —
        ///     тот же метод, который вызывает нажатие раздела). Ссылка берётся заново по пути.
        ///   ФАЗА 2 — СТРОКИ ОСТАЛЬНЫХ РАЗДЕЛОВ: при сборе их объектов не существовало вовсе
        ///     (`BuildStartMenuLevel` строит иконки только для открытого раздела), поэтому раздел
        ///     открывается и его пункты нажимаются настоящим путём панели (`PressIndex`). Без этой
        ///     фазы «десятки проверенных» в шлеме недостижимы: проверялись бы одни кнопки разделов.
        /// </summary>
        private IEnumerator StartMenuPass()
        {
            if (startMenuItems.Count == 0) yield break;

            // МЕНЮ В СЦЕНЕ ЕСТЬ? Если объекта меню нет, нажимать нечего — и каждый пункт обязан быть
            // НАЗВАН в отчёте, а не пропасть: «молча непроверено» и есть та самая ложь покрытия.
            if (KvXrStartMenu.Active == null)
            {
                Line("[KvUiSweep] СТАРТОВОЕ МЕНЮ: объекта меню в сцене нет — пунктов " +
                     startMenuItems.Count + ", все остаются непроверенными");
                FlushUncheckedStartMenu(KvUiSweepStartMenu.NoMenuReason);
                yield break;
            }

            int sections = 0;
            int rows = 0;
            for (int i = 0; i < startMenuItems.Count; i++)
            {
                if (startMenuItems[i] == null) continue;
                if (startMenuItems[i].IsSection) sections++;
                else rows++;
            }

            Line(KvUiSweepStartMenu.PassLine(startMenuItems.Count, sections, rows));

            float t0 = Time.realtimeSinceStartup;
            int checkedNow = 0;
            int notFound = 0;
            string stopReason = "";
            // ПЛАН РАСТЁТ ПО ХОДУ: строки разделов становятся известны только после открытия
            // раздела, поэтому «из N» — это «из запланированных на этот момент».
            startMenuPlanned = startMenuItems.Count;

            for (int i = 0; i < startMenuItems.Count; i++)
            {
                if (finished) yield break;

                if (Time.realtimeSinceStartup - t0 > StartMenuPassBudgetSeconds)
                {
                    Line("[KvUiSweep] СТАРТОВОЕ МЕНЮ: предел " +
                         StartMenuPassBudgetSeconds.ToString("0", CultureInfo.InvariantCulture) +
                         " с истекли — проверено " + checkedNow + " из " + startMenuItems.Count +
                         ", остальные НЕ ПРОВЕРЯЛИСЬ");
                    stopReason = KvUiSweepStartMenu.BudgetReason;
                    break;
                }

                StartMenuItem item = startMenuItems[i];
                if (item == null || item.Candidate == null) continue;
                Candidate c = item.Candidate;

                // 1) МЕНЮ НА ЭКРАНЕ. `Show` — штатный путь показа (`OpenStartMenu` внутри), он же
                //    пересобирает список под текущий момент. После него ОБЯЗАТЕЛЬНЫЙ кадр: старые
                //    объекты уничтожаются в конце кадра, и без ожидания в индексе путей оказались бы
                //    сразу и старый, и новый `MenuRow_0` — нажали бы уничтожаемый.
                KvXrStartMenu menu = KvXrStartMenu.Active;
                if (StartMenuNeedsShow())
                {
                    menu.Show();
                    yield return null;
                }

                KvXrGroupPanel panel = StartMenuPanel();
                if (panel == null)
                {
                    Line("[KvUiSweep] СТАРТОВОЕ МЕНЮ: панель меню не найдена — проход остановлен, " +
                         "проверено " + checkedNow + " из " + startMenuItems.Count);
                    stopReason = KvUiSweepStartMenu.NoPanelReason;
                    break;
                }

                // 2) РАЗДЕЛ — ТОТ ЖЕ, ЧТО ПРИ СБОРЕ (для разделов — СОСЕДНИЙ, см. ниже).
                IReadOnlyList<string> titles = SectionTitles();
                int wanted = item.IsSection
                    ? KvUiSweepStartMenu.DifferentSection(item.Section, titles.Count)
                    : item.Section;
                if ((int)panel.StartSection != wanted)
                {
                    panel.SelectStartSection(wanted);
                    yield return null;                  // пересборка уничтожает объекты в конце кадра
                    panel = StartMenuPanel();
                    if (panel == null)
                    {
                        Line("[KvUiSweep] СТАРТОВОЕ МЕНЮ: панель меню исчезла после выбора раздела — " +
                             "проход остановлен, проверено " + checkedNow + " из " + startMenuItems.Count);
                        stopReason = KvUiSweepStartMenu.NoPanelReason;
                        break;
                    }
                }

                // 3) ССЫЛКА БОЛЬШЕ НЕ ГОДИТСЯ — берём элемент по пути (он и есть устойчивый ключ).
                if (c.IsPanelIcon)
                {
                    c.Panel = panel;
                    // НОМЕР ИКОНКИ ПЕРЕСЧИТЫВАЕТСЯ ПО ПОДПИСИ: после пересборки номера те же, но
                    // проверять это догадкой нельзя — ищем подпись, снятую при сборе.
                    int index = IconIndexOfTitle(panel, KvUiSweepStartMenu.LastSegment(c.Path));
                    if (index >= 0) c.Index = index;
                }
                else
                {
                    c.Target = null;
                }

                if (!Locate(c))
                {
                    notFound++;
                    string why = KvUiSweepStartMenu.NotFoundReason(c.Path);
                    Line("[KvUiSweep] СТАРТОВОЕ МЕНЮ: " + c.Path + " — " + why);
                    Record(new KvUiSweepElement
                    {
                        Path = c.Path,
                        Kind = c.Kind,
                        Ok = false,
                        Effect = why,
                        Method = "пропущен"
                    });
                    item.Done = true;
                    continue;
                }

                // 4) ПРОВЕРКА ОБЫЧНЫМ ПОРЯДКОМ (снимок «до/после», нажатие, возврат состояния).
                startMenuIndex++;
                yield return CheckOne(c, startMenuIndex, startMenuItems.Count);
                item.Done = true;
                checkedNow++;

                // 5) МЕНЮ ОБРАТНО НА ЭКРАН. Нажатие строки могло его закрыть («Вернуться к работе»),
                //    и тогда следующий пункт искать негде. Не вернулось — говорим прямо и
                //    останавливаемся: молча «проверено 3 из 12» выглядело бы как All done.
                yield return null;
                menu = KvXrStartMenu.Active;
                if (StartMenuNeedsShow()) menu.Show();
                yield return null;
                if (!StartMenuShown())
                {
                    Line(KvUiSweepStartMenu.RestoreFailed(c.Path));
                    Line("[KvUiSweep] СТАРТОВОЕ МЕНЮ: проверено " + checkedNow + " из " +
                         startMenuItems.Count + ", остальные НЕ ПРОВЕРЯЛИСЬ");
                    stopReason = KvUiSweepStartMenu.RestoreFailedReason;
                    break;
                }
            }

            // НИ ОДИН ПУНКТ НЕ ПРОПАДАЕТ МОЛЧА: если проход остановился раньше времени, остальные
            // попадают в отчёт строкой с причиной, а не исчезают из чисел.
            if (stopReason.Length > 0)
            {
                FlushUncheckedStartMenu(stopReason);
                Line(KvUiSweepStartMenu.PassResultLine(checkedNow, startMenuPlanned, notFound,
                    Time.realtimeSinceStartup - t0));
                yield break;   // предел/обрыв: вторая фаза уже не имеет смысла
            }

            // ---------------------------------------------------------------- ФАЗА 2
            // СТРОКИ ОСТАЛЬНЫХ РАЗДЕЛОВ. Их объектов при сборе НЕ БЫЛО ВОВСЕ: меню строит иконки
            // только для открытого раздела (`BuildStartMenuLevel` → `StartContentLabels`), поэтому
            // «Стол: …» видны лишь в разделе «Стол». Без этой фазы из 6 разделов проверялись бы
            // только кнопки разделов, а содержимое остальных не проверялось никогда — и число
            // проверенных в шлеме оставалось бы однозначным.
            //
            // КАК: раздел открывается штатным `SelectStartSection` (тот же метод, что вызывает
            // нажатие раздела), затем КАЖДАЯ иконка раздела нажимается настоящим путём панели
            // (`KvXrGroupPanel.PressIndex`). Раздел, который был открыт при сборе, пропускается —
            // его строки уже проверены выше по путям uGUI, и повторять их нельзя.
            int sectionNow = startMenuCollectSection;
            for (int s = 0; s < KvXrStartMenuLayout.SectionCount; s++)
            {
                if (finished) yield break;
                if (s == sectionNow) continue;

                if (Time.realtimeSinceStartup - t0 > StartMenuPassBudgetSeconds)
                {
                    Line("[KvUiSweep] СТАРТОВОЕ МЕНЮ: предел " +
                         StartMenuPassBudgetSeconds.ToString("0", CultureInfo.InvariantCulture) +
                         " с истекли — разделы после «" + KvXrStartMenuLayout.SectionTitle(s) +
                         "» НЕ ПРОВЕРЯЛИСЬ");
                    break;
                }

                // МЕНЮ И НУЖНЫЙ РАЗДЕЛ.
                yield return null;
                KvXrStartMenu menu = KvXrStartMenu.Active;
                if (StartMenuNeedsShow()) { menu.Show(); yield return null; }
                KvXrGroupPanel panel = StartMenuPanel();
                if (panel == null) { Line(KvUiSweepStartMenu.NoPanelReason); break; }
                if ((int)panel.StartSection != s)
                {
                    panel.SelectStartSection(s);
                    yield return null;                  // пересборка уничтожает объекты в конце кадра
                    panel = StartMenuPanel();
                    if (panel == null) { Line(KvUiSweepStartMenu.NoPanelReason); break; }
                }

                IReadOnlyList<string> titles = SectionTitles();
                int icons = panel.IconCount;
                int sectionRows = 0;
                for (int k = 0; k < icons; k++)
                    if (!KvUiSweepStartMenu.IsSection(panel.TitleAt(k), titles)) sectionRows++;
                if (sectionRows == 0)
                {
                    Line("[KvUiSweep] СТАРТОВОЕ МЕНЮ: раздел «" +
                         KvXrStartMenuLayout.SectionTitle(s) + "» — пунктов 0, проверять нечего");
                    continue;
                }

                startMenuPlanned += sectionRows;
                Line("[KvUiSweep] СТАРТОВОЕ МЕНЮ: раздел «" + KvXrStartMenuLayout.SectionTitle(s) +
                     "» — пунктов " + sectionRows);

                for (int k = 0; k < icons; k++)
                {
                    if (finished) yield break;
                    if (Time.realtimeSinceStartup - t0 > StartMenuPassBudgetSeconds) break;

                    string title = panel.TitleAt(k);
                    if (KvUiSweepStartMenu.IsSection(title, titles)) continue;   // разделы — выше
                    if (string.IsNullOrEmpty(title)) continue;

                    // ПУТЬ — ТОТ ЖЕ, ЧТО У ПУНКТА ПАНЕЛИ (`PanelPath`): он и в отчёте читается,
                    // и переживает пересборку.
                    string path = PanelPath((int)KvXrPanelLevel.StartMenu, title);
                    string key = KvUiSweepNames.KeyOf(path);
                    string identity = key + "·раздел" + s.ToString(CultureInfo.InvariantCulture);
                    if (!startMenuKeys.Add(identity)) continue;                  // уже проверяли

                    var c = new Candidate
                    {
                        Path = path,
                        Key = key,
                        Label = title,
                        Kind = KvUiSweepKind.PanelIcon,
                        Panel = panel,
                        Index = k,
                        PathIndices = new int[0],
                        ExpectedLevel = (int)KvXrPanelLevel.StartMenu,
                        Depth = 0,
                        ProjectOwned = true,
                        SystemGate = KvUiSweepExemptions.IsGatePath(path)
                    };

                    startMenuIndex++;
                    yield return CheckOne(c, startMenuIndex, startMenuPlanned);
                    checkedNow++;

                    // МЕНЮ МОГЛО ЗАКРЫТЬСЯ (строка «Вернуться к работе») — вернуть и проверить,
                    // тот ли это раздел: пересборка могла сбросить состояние.
                    yield return null;
                    menu = KvXrStartMenu.Active;
                    if (StartMenuNeedsShow()) { menu.Show(); yield return null; }
                    if (!StartMenuShown())
                    {
                        Line(KvUiSweepStartMenu.RestoreFailed(path));
                        yield break;
                    }
                    panel = StartMenuPanel();
                    if (panel == null) { Line(KvUiSweepStartMenu.NoPanelReason); yield break; }
                    if ((int)panel.StartSection != s)
                    {
                        panel.SelectStartSection(s);
                        yield return null;
                        panel = StartMenuPanel();
                        if (panel == null) { Line(KvUiSweepStartMenu.NoPanelReason); yield break; }
                        icons = panel.IconCount;      // состав раздела мог измениться
                    }
                }
            }

            Line(KvUiSweepStartMenu.PassResultLine(checkedNow, startMenuPlanned, notFound,
                Time.realtimeSinceStartup - t0));
        }

        /// <summary>
        /// ОСТАВШИЕСЯ ПУНКТЫ МЕНЮ — В ОТЧЁТ С ПРИЧИНОЙ. Вызывается, если проход остановился раньше
        /// времени: непроверенный пункт обязан быть назван строкой, иначе покрытие врёт молчанием.
        /// </summary>
        private void FlushUncheckedStartMenu(string reason)
        {
            int hidden = 0;
            for (int i = 0; i < startMenuItems.Count; i++)
            {
                StartMenuItem item = startMenuItems[i];
                if (item == null || item.Candidate == null || item.Done) continue;
                item.Done = true;
                hidden++;
                Record(new KvUiSweepElement
                {
                    Path = item.Candidate.Path,
                    Kind = item.Candidate.Kind,
                    Ok = false,
                    Effect = reason,
                    ExemptReason = reason,
                    Method = "пропущен"
                });
            }
            if (hidden > 0)
                Line("[KvUiSweep] СТАРТОВОЕ МЕНЮ: не проверено " + hidden +
                     " пунктов — причина: " + reason);
        }

        /// <summary>ПАНЕЛЬ СТАРТОВОГО МЕНЮ: сначала своя у меню, затем — живая панель шлема.</summary>
        private static KvXrGroupPanel StartMenuPanel()
        {
            KvXrStartMenu menu = KvXrStartMenu.Active;
            if (menu != null && menu.Panel != null) return menu.Panel;
            return ActivePanel();
        }

        /// <summary>
        /// НУЖНО ЛИ ПОКАЗЫВАТЬ МЕНЮ ЗАНОВО. Одного флага `Visible` мало: `RestoreBase` в сборе
        /// переводит панель меню на «иконки групп» (`CloseFan`), и флаг может остаться поднятым при
        /// уровне `Groups`. Тогда `MenuSec_*` в интерфейсе нет вообще, и проверять нечего — поэтому
        /// условие включает УРОВЕНЬ панели.
        /// </summary>
        private static bool StartMenuNeedsShow()
        {
            KvXrStartMenu menu = KvXrStartMenu.Active;
            if (menu == null) return false;
            if (!menu.Visible) return true;
            if (menu.Panel == null) return true;
            return (int)menu.Panel.Level != (int)KvXrPanelLevel.StartMenu;
        }

        /// <summary>МЕНЮ РЕАЛЬНО НА ЭКРАНЕ: показано И панель стоит на уровне стартового меню.</summary>
        private static bool StartMenuShown()
        {
            KvXrStartMenu menu = KvXrStartMenu.Active;
            if (menu == null || !menu.Visible || menu.Panel == null) return false;
            return (int)menu.Panel.Level == (int)KvXrPanelLevel.StartMenu;
        }

        /// <summary>
        /// НАЗВАНИЯ РАЗДЕЛОВ МЕНЮ — из раскладки, а не из головы. Нужны чистым правилам
        /// (`KvUiSweepStartMenu.IsSection`): у пункта ПАНЕЛИ в пути нет `MenuSec_*`, там подпись
        /// раздела, и «раздел или строка» можно решить только сверкой с раскладкой.
        /// </summary>
        private static IReadOnlyList<string> SectionTitles()
        {
            var titles = new List<string>(KvXrStartMenuLayout.SectionCount);
            for (int i = 0; i < KvXrStartMenuLayout.SectionCount; i++)
                titles.Add(KvXrStartMenuLayout.SectionTitle(i));
            return titles;
        }

        /// <summary>
        /// НОМЕР ИКОНКИ ПО ПОДПИСИ. Панель строит иконки кодом, и номер — это порядок построения;
        /// подпись — то, что видит оператор. После пересборки сверяем именно подпись.
        /// </summary>
        private static int IconIndexOfTitle(KvXrGroupPanel panel, string title)
        {
            if (panel == null || string.IsNullOrEmpty(title)) return -1;
            int count = panel.IconCount;
            for (int i = 0; i < count; i++)
                if (string.Equals(panel.TitleAt(i), title, StringComparison.Ordinal)) return i;
            return -1;
        }

        /// <summary>
        /// ДОЖДАТЬСЯ, ПОКА ИНТЕРФЕЙС УСПОКОИТСЯ. Условия выхода: элемент снова находится по пути И
        /// число объектов интерфейса не меняется `StableFrames` кадров подряд. ЖЁСТКИЙ предел —
        /// `KvUiSweepSettle.MaxSeconds` (проверяется и в условии цикла, и в самой функции решения:
        /// две независимые защиты от зависания).
        ///
        /// Если элемент исчез совсем — ждать его бессмысленно: обход пересоберёт список и назовёт
        /// его «исчез». Поэтому ждём только пока интерфейс МЕНЯЕТСЯ.
        /// </summary>
        private IEnumerator Settle(Candidate c)
        {
            float t0 = Time.realtimeSinceStartup;
            int previous = UiObjectCount();
            int stable = 0;
            bool reindexed = false;

            // ХОТЯ БЫ ОДИН КАДР — ВСЕГДА: нажатие обрабатывается внутри кадра, и снимок в том же
            // кадре показал бы состояние ДО него.
            yield return null;

            while (Time.realtimeSinceStartup - t0 < KvUiSweepSettle.MaxSeconds)
            {
                int now = UiObjectCount();

                bool found = IsAlive(c);
                if (!found && !reindexed)
                {
                    // ОДИН раз за ожидание: после перестроения панели ссылки мертвы, но путь жив.
                    reindexed = true;
                    RebuildUiIndex();
                    Selectable live = c.IsPanelIcon ? null : FindLive(c.Key);
                    if (live != null) c.Target = live;
                    if (c.IsPanelIcon && (c.Panel == null || !c.Panel.isActiveAndEnabled))
                        c.Panel = ActivePanel();
                    found = IsAlive(c);
                }

                if (!found)
                {
                    // Ждём, только пока интерфейс строится; исчезнувший элемент не ждём вовсе.
                    if (previous == now) break;
                    previous = now;
                    stable = 0;
                    yield return null;
                    continue;
                }

                if (!KvUiSweepSettle.ShouldWait(true, previous, now, stable,
                        Time.realtimeSinceStartup - t0))
                    break;

                if (now == previous) stable++;
                else stable = 0;
                previous = now;
                yield return null;
            }
        }

        /// <summary>Сколько объектов в канвасе оболочки сейчас (признак «интерфейс перестроился»).</summary>
        private static int UiObjectCount()
        {
            KazistovVvUIManager ui = KazistovVvUIManager.Instance;
            return ui != null ? ui.UiObjectCount : 0;
        }

        /// <summary>
        /// ПОДГОТОВКА ЭЛЕМЕНТА: что удалось и что делать дальше.
        /// `Ready` — можно нажимать; `HiddenPanel` — элемент в скрытой панели (не нажимаем, но и
        /// не обвиняем); `Failed` — подготовка не удалась по другой причине.
        /// </summary>
        private enum PrepResult { Ready, HiddenPanel, Failed }

        /// <summary>
        /// ПОДГОТОВКА ЭЛЕМЕНТА. Свёрнутая dock-панель открывается ШТАТНЫМ путём (`ShowPanel` —
        /// тот же, что у кнопки панели). Скрытые панели СИЛОЙ НЕ ВКЛЮЧАЮТСЯ: элемент из такой
        /// панели получает причину «сначала откройте её штатной кнопкой» и откладывается до
        /// второго прохода (панель может открыться позже).
        /// </summary>
        private PrepResult Prepare(Candidate c, out string detail)
        {
            detail = "";
            if (c.IsPanelIcon)
            {
                KvXrGroupPanel panel = c.Panel;
                if (panel == null) { detail = "панель шлема исчезла"; return PrepResult.Failed; }

                // ПУНКТ СТАРТОВОГО МЕНЮ ГОТОВИТСЯ СВОИМ ПУТЁМ — БЕЗ `RestoreBase`.
                //
                // ЧТО БЫЛО. `RestoreBase` уводит панель на «иконки групп»: `CloseScreen` у панели
                // меню только скрывает меню, а следующий за ним `CloseFan` переводит уровень в
                // `Groups` и пересобирает иконки. После этого `(int)panel.Level != ExpectedLevel`,
                // и КАЖДЫЙ пункт меню получал «не удалось подготовить: уровень панели Groups вместо
                // StartMenu» — то есть не проверялся вообще.
                // ЧТО СТАЛО: для уровня «стартовое меню» панель показывается штатным путём меню
                // (`KvXrStartMenu.Show` → `OpenStartMenu`), уровень остаётся StartMenu, номер иконки
                // сверяется по подписи. `RestoreBase` в этом случае НЕ вызывается.
                if ((KvXrPanelLevel)c.ExpectedLevel == KvXrPanelLevel.StartMenu)
                {
                    KvXrStartMenu menu = KvXrStartMenu.Active;
                    if (menu != null && (menu.Panel == panel) && !menu.Visible) menu.Show();
                    if (menu != null && menu.Panel == panel && (int)panel.Level == c.ExpectedLevel)
                    {
                        c.PreparedBy = "показ стартового меню (Show)";
                        // НОМЕР ИКОНКИ — ПО ПОДПИСИ: показа меню пересобирает иконки, и номер
                        // обязан означать ТОТ ЖЕ пункт, что и в отчёте.
                        int byTitle = IconIndexOfTitle(panel, KvUiSweepStartMenu.LastSegment(c.Path));
                        if (byTitle >= 0) c.Index = byTitle;
                        if (c.Index >= panel.IconCount)
                        {
                            detail = "иконки " + c.Index + " на уровне нет";
                            return PrepResult.Failed;
                        }
                        return PrepResult.Ready;
                    }
                }

                // ПАНЕЛЬ УЖЕ НА ЗАПИСАННОМ УРОВНЕ (экран восстановлен перед проверкой) — `RestoreBase`
                // НЕ ВЫЗЫВАЕТСЯ: он пересобрал бы содержимое и уничтожил только что найденную
                // иконку, а нажатие ушло бы в объект, уничтожаемый в конце кадра. И цепочка
                // `PathIndices` тоже НЕ нажимается: её номера — это номера на БАЗОВОМ уровне, и
                // на уже открытом уровне они указывали бы на чужие иконки.
                bool levelKnown = c.PanelBound && (int)panel.Level == c.ExpectedLevel;
                if (!levelKnown)
                {
                    RestoreBase(panel);
                    if (c.PathIndices != null)
                    {
                        for (int i = 0; i < c.PathIndices.Length; i++)
                        {
                            if (c.PathIndices[i] >= panel.IconCount)
                            {
                                detail = "уровень панели не восстановлен (нет иконки " + c.PathIndices[i] + ")";
                                return PrepResult.Failed;
                            }
                            panel.PressIndex(c.PathIndices[i]);
                        }
                    }
                }
                if ((int)panel.Level != c.ExpectedLevel)
                {
                    detail = "уровень панели " + panel.Level + " вместо " + (KvXrPanelLevel)c.ExpectedLevel;
                    return PrepResult.Failed;
                }
                if (c.Index >= panel.IconCount) { detail = "иконки " + c.Index + " на уровне нет"; return PrepResult.Failed; }
                return PrepResult.Ready;
            }

            Selectable target = c.Target;
            if (target == null) { detail = "элемент исчез между перепоиском и подготовкой"; return PrepResult.Failed; }

            // ЭЛЕМЕНТ В СВЁРНУТОЙ/СКРЫТОЙ ПАНЕЛИ.
            Transform gate = TopInactiveAncestor(target.gameObject);
            if (gate == null) return PrepResult.Ready;

            // 1) Панель оболочки — открывается ШТАТНЫМ путём (тот же, что у кнопки панели).
            KazistovVvUIManager ui = KazistovVvUIManager.Instance;
            if (ui != null)
            {
                string[] ids = { "tree", "properties", "settings", "hotkeys" };
                for (int i = 0; i < ids.Length; i++)
                {
                    KvDockPanel dock = ui.DockById(ids[i]);
                    if (dock == null || dock.Root == null) continue;
                    if (gate != dock.Root && !gate.IsChildOf(dock.Root)) continue;
                    // ШТАТНЫЙ ПУТЬ: команда оператора, а при необходимости и сам менеджер —
                    // он же сбрасывает уехавшую раскладку (см. `OpenDockPanel`).
                    c.PreparedBy = OpenDockPanel(ui, ids[i]);
                    c.Container = ids[i];

                    // ПРОВЕРКА ФАКТА, А НЕ НАДЕЖДЫ. На планшете `ShowPanel(tree)` вернул
                    // управление, а панель осталась неактивной: кнопки её шапки нажимались в
                    // выключенной иерархии, `Button.OnPointerClick` молча выходил по `IsActive()`,
                    // и рабочие кнопки получали «нет изменений». Теперь такой элемент честно
                    // попадает в «панель не открыта», а не в дефекты интерфейса.
                    if (TopInactiveAncestor(target.gameObject) != null)
                    {
                        detail = PathOf(gate);
                        return PrepResult.HiddenPanel;
                    }
                    return PrepResult.Ready;
                }
            }

            // 2) ПАНЕЛЬ ШЛЕМА: сначала ШТАТНАЯ пересборка, затем ЕЁ ЖЕ публичный показ канваса.
            //
            // ЗАЧЕМ ВТОРОЙ ШАГ (шлем, свежая сборка). В VR содержимое панели (`ПанельШлема/…`)
            // лежит в скрытом канвасе панели: `Rebuild` его не включает, и 48 элементов из 70
            // уходили в «скрытая панель», а проверялся ОДИН. Показ канваса — ПУБЛИЧНЫЙ метод самой
            // панели (`KvXrGroupPanel.SetArVisible`), то есть тот же штатный путь, которым панель
            // показывает слой AR; это НЕ `SetActive` на произвольном предке. Состояние канваса
            // запоминается и возвращается после проверки элемента.
            if (c.PanelOwner != null)
            {
                KvXrGroupPanel owner = c.PanelOwner;

                // ЭЛЕМЕНТ УЖЕ НА СВОЁМ УРОВНЕ (экран восстановлен перед проверкой) — ЛИШНЯЯ
                // ПЕРЕСБОРКА РАЗРУШИЛА БЫ только что найденный объект: `ClearIcons` уничтожает
                // иконки, и нажатие ушло бы в объект, уничтожаемый в конце кадра. Пересбираем
                // только когда уровень НЕ совпал — тогда содержимое действительно надо собрать.
                bool levelKnown = c.PanelBound && (int)owner.Level == c.ExpectedLevel;
                if (!levelKnown) owner.Rebuild(true);
                if (TopInactiveAncestor(target.gameObject) == null)
                {
                    if (!levelKnown) c.PreparedBy = "пересборка панели";
                    return PrepResult.Ready;
                }

                // Стартовое меню открывается своим штатным методом (`Show` → `OpenStartMenu`).
                KvXrStartMenu menu = KvXrStartMenu.Active;
                if (menu != null && menu.Panel == owner && !menu.Visible)
                {
                    menu.Show();
                    c.ShowedStartMenu = true;
                    if (TopInactiveAncestor(target.gameObject) == null)
                    {
                        c.PreparedBy = "показ стартового меню (Show)";
                        return PrepResult.Ready;
                    }
                }

                if (!owner.IsCanvasVisible)
                {
                    c.ShowedPanel = owner;
                    c.ShowedPanelWasVisible = false;
                    owner.SetArVisible(true);              // штатный публичный показ канваса панели
                    if (TopInactiveAncestor(target.gameObject) == null)
                    {
                        c.PreparedBy = "показ канваса панели (SetArVisible)";
                        return PrepResult.Ready;
                    }
                }
            }

            // 3) ОСТАЛЬНОЕ — СКРЫТАЯ ПАНЕЛЬ. СИЛОЙ НЕ ВКЛЮЧАЕМ (см. `MayActivate`): включённая
            // силой панель не перестроена под текущее состояние, и её кнопки «нажимаются»
            // впустую — так и появились ложные «нет изменений» у вкладок панели команд AR.
            detail = PathOf(gate);
            return PrepResult.HiddenPanel;
        }

        // ============================================== ДОК-ПАНЕЛИ: ОТКРЫТИЕ И ПРИЧИНА (D2)

        /// <summary>
        /// ОТКРЫТЬ ДОК-ПАНЕЛЬ ШТАТНЫМ ПУТЁМ — НЕЗАВИСИМО ОТ СОХРАНЁННОГО СОСТОЯНИЯ РАСКЛАДКИ.
        ///
        /// ПОРЯДОК ТРИ ШАГА И ВАЖЕН:
        ///   1) КОМАНДА ОПЕРАТОРА (`view.panel.settings` и т.п.) — ровно то, что нажимает человек;
        ///   2) ЕСЛИ ПАНЕЛИ НЕТ НА ЭКРАНЕ — `ShowPanel` самого менеджера: он включает флаг,
        ///      поднимает канвас панелей и, если раскладка «уехала» (PlayerPrefs с другого
        ///      разрешения/ориентации), возвращает сторону, толщину и свёрнутость по умолчанию;
        ///   3) ЕСЛИ ПАНЕЛЬ СВЁРНУТА — раскрыть: свёрнутость живёт в том же PlayerPrefs и
        ///      переживает любые «восстановления экрана» (дефект D2, отчёт 13.11.2026).
        /// Возвращает, ЧЕМ открыли — для строки `открыто:` в отчёте.
        /// </summary>
        private static string OpenDockPanel(KazistovVvUIManager ui, string dockId)
        {
            if (ui == null || string.IsNullOrEmpty(dockId)) return "";
            KvDockPanel panel = ui.DockById(dockId);
            if (panel == null) return "";

            string how = "";
            string command = KvUiSweepDockNav.OpenCommandFor(dockId);
            if (!ui.IsPanelEffectivelyVisible(dockId))
            {
                // КОМАНДА ТОЛЬКО КОГДА ПАНЕЛИ НА ЭКРАНЕ НЕТ: `view.panel.settings` — это
                // TogglePanel, и на УЖЕ видимой панели она бы её ЗАКРЫЛА (а следующая за ней
                // проверка снова открыла — лишнее уничтожение и пересборка содержимого).
                if (command.Length > 0)
                {
                    try
                    {
                        if (KvCommands.Invoke(command)) how = "команда " + command;
                    }
                    catch (Exception e)
                    {
                        Debug.LogWarning("[KvUiSweep] команда открытия панели «" + command +
                                         "» упала: " + e.GetType().Name + ": " + e.Message);
                    }
                }

                if (!ui.IsPanelEffectivelyVisible(dockId))
                {
                    ui.ShowPanel(dockId);         // штатный путь менеджера + сброс раскладки
                    how = how.Length > 0
                        ? how + " + ShowPanel(" + dockId + ")"
                        : "ShowPanel(" + dockId + ")";
                }
            }

            if (panel.Collapsed)
            {
                panel.SetCollapsed(false);        // раскладка из PlayerPrefs: свёрнута — раскрыть
                how = how.Length > 0 ? how + " + раскрыта свёрнутая" : "раскрыта свёрнутая";
            }
            return how.Length > 0 ? how : "панель уже открыта";
        }

        /// <summary>
        /// ОТКРЫТЬ ПАНЕЛЬ И ДОКРУТИТЬ СПИСОК К СТРОКЕ (корутина). Кадр на пересборку обязателен:
        /// команда включает канвас и перекладывает панель, а индекс путей пересобирается следующим
        /// шагом — без паузы поиск работал бы на старом индексе.
        /// </summary>
        private IEnumerator OpenDockPanelStep(Candidate c, string dockId)
        {
            KazistovVvUIManager ui = KazistovVvUIManager.Instance;
            string how = OpenDockPanel(ui, dockId);
            if (!string.IsNullOrEmpty(how)) c.PreparedBy = how;
            yield return null;
            yield return null;
            ScrollDockTo(c.Target);
        }

        /// <summary>
        /// ДОКРУТИТЬ СПИСОК ПАНЕЛИ К СТРОКЕ ЭЛЕМЕНТА. Нужен, чтобы строка была не только в
        /// иерархии, но и В ВИДИМОЙ ЧАСТИ списка (иначе у виртуализированных списков её просто
        /// ещё не построили, а у обычного — оператор не увидит, что её проверяли). Лучший случай:
        /// прокрутки нет или высота контента не больше вьюпорта — тогда нечего и двигать.
        /// </summary>
        private static void ScrollDockTo(Selectable target)
        {
            if (target == null) return;
            try
            {
                ScrollRect scroll = target.GetComponentInParent<ScrollRect>();
                if (scroll == null || scroll.content == null) return;
                RectTransform item = target.transform as RectTransform;
                RectTransform viewport = scroll.viewport != null
                    ? scroll.viewport
                    : scroll.transform as RectTransform;
                if (item == null || viewport == null) return;

                Canvas.ForceUpdateCanvases();
                float viewHeight = viewport.rect.height;
                float contentHeight = scroll.content.rect.height;
                if (viewHeight <= 1f || contentHeight <= viewHeight) return;

                float top = -item.anchoredPosition.y;   // расстояние строки от верха контента
                float center = top + item.rect.height * 0.5f;
                float normalized = Mathf.Clamp01(
                    (center - viewHeight * 0.5f) / (contentHeight - viewHeight));
                scroll.verticalNormalizedPosition = 1f - normalized;
            }
            catch (Exception e)
            {
                Debug.LogWarning("[KvUiSweep] прокрутка списка к строке не удалась: " +
                                 e.GetType().Name + ": " + e.Message);
            }
        }

        /// <summary>id док-панели, которой принадлежит путь элемента (`""` — путь не дока).</summary>
        private static string DockIdOfPath(KazistovVvUIManager ui, string path)
        {
            if (ui == null || !KvUiSweepDockNav.IsDockPath(path)) return "";
            for (int i = 0; i < KvUiSweepDockNav.Ids.Length; i++)
            {
                string id = KvUiSweepDockNav.Ids[i];
                KvDockPanel panel = ui.DockById(id);
                if (panel == null || panel.Root == null) continue;
                if (path.IndexOf("/" + panel.Root.name + "/", StringComparison.Ordinal) >= 0)
                    return id;
            }
            return "";
        }

        /// <summary>
        /// ПОЧЕМУ ПАНЕЛЬ НЕ ОТКРЫЛАСЬ — ДЕТАЛЬ ДЛЯ ПРИЧИНЫ. Названа ФАКТИЧЕСКИМ состоянием
        /// (флаг, канвас, свёрнутость, размер), а не догадкой: по этой строке видно, что именно
        /// мешает проверке.
        /// </summary>
        private static string DockNotOpenDetail(KazistovVvUIManager ui, string dockId)
        {
            if (ui == null) return "менеджера интерфейса нет";
            KvDockPanel panel = ui.DockById(dockId);
            if (panel == null) return "панели нет в оболочке";
            if (!ui.IsPanelVisible(dockId))
                return "панель не показана: канвас доков выключен, пока ни одна панель не запрошена";
            if (panel.Collapsed) return "панель свёрнута (раскладка из PlayerPrefs)";
            if (!ui.IsPanelEffectivelyVisible(dockId))
                return "панель не попадает в экран: " + ui.DescribeDock(panel);
            return "панель открыта, но строка не найдена: " + ui.DescribeDock(panel);
        }

        /// <summary>
        /// ЗАПИСАТЬ ЭЛЕМЕНТ С ЧЕСТНОЙ ПРИЧИНОЙ «панель не открыта». Это ИСКЛЮЧЕНИЕ, а не «исчез»
        /// и не «без эффекта»: панель названа, деталь — по факту, а счётчик «исчезло» не растёт.
        /// </summary>
        private void RecordDockNotOpen(Candidate c, string dockId)
        {
            string detail = DockNotOpenDetail(KazistovVvUIManager.Instance, dockId);
            string reason = KvUiSweepDockNav.NotOpenReasonFor(dockId, detail);
            Line("[KvUiSweep] ПАНЕЛЬ ДОКА НЕ ОТКРЫЛАСЬ: " + c.Path + " — " + reason);
            Record(new KvUiSweepElement
            {
                Path = c.Path,
                Kind = c.Kind,
                Ok = false,
                Effect = "не нажимали — панель не открыта",
                ExemptReason = reason,
                Method = "пропущен"
            });
        }

        /// <summary>
        /// ВОЗВРАТ СОСТОЯНИЯ после элемента: закрыть открытую панель, выключить принудительно
        /// включённый предок, ВЕРНУТЬ СОСТОЯНИЕ DOCK-ПАНЕЛЕЙ, сбросить выделение uGUI и отменить
        /// переключения настроек, которые сделало нажатие. Без этого следующий элемент проверялся
        /// бы «в чужом» состоянии, и эффект приписывался бы не той кнопке.
        /// </summary>
        private void Restore(Candidate c, KvUiSweepSnapshot before, List<KvUiSweepPanelState> beforePanels)
        {
            try
            {
                if (EventSystem.current != null) EventSystem.current.SetSelectedGameObject(null);

                if (!string.IsNullOrEmpty(c.Container))
                {
                    KazistovVvUIManager ui = KazistovVvUIManager.Instance;
                    if (ui != null) ui.SetPanel(c.Container, false);
                    c.Container = "";
                }

                if (c.IsPanelIcon && c.Panel != null) RestoreBase(c.Panel);

                // ВОЗВРАТ ПОКАЗА ПАНЕЛИ ШЛЕМА: если канвас включал прогон — выключаем обратно,
                // иначе следующий элемент проверялся бы в другом мире (и «эффект» приписался бы
                // не той кнопке).
                if (c.ShowedStartMenu)
                {
                    KvXrStartMenu menu = KvXrStartMenu.Active;
                    if (menu != null) menu.Hide();
                    c.ShowedStartMenu = false;
                }
                if (c.ShowedPanel != null)
                {
                    c.ShowedPanel.SetArVisible(c.ShowedPanelWasVisible);
                    c.ShowedPanel = null;
                }

                RestoreContext(before);

                // ПАНЕЛИ ДОКА — ОБРАТНО В ИСХОДНОЕ. «Свернуть», «причалить» и «в рейл» меняют
                // состояние панели НАСОВСЕМ (оно сохраняется в PlayerPrefs как выбор оператора).
                // Если не вернуть, прогон оставит интерфейс разобранным, а следующий элемент
                // проверится на свёрнутой панели — и «без эффекта» получит уже невиновная кнопка.
                RestorePanels(beforePanels);
                // ПРОВЕРКА ВОССТАНОВЛЕНИЯ. Если состояние панели осталось чужим, следующий элемент
                // проверится не в том мире, и «нет эффекта» получит невиновная кнопка (ровно на это
                // намекали провалы кнопки «в рейл» у панели дерева). Молчать об этом нельзя.
                VerifyPanelRestore(beforePanels);

                // ОТМЕНА ПЕРЕКЛЮЧЕНИЙ: режим VR/MR, язык и комфорт — настройки, которые
                // переключатель меняет НАВСЕГДА (они пишутся в PlayerPrefs). Если не вернуть их,
                // прогон уедет в другой режим и «проверит» уже не то приложение.
                if (KvXrSettings.GetModeIndex() != before.ModeIndex)
                    KvXrSettings.SetModeIndex(before.ModeIndex);

                int languageNow = LanguageIndex();
                if (before.Language >= 0 && languageNow != before.Language)
                {
                    string code = LanguageCode(before.Language);
                    if (!string.IsNullOrEmpty(code)) KvLoc.SetLanguage(code);
                }

                if (ComfortValue() != before.Comfort)
                {
                    // Возвращаем И признак виньетки, И силу: иначе «кнопка комфорта» оставила бы
                    // следующий элемент в чужом состоянии.
                    KvXrSettings.SetVignetteEnabled(before.Comfort >= 1000);
                    KvXrSettings.SetVignetteStrength(KvUiSweepSettings.ComfortStrength(before.Comfort));
                }

                // ВИДИМОСТЬ ОБОЛОЧКИ ТОЖЕ НАЗАД (дефект D4, 13.11.2026). Команда `ui.toggle`
                // («Показать/скрыть интерфейс») гасит оболочку целиком, и раньше `Restore`
                // возвращал панели дока, режим, язык и `KvSettings`, но НЕ `uiVisible`: канвас
                // оставался выключенным, и 12 элементов `Cmd_*` не проверялись вторым проходом —
                // их путей в мире без интерфейса просто не существовало.
                KazistovVvUIManager shell = KazistovVvUIManager.Instance;
                if (shell != null && KvUiSweepUiVisible.NeedsRestore(before.UiVisible, shell.uiVisible))
                    KazistovVvUIManager.SetUiVisible(KvUiSweepUiVisible.Target(before.UiVisible));

                // ФЛАГИ ОБОЛОЧКИ — ТОЖЕ НАЗАД: переключатель «Фонарик» пишет в `KvSettings` и
                // сохраняется в PlayerPrefs, поэтому без возврата следующий элемент проверялся бы
                // в чужом состоянии (и мог бы «случайно» дать эффект).
                RestoreUiSettings(before);
            }
            catch (Exception e)
            {
                Debug.LogWarning("[KvUiSweep] возврат состояния после «" + c.Path + "»: " +
                                 e.GetType().Name + ": " + e.Message);
            }
        }

        /// <summary>
        /// ВОССТАНОВИТЬ КОНТЕКСТ ПОСЛЕ НАЖАТИЯ: если ДО нажатия стартовое меню было открыто, а после
        /// закрылось — открыть его СНОВА штатным путём (`KvXrStartMenu.Show`). То же для панели
        /// шлема: была показана и погасла — вернуть в показанное.
        ///
        /// ЗАЧЕМ (шлем, сборка 21:36). «Показать демо» закрыло стартовое меню, контекст не
        /// восстановился, и ВСЕ оставшиеся разделы меню «исчезли»: 21 элемент пропал, а 49 остались
        /// в скрытых панелях. Прогон обязан возвращать тот мир, в котором он проверяет.
        /// </summary>
        private void RestoreContext(KvUiSweepSnapshot before)
        {
            KvUiSweepSnapshot now = Capture();

            // 1) СТАРТОВОЕ МЕНЮ.
            if (KvUiSweepContext.NeedsRestore(before.StartMenuVisible, now.StartMenuVisible))
            {
                KvXrStartMenu menu = KvXrStartMenu.Active;
                bool restored = false;
                if (menu != null)
                {
                    menu.Show();
                    restored = menu.Visible;
                }
                contextRestores++;
                if (!restored || contextRestores <= 10)
                    Line(KvUiSweepContext.RestoreLine("стартовое меню", restored));
            }

            // 2) ПАНЕЛЬ ШЛЕМА: была показана (уровень был снят) и погасла.
            if (KvUiSweepContext.NeedsRestore(before.StartMenuVisible == 0 ? 1 : 0, now.StartMenuVisible) &&
                before.PanelLevel >= 0)
            {
                KvXrGroupPanel panel = ActivePanel();
                if (panel != null && !panel.IsCanvasVisible)
                {
                    panel.SetArVisible(true);
                    contextRestores++;
                    Line(KvUiSweepContext.RestoreLine("панель шлема", panel.IsCanvasVisible));
                }
            }
        }

        /// <summary>
        /// ВЕРНУТЬ ФЛАГИ ОБОЛОЧКИ в состояние ДО нажатия. Каждый сеттер `KvSettings` сам пишет в
        /// PlayerPrefs, поэтому сравнение «было/стало» обязательно: иначе каждое нажатие сохраняло
        /// бы значение заново и дёргало перестроение интерфейса без нужды.
        /// </summary>
        private static void RestoreUiSettings(KvUiSweepSnapshot before)
        {
            if (KvSettings.ShowWorkspace != (before.SetWorkspace != 0))
                KvSettings.ShowWorkspace = before.SetWorkspace != 0;
            if (KvSettings.ShowJointLimits != (before.SetJointLimits != 0))
                KvSettings.ShowJointLimits = before.SetJointLimits != 0;
            if (KvSettings.ShowMetrics != (before.SetMetrics != 0))
                KvSettings.ShowMetrics = before.SetMetrics != 0;
            if (KvSettings.Flashlight != (before.SetFlashlight != 0))
                KvSettings.Flashlight = before.SetFlashlight != 0;
            if (KvSettings.AutoRefreshTree != (before.SetAutoTree != 0))
                KvSettings.AutoRefreshTree = before.SetAutoTree != 0;
            if (KvSettings.ShowPhantoms != (before.SetPhantoms != 0))
                KvSettings.ShowPhantoms = before.SetPhantoms != 0;
            if (KvSettings.Density != before.SetDensity) KvSettings.Density = before.SetDensity;
            if (KvSettings.ToolbarRows != before.SetToolbarRows) KvSettings.ToolbarRows = before.SetToolbarRows;
            if (KvSettings.ToolbarLayout != before.SetToolbarLayout)
                KvSettings.ToolbarLayout = before.SetToolbarLayout;
            if (KvSettings.ToolbarCompact != (before.SetToolbarCompact != 0))
                KvSettings.ToolbarCompact = before.SetToolbarCompact != 0;
            if (KvSettings.FontSize != before.SetFontSize) KvSettings.FontSize = before.SetFontSize;
            if (KvSettings.HighContrast != (before.SetHighContrast != 0))
                KvSettings.HighContrast = before.SetHighContrast != 0;
            if (KvSettings.ColorBlind != before.SetColorBlind) KvSettings.ColorBlind = before.SetColorBlind;
            if (KvSettings.KeyboardNav != (before.SetKeyboardNav != 0))
                KvSettings.KeyboardNav = before.SetKeyboardNav != 0;
            if (KvSettings.GamepadHud != (before.SetGamepadHud != 0))
                KvSettings.GamepadHud = before.SetGamepadHud != 0;
            if (KvSettings.ErrorPlate != (before.SetErrorPlate != 0))
                KvSettings.ErrorPlate = before.SetErrorPlate != 0;
        }

        /// <summary>
        /// ПРОВЕРКА, ЧТО СОСТОЯНИЕ ПАНЕЛЕЙ ВЕРНУЛОСЬ. Молчаливое «не вернулось» — это скрытая
        /// причина ложных «нет эффекта» у следующих элементов. Каждый такой случай называется.
        /// </summary>
        private void VerifyPanelRestore(List<KvUiSweepPanelState> beforePanels)
        {
            if (beforePanels == null || beforePanels.Count == 0) return;
            KazistovVvUIManager ui = KazistovVvUIManager.Instance;
            if (ui == null) return;

            for (int i = 0; i < beforePanels.Count; i++)
            {
                KvUiSweepPanelState before = beforePanels[i];
                KvDockPanel panel = ui.DockById(before.Id);
                if (panel == null) continue;

                string diff = KvUiSweepPanelSig.DescribeOne(before.Id, before, PanelStateOf(before.Id, panel));
                if (diff.Length == 0) continue;

                restoreFailures++;
                if (restoreFailures <= 10)
                    Line("[KvUiSweep] ВНИМАНИЕ: состояние панели не восстановлено — " + diff);            }
        }

        /// <summary>
        /// ВЕРНУТЬ DOCK-ПАНЕЛИ В ИСХОДНОЕ СОСТОЯНИЕ. Порядок важен: `SetCollapsed` сбрасывает
        /// рейл, а `ToRail` сбрасывает свёрнутость — поэтому сначала сторона, потом рейл, потом
        /// свёрнутость, и только затем видимость.
        /// </summary>
        private static void RestorePanels(List<KvUiSweepPanelState> beforePanels)
        {
            if (beforePanels == null || beforePanels.Count == 0) return;
            KazistovVvUIManager ui = KazistovVvUIManager.Instance;
            if (ui == null) return;

            for (int i = 0; i < beforePanels.Count; i++)
            {
                KvUiSweepPanelState s = beforePanels[i];
                KvDockPanel panel = ui.DockById(s.Id);
                if (panel == null) continue;

                // ШАГИ И ПОРЯДОК — ИЗ ЧИСТОЙ ФУНКЦИИ (`RestoreSteps`), чтобы правило было одно
                // и проверялось тестом.
                IList<string> steps = KvUiSweepPanelSig.RestoreSteps(s, PanelStateOf(s.Id, panel));
                for (int k = 0; k < steps.Count; k++)
                {
                    switch (steps[k])
                    {
                        case "side": panel.SetSide((KvDockSide)s.Side); break;
                        case "rail":
                            if (s.InRail != 0) panel.ToRail(); else panel.FromRail();
                            break;
                        case "collapsed": panel.SetCollapsed(s.Collapsed != 0); break;
                        case "shown": panel.SetVisible(s.Shown != 0); break;
                    }
                }
            }
        }

        // ------------------------------------------------------------------ сбор элементов

        /// <summary>
        /// ПЕРЕСОБРАТЬ ИНДЕКС «ПУТЬ → ЖИВОЙ ЭЛЕМЕНТ».
        ///
        /// ЗАЧЕМ ИНДЕКС, А НЕ СПИСОК ССЫЛОК. Нажатие переключателя панели настроек перестраивает
        /// панель: объекты уничтожаются и создаются заново, а собранные ранее ссылки `Selectable`
        /// становятся мёртвыми. Путь (`KvUiSweepNames.KeyOf`) — устойчивый ключ, ссылка — нет.
        /// Индекс пересобирается ровно тогда, когда путь не нашёлся, поэтому 45 ложных обвинений
        /// «элемент уничтожен» больше не появляются.
        /// </summary>
        private void RebuildUiIndex()
        {
            pathIndex.Clear();
            duplicatePaths = 0;
            collisions.Clear();

            Canvas[] canvases = UnityEngine.Object.FindObjectsByType<Canvas>(
                FindObjectsInactive.Include);

            // ОДИН ОБЪЕКТ — ОДИН РАЗ. Вложенный канвас попадает и в родительский обход, и в свой
            // собственный: без этой проверки один и тот же `Selectable` считался бы «дублем пути»,
            // и настоящие совпадения имён терялись бы в шуме (на планшете так и вышло — «дублей 45»).
            var seen = new HashSet<Selectable>();

            for (int i = 0; i < canvases.Length; i++)
            {
                Canvas canvas = canvases[i];
                if (canvas == null) continue;
                // «Активный канвас» — тот, что сейчас участвует в иерархии. Элементы ВНУТРИ
                // свёрнутых панелей тоже берём (`true`): иначе половина интерфейса выпала бы из
                // проверки ровно потому, что её не видно.
                if (!canvas.gameObject.activeInHierarchy) continue;

                Selectable[] all = canvas.GetComponentsInChildren<Selectable>(true);
                for (int k = 0; k < all.Length; k++)
                {
                    Selectable s = all[k];
                    if (s == null) continue;
                    if (!seen.Add(s)) continue;

                    string key = KvUiSweepNames.KeyOf(PathOf(s.transform));
                    if (string.IsNullOrEmpty(key)) continue;

                    if (pathIndex.ContainsKey(key))
                    {
                        // РАЗНЫЕ объекты с ОДНИМ ключом — это ПОТЕРЯ ПОКРЫТИЯ: второй объект не
                        // будет проверен никогда. Считаем и называем в отчёте, а не глотаем.
                        duplicatePaths++;
                        int count;
                        collisions.TryGetValue(key, out count);
                        collisions[key] = count + 1;
                        continue;
                    }
                    pathIndex[key] = s;
                }
            }
        }

        /// <summary>
        /// НАЙТИ ЖИВОЙ ЭЛЕМЕНТ ПО КЛЮЧУ. Сначала — по текущему индексу (дёшево). Не нашлось или
        /// ссылка мертва — ПЕРЕСОБРАТЬ индекс и попробовать ещё раз: именно так пересозданный
        /// объект находится по своему пути.
        /// </summary>
        private Selectable FindLive(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;

            Selectable s;
            if (pathIndex.TryGetValue(key, out s) && s != null) return s;

            RebuildUiIndex();
            if (pathIndex.TryGetValue(key, out s) && s != null) return s;
            return null;
        }

        /// <summary>
        /// НАЙТИ ЭЛЕМЕНТ ОЧЕРЕДИ В ЖИВОМ ИНТЕРФЕЙСЕ. Возвращает true, если элемент есть и ссылка
        /// в кандидате обновлена. Ложь — элемента нет: тогда решение принимает обход (пересборка
        /// списка, затем «исчез»).
        /// </summary>
        private bool Locate(Candidate c)
        {
            if (c == null) return false;

            if (c.IsPanelIcon)
            {
                // Панель шлема могли пересоздать (перезапуск сцены) — тогда берём живую. ЖИВУЮ,
                // НО НЕ ЛЮБУЮ: если ссылка ещё существует, подменять её нельзя, иначе кандидат
                // одной панели начнёт нажимать иконки другой.
                if (c.Panel == null) c.Panel = ActivePanel();
                return c.Panel != null && c.Panel.isActiveAndEnabled;
            }

            if (c.Target != null) return true;              // ссылка ещё жива
            Selectable s = FindLive(c.Key);
            if (s == null) return false;
            c.Target = s;                                   // РАБОТАЕМ С НОВОЙ ССЫЛКОЙ
            return true;
        }

        /// <summary>
        /// НАЙТИ ЭЛЕМЕНТ ПО УКОРОЧЕННОМУ КЛЮЧУ (только второй проход). После перестроения
        /// интерфейса путь часто меняется в ПОСЛЕДНИХ сегментах (контейнер пересобрался), а начало
        /// остаётся. Берём совпадение по префиксу и только если оно единственное.
        /// </summary>
        private bool LocateShortened(Candidate c)
        {
            if (c == null || c.IsPanelIcon) return false;

            RebuildUiIndex();
            var keys = new List<string>(pathIndex.Keys);
            string resolved = KvUiSweepNames.ResolveKey(c.Key, keys);
            if (string.IsNullOrEmpty(resolved)) return false;

            Selectable found;
            if (!pathIndex.TryGetValue(resolved, out found) || found == null) return false;

            c.Target = found;
            c.PreparedBy = "по укороченному пути";
            Line("[KvUiSweep] ВТОРОЙ ПРОХОД: " + c.Path + " — найден по укороченному ключу " + resolved);
            return true;
        }

        /// <summary>ЖИВ ЛИ ЭЛЕМЕНТ (без пересборки индекса) — для ожидания устойчивости.</summary>
        private static bool IsAlive(Candidate c)
        {
            if (c == null) return false;
            if (c.IsPanelIcon) return c.Panel != null && c.Panel.isActiveAndEnabled;
            return c.Target != null;
        }

        /// <summary>
        /// ПОЛНЫЙ СБОР ЦЕЛЕЙ: uGUI + пункты панели шлема. Используется и на старте, и при
        /// ПЕРЕСБОРЕ во время обхода (когда путь перестал находиться — интерфейс изменился).
        /// </summary>
        private void CollectTargets(List<Candidate> into)
        {
            skippedScrollbars = 0;
            skippedTemplates = 0;
            skippedWindowPanels = 0;
            RebuildUiIndex();
            CollectUgui(into);
            CollectPanelIcons(into);
            ReorderDestructiveLast(into);
        }

        /// <summary>
        /// <summary>
        /// ПЕРЕСБОРКА СПИСКА ВО ВРЕМЯ ОБХОДА. Новые элементы встают в СВОЙ ЯРУС (открывающие —
        /// вперёд, разрушительные — в конец), непроверенные остаются, проверенные не возвращаются.
        /// </summary>
        private int MergeFreshTargets()
        {
            if (queue == null || queue.Total >= MaxElements) return 0;

            var fresh = new List<Candidate>();
            CollectTargets(fresh);

            int added = 0;
            for (int i = 0; i < fresh.Count; i++)
            {
                Candidate c = fresh[i];
                if (string.IsNullOrEmpty(c.Key)) continue;
                if (byKey.ContainsKey(c.Key)) continue;
                if (SkipAsPcWindow(c)) continue;            // ПК-окна в шлеме не проверяются
                if (DeferStartMenuItem(c)) continue;         // стартовое меню — отдельным проходом
                byKey[c.Key] = c;
                added += queue.Merge(c.Key, (int)KvUiSweepTiers.TierOf(c.Path, LabelOf(c), c.OpensPanel));
            }

            if (added > 0)
                Line("[KvUiSweep] ПЕРЕСБОРКА: интерфейс изменился — новых элементов " + added +
                     ", осталось проверить " + queue.Count);
            return added;
        }

        /// <summary>
        /// СБОР ЭЛЕМЕНТОВ uGUI ИЗ ЖИВОЙ СЦЕНЫ: все активные `Canvas`, в них — реальные
        /// `Selectable` (Button / Toggle / Slider / Dropdown / InputField, включая TMP-варианты,
        /// которые отличаются только именем типа). Список НЕ статический: что построено, то и
        /// проверяется.
        /// </summary>
        private void CollectUgui(List<Candidate> into)
        {
            Canvas[] canvases = UnityEngine.Object.FindObjectsByType<Canvas>(
                FindObjectsInactive.Include);
            var seen = new HashSet<Selectable>();

            for (int i = 0; i < canvases.Length; i++)
            {
                Canvas canvas = canvases[i];
                if (canvas == null) continue;
                // «Активный канвас» — тот, что сейчас участвует в иерархии. Элементы ВНУТРИ
                // свёрнутых панелей тоже берём (`true`): иначе половина интерфейса выпала бы из
                // проверки ровно потому, что её не видно.
                if (!canvas.gameObject.activeInHierarchy) continue;

                Selectable[] all = canvas.GetComponentsInChildren<Selectable>(true);
                for (int k = 0; k < all.Length; k++)
                {
                    Selectable s = all[k];
                    if (s == null) continue;
                    if (!seen.Add(s)) continue;

                    if (UnderTemplate(s.transform)) { skippedTemplates++; continue; }

                    KvUiSweepKind kind;
                    if (!Classify(s, out kind)) { skippedScrollbars++; continue; }

                    string path = PathOf(s.transform);
                    string key = KvUiSweepNames.KeyOf(path);
                    if (string.IsNullOrEmpty(key)) continue;

                    string label = LabelOf(s.gameObject);
                    var candidate = new Candidate
                    {
                        Path = path,
                        Key = key,
                        Label = label,
                        Kind = kind,
                        Target = s,
                        ProjectOwned = IsProjectOwned(s.transform),
                        OpensPanel = KvUiSweepTiers.OpensPanel(path, label),
                        SystemGate = KvUiSweepExemptions.IsGatePath(path),
                        PanelOwner = s.GetComponentInParent<KvXrGroupPanel>()
                    };
                    RecordPanelRoute(candidate);
                    into.Add(candidate);
                    if (into.Count >= MaxElements) return;
                }
            }
        }

        /// <summary>
        /// СБОР ПУНКТОВ, КОТОРЫЕ ПАНЕЛЬ ШЛЕМА СОЗДАЁТ КОДОМ. Это не `Selectable`: иконки строит
        /// `KvXrGroupPanel` и нажимает их `PressIndex` — штатным путём луча. Без них в VR/MR
        /// проверялась бы только оболочка компьютера, а именно панель у руки владелец и нажимает.
        /// </summary>
        private void CollectPanelIcons(List<Candidate> into)
        {
            KvXrGroupPanel[] panels = UnityEngine.Object.FindObjectsByType<KvXrGroupPanel>(
                FindObjectsInactive.Exclude);

            for (int i = 0; i < panels.Length; i++)
            {
                KvXrGroupPanel panel = panels[i];
                if (panel == null || !panel.isActiveAndEnabled) continue;

                // ОКНА КОМПЬЮТЕРА ПРОПУСКАЮТСЯ ОСОЗНАННО. Крестик такого окна его ЗАКРЫВАЕТ, и
                // обход, вернув «базовый уровень», уничтожил бы проверяемую панель вместе с
                // оставшимися пунктами: прогон покраснел бы на исправном интерфейсе. Окна
                // проверяются отдельно (их строки и вкладки — часть `KvXrDesktopWindows`).
                if (panel.isWindow) { skippedWindowPanels++; continue; }

                RestoreBase(panel);
                int count = panel.IconCount;
                int level = (int)panel.Level;
                for (int k = 0; k < count; k++)
                {
                    if (into.Count >= MaxElements) return;
                    string path = PanelPath(level, panel.TitleAt(k));
                    var icon = new Candidate
                    {
                        Path = path,
                        Key = KvUiSweepNames.KeyOf(path),
                        Kind = KvUiSweepKind.PanelIcon,
                        Panel = panel,
                        PanelOwner = panel,
                        Index = k,
                        PathIndices = new int[0],
                        ExpectedLevel = level,
                        Depth = 0
                    };
                    RecordPanelRoute(icon);
                    into.Add(icon);
                }
            }
        }

        /// <summary>
        /// ЦЕПОЧКА ОТ БАЗЫ ДЛЯ ЭЛЕМЕНТА, РАСКРЫТОГО ИЗ УЖЕ ОТКРЫТОГО УРОВНЯ. Панель в момент
        /// раскрытия стоит на БАЗОВОМ уровне (`RestoreBase` отработал в `CheckOne`), поэтому
        /// первый шаг цепочки — подпись иконки, которой панель на этот уровень попала: для веера
        /// это иконка группы, для экрана — иконка его самого (экраны достижимы от базы напрямую,
        /// минуя веер). Если подпись прочитать не удалось — откат к раскладке (`ChainFor`),
        /// а если и она не знает уровня — `null`, и элемент честно получит «панель не открыта».
        /// </summary>
        private static string[] BuildBaseChain(KvXrGroupPanel panel, int[] path, int level)
        {
            KvXrPanelLevel lvl = (KvXrPanelLevel)level;
            if (panel != null && path != null && path.Length >= 1)
            {
                string first = panel.TitleAt(path[0]);
                if (!string.IsNullOrEmpty(first)) return new[] { first };
            }
            return KvUiSweepPanelNav.ChainFor(lvl, -1, null, KvXrGroupPanel.ScreenTitle(lvl));
        }

        /// <summary>
        /// ЗАПИСАТЬ МАРШРУТ ЭЛЕМЕНТА ПАНЕЛИ ШЛЕМА: ЕГО уровень в момент сбора, цепочка штатных
        /// нажатий от базы до этого уровня и имя уровня для причины «панель не открыта».
        ///
        /// ЗАЧЕМ ЗДЕСЬ, А НЕ ПРИ ПРОВЕРКЕ. Путь элемента панели существует ТОЛЬКО на своём
        /// уровне (`ClearIcons` уничтожает содержимое другого уровня), а к моменту проверки
        /// панель уже перестроилась десятки раз. Единственное место, где уровень ещё честно
        /// известен, — момент сбора: элемент физически лежит на этом уровне. Уровень окна
        /// компьютера получает цепочку по подписи экрана — рантайм попробует и без неё и в
        /// конце даст честную причину.
        /// </summary>
        private void RecordPanelRoute(Candidate c)
        {
            if (c == null) return;
            KvXrGroupPanel owner = c.PanelOwner != null ? c.PanelOwner : c.Panel;
            if (owner == null) return;

            c.PanelBound = true;
            c.ExpectedLevel = (int)owner.Level;
            KvXrPanelLevel screenLevel = owner.isWindow ? owner.WindowScreen : owner.Level;
            string screenTitle = KvXrGroupPanel.ScreenTitle(screenLevel);
            c.RestoreScreenTitle = KvUiSweepPanelNav.LevelTitle(owner.Level, screenTitle);
            c.RestoreChain = KvUiSweepPanelNav.ChainFor(owner.Level, owner.OpenGroupIndex,
                GroupTitles(), screenTitle);
        }

        /// <summary>
        /// ПОДПИСИ ГРУПП НА БАЗОВОМ УРОВНЕ — ИЗ РАСКЛАДКИ ТУЛБАРА, а не с живой панели: к
        /// моменту восстановления панель перестроена, а раскладка (`KvToolbarGroups`) константна
        /// и совпадает с тем, что панель рисует на базовом уровне.
        /// </summary>
        private static List<string> GroupTitles()
        {
            KvToolbarGroup[] groups = KvToolbarGroups.All;
            var titles = new List<string>(groups != null ? groups.Length : 0);
            if (groups == null) return titles;
            for (int i = 0; i < groups.Length; i++)
                titles.Add(groups[i] != null ? (groups[i].Title ?? "") : "");
            return titles;
        }

        /// <summary>
        /// УРОВЕНЬ ПАНЕЛИ СОВПАДАЕТ С ЗАПИСАННЫМ — ЭЛЕМЕНТ НАХОДИТСЯ НА СВОЁМ ЭКРАНЕ.
        ///
        /// ЗАЧЕМ ОТДЕЛЬНАЯ ПРОВЕРКА, ЕСЛИ ПУТЬ НАЙДЕН. Часть путей существует на НЕСКОЛЬКИХ
        /// уровнях (`Screen_Close` есть на каждом экране): путь нашёлся бы на ЧУЖОМ экране, и
        /// нажатие ушло бы не туда — эффект оказался бы у невиновной кнопки. Для элемента,
        /// который НЕ принадлежит панели (AR, док-панели), проверка всегда проходит — правило
        /// действует только в шлеме.
        /// </summary>
        private static bool PanelLevelMatches(Candidate c)
        {
            if (c == null || !c.PanelBound) return true;

            KvXrGroupPanel panel = c.IsPanelIcon ? c.Panel : c.PanelOwner;
            if (panel == null || !panel.isActiveAndEnabled) return false;
            if ((int)panel.Level != c.ExpectedLevel) return false;

            // МЕНЮ: уровень может совпасть, а само меню — быть закрытым; тогда пунктов меню нет.
            if (c.ExpectedLevel == (int)KvXrPanelLevel.StartMenu)
            {
                KvXrStartMenu menu = KvXrStartMenu.Active;
                if (menu == null || !menu.Visible || menu.Panel != panel) return false;
            }
            return true;
        }

        /// <summary>
        /// ВЕРНУТЬ ПАНЕЛЬ НА ЭКРАН ЭЛЕМЕНТА — ШТАТНЫМИ ПУТЯМИ. Возвращает `""` или деталь
        /// неудачи (её потом видно в причине «панель не открыта»).
        ///
        /// ПОРЯДОК ШАГОВ ВЫБРАН ПО УСТРОЙСТВУ ИНТЕРФЕЙСА (найдено разбором отчёта 11.11.2026):
        ///   1) стартовое меню показывается ТОЛЬКО своим `KvXrStartMenu.Show` (он же гасит
        ///      панель у руки) — `RestoreBase` меню, наоборот, СКРЫВАЕТ, поэтому для уровня
        ///      `StartMenu` цепочки нет вообще;
        ///   2) окно компьютера открывается той же командой/хостом, что и обычно;
        ///   3) панель у руки: открытое меню её гасит — закрывается меню штатным `Hide` (он же
        ///      возвращает панель у руки), затем показывается погашенный канвас `SetArVisible`;
        ///   4) возврат на базу `RestoreBase` и нажатия по цепочке «иконка группы → иконка
        ///      экрана» настоящим `PressIndex`; если иконка экрана открыла окно компьютера
        ///      (`OpenWindow`), сама панель открывает экран тем же `OpenScreen`, которым
        ///      открывается её иконка;
        ///   5) каждый шаг ПРОВЕРЯЕТСЯ фактическим уровнем — «нажали и надеемся» не считается.
        /// </summary>
        private string NavigatePanel(Candidate c)
        {
            KvXrGroupPanel panel = c.IsPanelIcon ? c.Panel : c.PanelOwner;
            if (panel == null && c.IsPanelIcon)
            {
                panel = ActivePanel();                 // панель пересоздали — берём живую
                if (panel != null) c.Panel = panel;
            }
            if (panel == null) return "панель шлема в сцене не найдена";

            KvXrStartMenu menu = KvXrStartMenu.Active;
            bool isMenuPanel = menu != null && menu.Panel == panel;

            // 1) СТАРТОВОЕ МЕНЮ — СВОИМ ШТАТНЫМ ПУТЁМ.
            if (c.ExpectedLevel == (int)KvXrPanelLevel.StartMenu)
            {
                if (menu == null) return "объекта стартового меню в сцене нет";
                if (!menu.Visible) menu.Show();
                if (!menu.Visible || !panel.isActiveAndEnabled)
                    return "меню не показалось (видимость=" + (menu.Visible ? "1" : "0") + ")";
                return "";
            }

            // 2) ОКНО КОМПЬЮТЕРА — СВОИМ ОКНОМ (командой, которой оно и открывалось).
            if (panel.isWindow)
            {
                if (!string.IsNullOrEmpty(panel.WindowCommandId) &&
                    panel.OpenDesktopWindow(panel.WindowCommandId)) return "";
                KvXrWindowHost host = KvXrWindowHost.Active;
                if (host != null && panel.WindowScreen != KvXrPanelLevel.Groups &&
                    host.Open(panel.WindowScreen, KvXrGroupPanel.ScreenTitle(panel.WindowScreen)) != null)
                    return "";
                return "окно компьютера не открывается: команды окна нет";
            }

            // 3) ПАНЕЛЬ У РУКИ: открытое меню её гасит — закрываем меню штатным путём.
            if (menu != null && menu.Visible && !isMenuPanel) menu.Hide();

            if (isMenuPanel)
            {
                // У ПАНЕЛИ МЕНЮ УРОВНЯ «ИКОНКИ ГРУПП» ШТАТНОГО ПОКАЗА НЕТ: `Show` ведёт только
                // на уровень меню, а `RestoreBase` его скрывает. Поэтому: возврат на базу
                // (`RestoreBase` у меню побочно гасит его — это его штатное поведение), затем
                // включение объекта панели и ПЕРЕСБОРКА — тот же принцип «показ + пересборка»,
                // что `SetArVisible` + `Rebuild` в подготовке элемента (включённая силой панель
                // без пересборки проверять нельзя — правило пункта 13 шапки).
                RestoreBase(panel);
                if (!panel.isActiveAndEnabled)
                {
                    panel.gameObject.SetActive(true);
                    panel.Rebuild(true);
                }
                if (!panel.isActiveAndEnabled) return "канвас панели меню не активен";
            }
            else
            {
                RestoreBase(panel);
                if ((int)panel.Level != (int)KvXrPanelLevel.Groups)
                    return "панель не вернулась на иконки групп (уровень " + panel.Level + ")";
                if (!panel.IsCanvasVisible) panel.SetArVisible(true);
                if (!panel.isActiveAndEnabled)
                {
                    // Корень панели погашен не `SetArVisible` (например, скрыт сам объект) —
                    // включаем объект и перестраиваем, чтобы содержимое было собрано заново.
                    panel.gameObject.SetActive(true);
                    panel.Rebuild(true);
                }
                if (!panel.isActiveAndEnabled) return "канвас панели не активен";

                // 4) ЦЕПОЧКА ШТАТНЫХ НАЖАТИЙ: иконка группы → иконка экрана.
                string[] chain = c.RestoreChain;
                if (chain != null)
                {
                    for (int i = 0; i < chain.Length; i++)
                    {
                        int index = IconIndexOfTitle(panel, chain[i]);
                        if (index < 0)
                            return "на иконках групп нет иконки «" + chain[i] + "»";
                        panel.PressIndex(index);
                        // УРОВЕНЬ НЕ ПРОВЕРЯЕТСЯ ЗДЕСЬ: иконка экрана при живом хосте окон
                        // открывает ОКНО, а не экран панели, — тогда ниже сработает запасной
                        // штатный путь (`OpenScreen`), а не отказ. Факт сверяется в конце.
                    }
                }

                // ЗАПАСНОЙ ШТАТНЫЙ ПУТЬ ДЛЯ ЭКРАНА: иконка экрана могла открыть окно компьютера
                // (`OpenWindow`), а не экран панели — тогда сама панель открывает экран тем же
                // `OpenScreen`, которым открывается её иконка, когда окон в сцене нет.
                if ((int)panel.Level != c.ExpectedLevel &&
                    c.ExpectedLevel >= (int)KvXrPanelLevel.StatusScreen)
                    panel.OpenScreen((KvXrPanelLevel)c.ExpectedLevel);
            }

            // 5) ПРОВЕРКА ФАКТА: «нажали и надеемся» не считается восстановлением.
            if ((int)panel.Level != c.ExpectedLevel)
                return "уровень " + panel.Level + " вместо " + (KvXrPanelLevel)c.ExpectedLevel;
            return "";
        }

        /// <summary>
        /// ВОССТАНОВИТЬ ЭКРАН ЭЛЕМЕНТА И НАЙТИ ПУТЬ ЗАНОВО — ДО `MaxAttempts` ПОПЫТОК.
        ///
        /// ЧТО БЫЛО. Путь не находился → элемент откладывался → во втором проходе записывался
        /// «исчез». Для панели шлема это была массовая потеря (152 из 209): исчезал не элемент,
        /// а ЭКРАН, на котором он лежит.
        /// ЧТО СТАЛО. Каждая попытка: показать/вернуть панель штатным путём → нажать цепочку →
        /// ЖДЁМ КАДР (старые объекты уничтожаются в конце кадра, и без ожидания индекс путей
        /// нашёл бы уничтожаемый объект — урок `StartMenuPass`) → пересобрать индекс → найти
        /// путь заново. Успех — элемент проверяется обычным порядком; неудача — `RestoreFail`
        /// с деталью, и обход пишет причину «панель не открыта», а НЕ «исчез».
        /// </summary>
        private IEnumerator RestorePanelElement(Candidate c)
        {
            if (c == null || !c.PanelBound) yield break;
            c.RestoreFail = "";

            for (int attempt = 0; attempt < KvUiSweepPanelNav.MaxAttempts; attempt++)
            {
                if (finished) yield break;
                if (Locate(c) && PanelLevelMatches(c)) { c.RestoreFail = ""; yield break; }

                string detail = NavigatePanel(c);
                yield return null;                     // пересборка заканчивается в конце кадра
                RebuildUiIndex();
                c.Target = null;                       // путь — устойчивый ключ, ссылка — нет
                if (Locate(c) && PanelLevelMatches(c)) { c.RestoreFail = ""; yield break; }
                c.RestoreFail = detail.Length > 0
                    ? detail
                    : "путь не найден на восстановленном уровне";
            }

            if (Locate(c) && PanelLevelMatches(c)) { c.RestoreFail = ""; yield break; }
            if (c.RestoreFail.Length == 0)
                c.RestoreFail = "путь не найден после " + KvUiSweepPanelNav.MaxAttempts +
                                " попыток восстановления";
        }

        /// <summary>
        /// ЗАПИСАТЬ ЭЛЕМЕНТ С ПРИЧИНОЙ «ПАНЕЛЬ НЕ ОТКРЫТА» — ЭТО ИСКЛЮЧЕНИЕ С ПРОВЕРЯЕМЫМ
        /// СОСТОЯНИЕМ, а не «исчез» и не «без эффекта»: назван экран (`RestoreScreenTitle`) и
        /// фактическая деталь неудачи (`RestoreFail`), видно, сколько попыток было сделано.
        /// </summary>
        private void RecordPanelNotOpen(Candidate c)
        {
            string detail = c.RestoreFail;
            if (detail.Length == 0)
                detail = "путь не найден после " + KvUiSweepPanelNav.MaxAttempts + " попыток";
            string reason = KvUiSweepPanelNav.NotOpenReason(c.RestoreScreenTitle, detail);

            panelNotOpen++;
            if (panelNotOpen <= 20)
                Line("[KvUiSweep] ВОССТАНОВЛЕНИЕ ПАНЕЛИ: " + c.Path + " — " + reason);
            Record(new KvUiSweepElement
            {
                Path = c.Path,
                Kind = c.Kind,
                Ok = false,
                Effect = "не нажимали — " + reason,
                ExemptReason = reason,
                Method = "пропущен"
            });
        }

        /// <summary>Сколько элементов получили причину «панель не открыта» (для отчёта).</summary>
        private int panelNotOpen;

        /// <summary>
        /// РАСКРЫТИЕ СЛЕДУЮЩЕГО УРОВНЯ ПАНЕЛИ. Нажатие иконки группы раскрывает веер команд, а
        /// нажатие иконки экрана — экран. Эти пункты ТОЖЕ надо проверить, иначе «каждая кнопочка»
        /// останется неправдой для самых нужных кнопок. Глубина ограничена `MaxPanelDepth`, а
        /// каждый уровень проверяется ОДИН раз.
        /// </summary>
        private void ExpandPanelLevels(Candidate c, HashSet<int> seenLevels)
        {
            if (!c.IsPanelIcon || c.Panel == null) return;
            if (c.Depth >= MaxPanelDepth) return;

            // УРОВЕНЬ ЧИТАЕТСЯ ИЗ РЕЗУЛЬТАТА НАЖАТИЯ, а не из живого состояния панели: между
            // нажатием и этим вызовом `Restore` уже вернул панель на базовый уровень, и живое
            // состояние сказало бы «уровень не сменился» — панель шлема не проверялась бы глубже
            // первого уровня, то есть самые нужные кнопки (команды в веере) остались бы вне
            // прогона.
            int level = c.ResultLevel;
            if (level < 0) return;
            if (level == c.ExpectedLevel) return;                 // уровень не сменился — некуда идти
            if (!IsNavigableLevel(level)) return;
            if (!seenLevels.Add(level)) return;                   // этот уровень уже проверяли
            if (queue == null || queue.Total >= MaxElements) return;

            int[] path = new int[(c.PathIndices != null ? c.PathIndices.Length : 0) + 1];
            if (c.PathIndices != null) Array.Copy(c.PathIndices, path, c.PathIndices.Length);
            path[path.Length - 1] = c.Index;

            string levelTitle = KvXrGroupPanel.ScreenTitle((KvXrPanelLevel)level);
            if (string.IsNullOrEmpty(levelTitle)) levelTitle = "уровень " + level;
            int count = c.ResultIcons;
            int added = 0;
            for (int k = 0; k < count; k++)
            {
                // ПОДПИСИ ВЗЯТЫ В МОМЕНТ НАЖАТИЯ (`ResultTitles`), а не сейчас: к этому времени
                // панель уже вернулась на базовый уровень, и `TitleAt` назвал бы ЧУЖИЕ иконки.
                string title = c.ResultTitles != null && k < c.ResultTitles.Length
                    ? c.ResultTitles[k] : "";
                string pathText = PanelPath(level, title);
                string key = KvUiSweepNames.KeyOf(pathText);
                if (string.IsNullOrEmpty(key) || byKey.ContainsKey(key)) continue;

                var icon = new Candidate
                {
                    Path = pathText,
                    Key = key,
                    Label = title ?? "",
                    Kind = KvUiSweepKind.PanelIcon,
                    Panel = c.Panel,
                    PanelOwner = c.Panel,
                    Index = k,
                    PathIndices = path,
                    ExpectedLevel = level,
                    Depth = c.Depth + 1,
                    OpensPanel = KvUiSweepTiers.OpensPanel(pathText, title ?? "")
                };
                // ЭЛЕМЕНТ СЛЕДУЮЩЕГО УРОВНЯ ТОЖЕ ПРИНАДЛЕЖИТ ПАНЕЛИ (пункт 36 шапки): его путь
                // существует только на своём уровне. Цепочка от базы строится ЗДЕСЬ, а не при
                // сборе: панель сейчас на БАЗОВОМ уровне (после `RestoreBase`), поэтому подпись
                // первого шага читается прямо по номеру иконки.
                icon.PanelBound = true;
                icon.RestoreScreenTitle = KvUiSweepPanelNav.LevelTitle((KvXrPanelLevel)level,
                    KvXrGroupPanel.ScreenTitle((KvXrPanelLevel)level));
                icon.RestoreChain = BuildBaseChain(c.Panel, path, level);
                byKey[key] = icon;
                added += queue.Merge(key,
                    (int)KvUiSweepTiers.TierOf(pathText, title ?? "", byKey[key].OpensPanel));
            }

            // ОТЧЁТ ПО КАЖДОМУ УРОВНЮ — как требует приёмка: какой уровень, какая иконка, сколько
            // пунктов и сколько НОВЫХ попало в очередь. Если новых 0 — это сказано прямо: значит
            // цепочка не проходит (дело в `PressIndex`, а не в снимке).
            Line("[KvUiSweep] РАСКРЫТИЕ ПАНЕЛИ: уровень " + (c.Depth + 1) +
                 " · иконка «" + (c.Label ?? "") + "» → пунктов " + count +
                 " · новых в очереди " + added +
                 (added == 0 ? " (цепочка не прошла: новых пунктов нет)" : ""));
        }

        // ------------------------------------------------------------------ нажатие

        /// <summary>
        /// НАЖАТИЕ НАСТОЯЩИМ ПУТЁМ uGUI: `ExecuteEvents.Execute&lt;IPointerClickHandler&gt;` — то же
        /// самое, что вызывает мышь/луч. Запасные пути (`onClick.Invoke()`, `isOn`, `value`)
        /// применяются ТОЛЬКО если событие не дошло ни до одного обработчика, и их имя попадает
        /// в отчёт (`путь=…`), чтобы «нажали по-настоящему» было проверяемым утверждением.
        /// </summary>
        private string Press(Candidate c)
        {
            if (c.IsPanelIcon)
            {
                if (c.Panel == null) return "нет панели";
                if (!KvUiSweepExemptions.ShouldPress(c.Path, c.ProjectOwned))
                    return "не нажимали (запрещено правилом)";
                c.Panel.PressIndex(c.Index);
                return "PressIndex";
            }

            Selectable target = c.Target;
            if (target == null) return "нет элемента";
            if (!KvUiSweepExemptions.ShouldPress(c.Path, c.ProjectOwned))
                return "не нажимали (запрещено правилом)";
            if (!target.IsInteractable()) return "не нажимали (interactable=false)";

            GameObject go = target.gameObject;
            PointerEventData data = MakePointerData(go);

            // ПОЛНЫЙ ПОСЛЕДОВАТЕЛЬНЫЙ КЛИК: нажатие → отпускание → клик, как у настоящего указателя.
            // Одного `pointerClickHandler` НЕ ХВАТАЛО: строка дерева обрабатывает выбор в СВОЁМ
            // `IPointerClickHandler` (`KvTreeRow`), и если событие до него не дошло, вызывался
            // запасной путь `onClick` — а он у строки только завершает переименование, то есть
            // строка выглядела «мёртвой» (5 провалов на планшете).
            bool down = ExecuteEvents.Execute<IPointerDownHandler>(go, data, ExecuteEvents.pointerDownHandler);
            bool up = ExecuteEvents.Execute<IPointerUpHandler>(go, data, ExecuteEvents.pointerUpHandler);
            bool click = ExecuteEvents.Execute<IPointerClickHandler>(go, data, ExecuteEvents.pointerClickHandler);
            if (down || up || click) return KvUiSweepPressPathNames.Of(KvUiSweepPressPath.PointerEvents);

            // ПРЯМОЙ ВЫЗОВ ОБРАБОТЧИКОВ НА ЭТОМ ОБЪЕКТЕ. Тот же интерфейс, который зовёт
            // `EventSystem`, но БЕЗ фильтра «компонент активен и включён»: если кнопку-обёртку в
            // проекте выключают (чтобы клик обрабатывала строка), `ExecuteEvents` её не видит, а
            // настоящий оператор нажимает строку — и она работает.
            bool direct = false;
            IPointerClickHandler[] handlers = go.GetComponents<IPointerClickHandler>();
            for (int i = 0; i < handlers.Length; i++)
            {
                if (handlers[i] == null) continue;
                handlers[i].OnPointerClick(data);      // тот же путь, что у EventSystem
                direct = true;
            }
            if (direct) return KvUiSweepPressPathNames.Of(KvUiSweepPressPath.DirectHandlers);

            // ЗАПАСНЫЕ ПУТИ — и каждый назван в отчёте.
            Button button = target as Button;
            if (button != null) { button.onClick.Invoke(); return KvUiSweepPressPathNames.Of(KvUiSweepPressPath.UnityEvent); }

            Toggle toggle = target as Toggle;
            if (toggle != null) { toggle.isOn = !toggle.isOn; return KvUiSweepPressPathNames.Of(KvUiSweepPressPath.ValueToggle); }

            Slider slider = target as Slider;
            if (slider != null)
            {
                float mid = (slider.minValue + slider.maxValue) * 0.5f;
                slider.value = slider.value < mid
                    ? Mathf.Lerp(slider.minValue, slider.maxValue, 0.75f)
                    : Mathf.Lerp(slider.minValue, slider.maxValue, 0.25f);
                return KvUiSweepPressPathNames.Of(KvUiSweepPressPath.ValueSlider);
            }

            // DROPDOWN / INPUTFIELD без обработчика: выделяем элемент — это то, что делает клик.
            if (EventSystem.current != null)
            {
                EventSystem.current.SetSelectedGameObject(go);
                return KvUiSweepPressPathNames.Of(KvUiSweepPressPath.Select);
            }
            return KvUiSweepPressPathNames.Of(KvUiSweepPressPath.None);
        }

        /// <summary>
        /// ДАННЫЕ УКАЗАТЕЛЯ в ЦЕНТРЕ элемента. Позиция важна: без неё `Slider` не знает, куда
        /// «ткнули», и значение не меняется — то есть нажатие выглядело бы пустым.
        /// </summary>
        private static PointerEventData MakePointerData(GameObject go)
        {
            var data = new PointerEventData(EventSystem.current)
            {
                button = PointerEventData.InputButton.Left,
                clickCount = 1
            };

            RectTransform rect = go.transform as RectTransform;
            if (rect != null)
            {
                Canvas canvas = go.GetComponentInParent<Canvas>();
                Camera cam = canvas != null && canvas.renderMode != RenderMode.ScreenSpaceOverlay
                    ? canvas.worldCamera
                    : null;
                Vector2 screen = RectTransformUtility.WorldToScreenPoint(cam,
                    rect.TransformPoint(rect.rect.center));
                data.position = screen;
                data.pressPosition = screen;
                data.pointerCurrentRaycast = new RaycastResult { gameObject = go };
            }
            return data;
        }

        // ------------------------------------------------------------------ снимок состояния

        /// <summary>
        /// СНИМОК ЖИВОГО СОСТОЯНИЯ. Дешёвый намеренно: снимается ДВА РАЗА на элемент, а элементов
        /// десятки — тяжёлый обход сцены на каждый кадр сорвал бы бюджет времени в шлеме.
        ///
        /// `intoPanels` (необязательный) заполняется СОСТОЯНИЕМ КАЖДОЙ DOCK-ПАНЕЛИ. Без этого
        /// «свернуть», «причалить» и «в рейл» выглядели как мёртвые кнопки: они не скрывают
        /// панель, а меняют её вид, сторону и размер — по одному признаку «панелей видно» такого
        /// изменения не видно (найдено на планшете 12.11.2026).
        /// </summary>
        private KvUiSweepSnapshot Capture(List<KvUiSweepPanelState> intoPanels = null)
        {
            var s = new KvUiSweepSnapshot { Comfort = ComfortValue(), PanelLevel = -1 };

            KazistovVvUIManager ui = KazistovVvUIManager.Instance;
            if (ui != null)
            {
                if (ui.IsPanelVisible("tree")) s.VisiblePanels++;
                if (ui.IsPanelVisible("properties")) s.VisiblePanels++;
                if (ui.IsPanelVisible("settings")) s.VisiblePanels++;
                if (ui.IsPanelVisible("hotkeys")) s.VisiblePanels++;
                // ВИДИМОСТЬ ОБОЛОЧКИ (дефект D4): команда `ui.toggle` прячет интерфейс целиком.
                // Без этого признака снимок не видел ни самого нажатия, ни того, что следующие
                // элементы проверяются в мире, где оболочки нет.
                s.UiVisible = ui.uiVisible ? 1 : 0;
                s.UiObjects = ui.UiObjectCount;
                s.TreeRows = ui.TreeRowCount;
                s.PropertyRows = ui.PropertyRowCount;
                s.ToolbarButtons = ui.ToolbarButtonCount;
                s.Points = ui.PointCount;

                if (intoPanels != null)
                {
                    intoPanels.Clear();
                    intoPanels.Add(PanelStateOf("tree", ui.TreeDock));
                    intoPanels.Add(PanelStateOf("properties", ui.PropertiesDock));
                    intoPanels.Add(PanelStateOf("settings", ui.SettingsDock));
                    intoPanels.Add(PanelStateOf("hotkeys", ui.HotkeyDock));
                }
                s.PanelFingerprint = intoPanels != null
                    ? KvUiSweepPanelSig.Fingerprint(intoPanels)
                    : 0;
            }

            if (EventSystem.current != null && EventSystem.current.currentSelectedGameObject != null)
                s.SelectedObjects = 1;

            s.ModeIndex = KvXrSettings.GetModeIndex();
            s.Language = LanguageIndex();
            s.Commands = KvCommands.ExecutedCount;
            s.SceneObjects = SceneObjectCount();
            s.Files = CountRecords();

            KvXrGroupPanel panel = ActivePanel();
            if (panel != null)
            {
                s.PanelLevel = (int)panel.Level;
                s.PanelIcons = panel.IconCount;
                // ПОДПИСЬ ПАНЕЛИ ШЛЕМА: уровень + иконки + раскрытая группа + страница + строка
                // состояния. Без неё нажатие, меняющее только подпись или страницу веера, тоже
                // выглядело бы «без эффекта».
                s.PanelStateHash = KvUiSweepNames.StableHash(
                    s.PanelLevel.ToString(CultureInfo.InvariantCulture) + "|" +
                    s.PanelIcons.ToString(CultureInfo.InvariantCulture) + "|" +
                    panel.OpenGroupIndex.ToString(CultureInfo.InvariantCulture) + "|" +
                    panel.FanPageIndex.ToString(CultureInfo.InvariantCulture) + "|" +
                    (panel.Status ?? ""));
            }
            // ФЛАГИ ОБОЛОЧКИ И ТЕМА: их меняют переключатели панели настроек, и без них эти
            // переключатели выглядели бы мёртвыми (принцип «кнопка мертва ≠ снимок не видит»).
            CaptureUiSettings(s);
            CaptureArPanels(s, ui);
            return s;
        }

        /// <summary>
        /// СНЯТЬ ПАНЕЛИ AR И ОБЩИЙ СЧЁТ ОБЪЕКТОВ ИНТЕРФЕЙСА.
        ///
        /// ЗАЧЕМ. Кнопка «Поставить» без плоскости не молчит — она пишет оператору «плоскостей
        /// нет», и это эффект. Показ сообщения/панели команд/меню AR, как и показ любой другой
        /// панели, обязан быть виден снимку, иначе рабочие кнопки попадают в дефекты.
        /// </summary>
        private static void CaptureArPanels(KvUiSweepSnapshot snapshot, KazistovVvUIManager ui)
        {
            KvArUi ar = UnityEngine.Object.FindAnyObjectByType<KvArUi>();
            if (ar != null)
            {
                snapshot.ArMessageVisible = ar.MessageVisible ? 1 : 0;
                string text = ar.MessageText ?? "";
                snapshot.ArMessageHash = KvUiSweepNames.StableHash(text);
                snapshot.ArMessageLength = text.Length;
                snapshot.ArCommandPanel = ar.CommandPanelVisible ? 1 : 0;
                snapshot.ArMenu = ar.MenuVisible ? 1 : 0;
                snapshot.ArButtons = ar.ButtonCount;
            }
            snapshot.ArTables = KvArUi.CreatedTableCount;
            snapshot.ArPlanes = CountArPlanes();

            // СТРОКА СОСТОЯНИЯ И ПОДСКАЗКА AR: интерфейс планшета отвечает ими на действие
            // («плоскостей нет», «поставлено»), поэтому их изменение — эффект.
            string status = ar != null ? (ar.StatusText ?? "") : "";
            string hint = ar != null ? (ar.HintText ?? "") : "";
            snapshot.ArStatusHash = KvUiSweepNames.StableHash(status + "|" + hint);

            // ВЫБОР В ДЕРЕВЕ: нажатие строки дерева меняет выбранный узел (и панель свойств).
            if (ui != null)
                snapshot.SelectedNodeHash = KvUiSweepNames.StableHash(DescribeSelectedNode(ui));

            CountCanvasObjects(out snapshot.UiObjectsAll, out snapshot.UiObjectsActive);
            CaptureStatusAndMenus(snapshot, ui);
        }

        /// <summary>
        /// СНЯТЬ СТРОКУ СТАТУСА, СОСТОЯНИЕ МЕНЮ И СТАРТОВОГО МЕНЮ.
        ///
        /// ЗАЧЕМ СТАТУС. Целый класс кнопок НИЧЕГО НЕ МЕНЯЕТ, КРОМЕ СООБЩЕНИЯ оператору
        /// («Переназначение клавиш появится позже — бинды не меняются»). Без статуса в снимке такие
        /// кнопки выглядят мёртвыми, хотя они работают: они честно отвечают, что действие
        /// невозможно.
        /// </summary>
        private static void CaptureStatusAndMenus(KvUiSweepSnapshot snapshot, KazistovVvUIManager ui)
        {
            if (ui != null)
            {
                string message = ui.StatusMessage ?? "";
                snapshot.StatusLength = message.Length;
                snapshot.StatusHash = KvUiSweepNames.StableHash(
                    (ui.StatusState ?? "") + "|" + message + "|" +
                    (ui.StatusCursor ?? "") + "|" + (ui.StatusTheme ?? ""));
                snapshot.MenuOpen = MenuOpenNow() ? 1 : 0;
            }

            KvXrStartMenu start = KvXrStartMenu.Active;
            snapshot.StartMenuVisible = start != null && start.Visible ? 1 : 0;
            KvXrGroupPanel startPanel = start != null ? start.Panel : startPanelFromScene();
            if (startPanel != null)
            {
                snapshot.StartSection = (int)startPanel.StartSection;
                snapshot.StartTables = startPanel.StartTableCount;
                snapshot.StartRobots = startPanel.StartRobotCount;
            }

            // ГРУППЫ ТУЛБАРА: «вкладка группы» сворачивает/разворачивает набор кнопок — без этого
            // числа эффект терялся (тулбар выглядел одинаково).
            if (ui != null && ui.Toolbar != null)
                snapshot.ToolbarCollapsedGroups = ui.Toolbar.CollapsedGroupCount;
        }

        /// <summary>Панель меню, если `KvXrStartMenu.Active` ещё не поднят: ищем по сцене.</summary>
        private static KvXrGroupPanel startPanelFromScene()
        {
            KvXrGroupPanel[] panels = UnityEngine.Object.FindObjectsByType<KvXrGroupPanel>(
                FindObjectsInactive.Exclude);
            for (int i = 0; i < panels.Length; i++)
            {
                KvXrGroupPanel p = panels[i];
                if (p == null || !p.isActiveAndEnabled) continue;
                if (p.Level != KvXrPanelLevel.StartMenu) continue;   // только настоящее меню
                return p;
            }
            return null;
        }

        /// <summary>ТЕКСТ СТАТУСА СЕЙЧАС — для строки эффекта «статус изменён: «…»».</summary>
        private static string StatusPreview(int max)
        {
            KazistovVvUIManager ui = KazistovVvUIManager.Instance;
            if (ui == null) return "";
            return KvUiSweepNames.Preview(ui.StatusMessage, max);
        }

        /// <summary>Имя выбранного узла дерева (пусто — ничего не выбрано).</summary>
        private static string DescribeSelectedNode(KazistovVvUIManager ui)
        {
            ProjectNode node = ui.SelectedNode;
            if (node == null) return "";
            string name = string.IsNullOrEmpty(node.DisplayName) ? node.Key : node.DisplayName;
            return (node.Id ?? "") + "|" + (name ?? "");
        }

        /// <summary>
        /// СКОЛЬКО ПЛОСКОСТЕЙ НАЙДЕНО СЕЙЧАС — ФАКТИЧЕСКОЕ СОСТОЯНИЕ AR. Читается у постановщика
        /// (`KvArPlacement`), а если его нет — у визуализатора плоскостей. Нужно для честного
        /// исключения «ставить некуда: плоскостей 0»: без числа тестировщик не отличит
        /// «невозможно» от «сломалось».
        /// </summary>
        private static int CountArPlanes()
        {
            KvArPlacement placement = UnityEngine.Object.FindAnyObjectByType<KvArPlacement>();
            if (placement != null) return placement.PlanesFound;

            KvArPlaneVisualizer visualizer = UnityEngine.Object.FindAnyObjectByType<KvArPlaneVisualizer>();
            return visualizer != null ? visualizer.VisualizedPlanes : 0;
        }

        /// <summary>
        /// СЧЁТ ОБЪЕКТОВ ПО ВСЕМ АКТИВНЫМ КАНВАСАМ: всего и активных. Вложенные канвасы не
        /// считаются дважды — идём только от корневых.
        /// </summary>
        private static void CountCanvasObjects(out int all, out int active)
        {
            all = 0;
            active = 0;

            Canvas[] canvases = UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsInactive.Include);
            for (int i = 0; i < canvases.Length; i++)
            {
                Canvas canvas = canvases[i];
                if (canvas == null) continue;
                if (!canvas.gameObject.activeInHierarchy) continue;

                // ВЛОЖЕННЫЙ КАНВАС УЖЕ ПОСЧИТАН РОДИТЕЛЕМ.
                Transform parent = canvas.transform.parent;
                if (parent != null && parent.GetComponentInParent<Canvas>() != null) continue;

                CountObjects(canvas.transform, ref all, ref active);
            }
        }

        private static void CountObjects(Transform t, ref int all, ref int active)
        {
            if (t == null) return;
            all++;
            if (t.gameObject.activeSelf) active++;
            for (int i = 0; i < t.childCount; i++) CountObjects(t.GetChild(i), ref all, ref active);
        }

        /// <summary>
        /// СНЯТЬ ФЛАГИ ОБОЛОЧКИ И ТЕМУ. Вынесено отдельно от <see cref="Capture"/>, чтобы список
        /// признаков не разъезжался с восстановлением состояния (<see cref="RestoreUiSettings"/>).
        /// Каждое чтение — свойство `KvSettings`, которое пишет оператор переключателями панели
        /// настроек; без них эти переключатели выглядели бы мёртвыми.
        /// </summary>
        private static void CaptureUiSettings(KvUiSweepSnapshot snapshot)
        {
            snapshot.SetWorkspace = KvSettings.ShowWorkspace ? 1 : 0;            snapshot.SetJointLimits = KvSettings.ShowJointLimits ? 1 : 0;
            snapshot.SetMetrics = KvSettings.ShowMetrics ? 1 : 0;
            snapshot.SetFlashlight = KvSettings.Flashlight ? 1 : 0;
            snapshot.SetAutoTree = KvSettings.AutoRefreshTree ? 1 : 0;
            snapshot.SetPhantoms = KvSettings.ShowPhantoms ? 1 : 0;
            snapshot.SetDensity = KvSettings.Density;
            snapshot.SetToolbarRows = KvSettings.ToolbarRows;
            snapshot.SetToolbarLayout = KvSettings.ToolbarLayout;
            snapshot.SetToolbarCompact = KvSettings.ToolbarCompact ? 1 : 0;
            snapshot.SetFontSize = KvSettings.FontSize;
            snapshot.SetHighContrast = KvSettings.HighContrast ? 1 : 0;
            snapshot.SetColorBlind = KvSettings.ColorBlind;
            snapshot.SetKeyboardNav = KvSettings.KeyboardNav ? 1 : 0;
            snapshot.SetGamepadHud = KvSettings.GamepadHud ? 1 : 0;
            snapshot.SetErrorPlate = KvSettings.ErrorPlate ? 1 : 0;
            snapshot.ThemeHash = KvUiSweepNames.StableHash(
                (KvTheme.ModeLabel ?? "") + "|" + (KvTheme.PaletteLabel ?? ""));
        }

        private static KvXrGroupPanel ActivePanel()
        {
            KvXrGroupPanel[] panels = UnityEngine.Object.FindObjectsByType<KvXrGroupPanel>(
                FindObjectsInactive.Exclude);
            for (int i = 0; i < panels.Length; i++)
                if (panels[i] != null && panels[i].isActiveAndEnabled) return panels[i];
            return null;
        }

        /// <summary>
        /// СОСТОЯНИЕ ОДНОЙ DOCK-ПАНЕЛИ для отпечатка: сторона, свёрнутость, рейл, видимость, размер.
        /// Именно это меняют кнопки шапки дока (`ToggleCollapsed`, `ToggleFloat`/`CycleDock`,
        /// `ToRail`), не скрывая панель: без этих полей три рабочие кнопки выглядели мёртвыми.
        /// </summary>
        private static KvUiSweepPanelState PanelStateOf(string id, KvDockPanel panel)
        {
            var state = new KvUiSweepPanelState { Id = id };
            if (panel == null) return state;

            state.Side = (int)panel.Side;
            state.Collapsed = panel.Collapsed ? 1 : 0;
            state.InRail = panel.InRail ? 1 : 0;
            state.Shown = panel.Shown ? 1 : 0;
            if (panel.Root != null)
            {
                Rect rect = panel.Root.rect;
                state.Width = KvUiSweepPanelSig.Quantize(rect.width);
                state.Height = KvUiSweepPanelSig.Quantize(rect.height);
            }
            return state;
        }

        /// <summary>Комфорт одним числом: признак виньетки + сила в сотых.</summary>
        private static int ComfortValue()
        {
            int on = KvXrSettings.GetVignetteEnabled() ? 1000 : 0;
            return on + Mathf.RoundToInt(KvXrSettings.GetVignetteStrength() * 100f);
        }

        private static int LanguageIndex()
        {
            string code = KvLoc.CurrentCode;
            IReadOnlyList<KvLangInfo> langs = KvLoc.Languages;
            for (int i = 0; i < langs.Count; i++)
                if (string.Equals(langs[i].code, code, StringComparison.OrdinalIgnoreCase)) return i;
            return -1;
        }

        /// <summary>Код языка по номеру — нужен, чтобы ВЕРНУТЬ язык после нажатия.</summary>
        private static string LanguageCode(int index)
        {
            IReadOnlyList<KvLangInfo> langs = KvLoc.Languages;
            if (index < 0 || index >= langs.Count) return "";
            return langs[index] != null ? langs[index].code : "";
        }

        /// <summary>Сколько объектов в активной сцене (считаем вручную: без выделения массивов).</summary>
        private static int SceneObjectCount()
        {
            Scene scene = SceneManager.GetActiveScene();
            if (!scene.IsValid()) return 0;
            GameObject[] roots = scene.GetRootGameObjects();
            int total = 0;
            for (int i = 0; i < roots.Length; i++)
                if (roots[i] != null) total += CountTransforms(roots[i].transform);
            return total;
        }

        private static int CountTransforms(Transform t)
        {
            if (t == null) return 0;
            int n = 1;
            for (int i = 0; i < t.childCount; i++) n += CountTransforms(t.GetChild(i));
            return n;
        }

        /// <summary>Сколько записей и поз лежит в хранилище (нажатие «записать» обязано их прибавить).</summary>
        private static int CountRecords()
        {
            return CountFiles(FeatureStorage.RecordingsDir) + CountFiles(FeatureStorage.PosesDir);
        }

        private static int CountFiles(string dir)
        {
            try
            {
                if (string.IsNullOrEmpty(dir) || !Directory.Exists(dir)) return 0;
                return Directory.GetFiles(dir, "*", SearchOption.TopDirectoryOnly).Length;
            }
            catch (Exception e)
            {
                Debug.LogWarning("[KvUiSweep] не удалось прочитать «" + dir + "»: " + e.Message);
                return 0;
            }
        }

        // ------------------------------------------------------------------ вспомогательное

        private bool UiReady()
        {
            return KazistovVvUIManager.Instance != null || ActivePanel() != null;
        }

        /// <summary>Сколько панелей вообще построено (оболочка + панель шлема).</summary>
        private int CountPanels()
        {
            int n = 0;
            KazistovVvUIManager ui = KazistovVvUIManager.Instance;
            if (ui != null)
            {
                if (ui.TreeDock != null && ui.TreeDock.Root != null) n++;
                if (ui.PropertiesDock != null && ui.PropertiesDock.Root != null) n++;
                if (ui.SettingsDock != null && ui.SettingsDock.Root != null) n++;
                if (ui.HotkeyDock != null && ui.HotkeyDock.Root != null) n++;
            }

            KvXrGroupPanel[] panels = UnityEngine.Object.FindObjectsByType<KvXrGroupPanel>(
                FindObjectsInactive.Include);
            for (int i = 0; i < panels.Length; i++)
                if (panels[i] != null && panels[i].BuiltOnce) n++;
            return n;
        }

        /// <summary>Смена режима по флагу + кадры «остывания» и пересборка панелей штатным путём.</summary>
        private IEnumerator ApplyMode(int mode)
        {
            int before = KvXrSettings.GetModeIndex();
            Line("[KvUiSweep] РЕЖИМ: выставление " + KvUiSweepLayout.ModeName(mode) +
                 " (было " + KvUiSweepLayout.ModeName(before) + ")");
            try
            {
                KvXrSettings.SetModeIndex(mode);
                KvXrSettingsChanged.Notify();
            }
            catch (Exception e)
            {
                Line("[KvUiSweep] РЕЖИМ: не удалось выставить — " + e.GetType().Name + ": " + e.Message);
            }

            for (int f = 0; f < SettleFrames; f++) yield return null;

            // ПАНЕЛИ ПЕРЕСТРАИВАЮТСЯ ШТАТНЫМ ПУТЁМ: настройка режима влияет на их состав, и
            // «обход сразу после переключения» проверял бы старую раскладку.
            KazistovVvUIManager ui = KazistovVvUIManager.Instance;
            if (ui != null)
            {
                try { ui.RefreshPanels(); }
                catch (Exception e)
                {
                    Line("[KvUiSweep] РЕЖИМ: RefreshPanels — " + e.GetType().Name + ": " + e.Message);
                }
            }
            KvXrGroupPanel panel = ActivePanel();
            if (panel != null)
            {
                try { panel.Rebuild(true); }
                catch (Exception e)
                {
                    Line("[KvUiSweep] РЕЖИМ: Rebuild панели — " + e.GetType().Name + ": " + e.Message);
                }
            }
            for (int f = 0; f < SettleFrames; f++) yield return null;
        }

        /// <summary>Проиграть путь «сначала иконки групп» — база для любого уровня панели.</summary>
        private static void RestoreBase(KvXrGroupPanel panel)
        {
            if (panel == null) return;
            if (panel.OpenGroupIndex >= 0) panel.CloseFan();
            if (panel.Level != KvXrPanelLevel.Groups) panel.CloseScreen();
            // НАДЁЖНЫЙ СБРОС: `CloseScreen` у меню и у экрана ввода уровня не меняет (это его
            // штатное поведение), поэтому нужен второй шаг.
            if (panel.Level != KvXrPanelLevel.Groups) panel.CloseFan();
        }

        private static bool IsNavigableLevel(int level)
        {
            KvXrPanelLevel l = (KvXrPanelLevel)level;
            return l == KvXrPanelLevel.GroupFan || l == KvXrPanelLevel.DesktopWindow ||
                   l == KvXrPanelLevel.StartMenu || KvXrGroupPanel.IsScreen(l);
        }

        private static string PanelPath(int level, string title)
        {
            string levelName = KvXrGroupPanel.ScreenTitle((KvXrPanelLevel)level);
            string name = string.IsNullOrEmpty(title) ? "(без подписи)" : title;
            return "ПанельШлема/" + levelName + "/" + name;
        }

        private static string PathOf(Transform t)
        {
            if (t == null) return "(без имени)";

            // ПОЛНЫЙ ПУТЬ ОТ КОРНЯ (до 12 уровней), а не «три предка», и с НОМЕРОМ у одноимённых
            // соседей. Путь — КЛЮЧ ПОИСКА: он обязан быть уникальным, иначе два разных объекта
            // дают один ключ, и второй из них не проверяется никогда.
            var sb = new StringBuilder(Segment(t));
            Transform p = t.parent;
            for (int guard = 0; p != null && guard < 12; guard++, p = p.parent)
                sb.Insert(0, Segment(p) + "/");

            // ПОДПИСЬ — ТОЛЬКО ДЛЯ ЧИТАЕМОСТИ. В ключ она не входит (`KvUiSweepNames.KeyOf`):
            // переключатель меняет текст после нажатия, и ключ с подписью «потерялся» бы ровно
            // тогда, когда кнопка сработала.
            Text own = t.GetComponent<Text>();
            Text label = own != null ? own : t.GetComponentInChildren<Text>(true);
            if (label != null && !string.IsNullOrEmpty(label.text))
                sb.Append("«").Append(Trim(label.text, 24)).Append("»");
            return sb.ToString();
        }

        /// <summary>
        /// ИМЯ СЕГМЕНТА ПУТИ: при одноимённых соседях добавляется номер (`Switch#2`). Считает
        /// соседей, а правило сборки имени берёт из чистой функции <see cref="KvUiSweepNames.Segment"/>
        /// — чтобы проверенное тестом правило было РОВНО тем, что работает в обходе.
        /// </summary>
        private static string Segment(Transform t)
        {
            Transform parent = t.parent;
            if (parent == null) return KvUiSweepNames.Segment(t.name, 1, 0);

            int sameName = 0;
            int ordinal = 0;
            for (int i = 0; i < parent.childCount; i++)
            {
                Transform sibling = parent.GetChild(i);
                if (!string.Equals(sibling.name, t.name, StringComparison.Ordinal)) continue;
                if (sibling == t) ordinal = sameName;
                sameName++;
            }
            return KvUiSweepNames.Segment(t.name, sameName, ordinal);
        }

        private static string Trim(string s, int max)
        {
            if (string.IsNullOrEmpty(s)) return "";
            string flat = s.Replace('\n', ' ').Replace('\r', ' ').Trim();
            return flat.Length <= max ? flat : flat.Substring(0, max) + "…";
        }

        /// <summary>Самый верхний ВЫКЛЮЧЕННЫЙ предок элемента (та самая «свёрнутая панель»).</summary>
        private static Transform TopInactiveAncestor(GameObject go)
        {
            if (go == null) return null;
            Transform gate = null;
            for (Transform t = go.transform; t != null; t = t.parent)
                if (!t.gameObject.activeSelf) gate = t;
            return gate;
        }

        /// <summary>Элемент внутри ШАБЛОНА выпадающего списка: он не для оператора, а для отрисовки.</summary>
        private static bool UnderTemplate(Transform t)
        {
            for (Transform p = t; p != null; p = p.parent)
                if (p.name.IndexOf("Template", StringComparison.OrdinalIgnoreCase) >= 0) return true;
            return false;
        }

        /// <summary>
        /// Вид элемента по ФАКТИЧЕСКОМУ типу компонента.
        ///
        /// ПОЧЕМУ ПРОВЕРКА НАСЛЕДОВАНИЯ (`is`), А НЕ СРАВНЕНИЕ ИМЕНИ. Кнопки шапки дока — это
        /// кнопки, но у них бывают свои наследники (`KvIconButton` и подобные). Сравнение
        /// `GetType().Name == "Button"` тихо выбросило бы их из прогона, и «каждая кнопочка» снова
        /// стала бы неправдой — только теперь молча. Имя типа остаётся нужным ТОЛЬКО для
        /// TMP-вариантов: `TMP_Dropdown` не наследует `Dropdown`, и по-другому их не отличить.
        /// </summary>
        private static bool Classify(Selectable s, out KvUiSweepKind kind)
        {
            kind = KvUiSweepKind.Button;
            if (s is Button) return true;
            if (s is Toggle) { kind = KvUiSweepKind.Toggle; return true; }
            if (s is Slider) { kind = KvUiSweepKind.Slider; return true; }

            string type = s.GetType().Name;
            if (type == "Dropdown" || type == "TMP_Dropdown") { kind = KvUiSweepKind.Dropdown; return true; }
            if (type == "InputField" || type == "TMP_InputField") { kind = KvUiSweepKind.InputField; return true; }
            return false;   // полосы прокрутки и прочее — это не «кнопочки», их считаем отдельно
        }

        private static bool IsInteractable(Candidate c)
        {
            if (c.IsPanelIcon) return true;
            return c.Target != null && c.Target.IsInteractable();
        }

        /// <summary>
        /// ЭЛЕМЕНТ ПРИНАДЛЕЖИТ ПАНЕЛЯМ ПРОЕКТА? От этого зависит, считается ли подпись
        /// «Настройки» системным пунктом.
        ///
        /// ПОЧЕМУ ЭТО ВООБЩЕ НУЖНО. Одноимённые пункты ведут себя по-разному: штатная панель
        /// «Настройки» приложения обязана ПРОВЕРЯТЬСЯ нажатием, а кнопка «ОТКРЫТЬ НАСТРОЙКИ»
        /// из `KvArCameraGate` открывает `android.settings.APPLICATION_DETAILS_SETTINGS` и уводит
        /// приложение в фон вместе с прогоном. Различаются они принадлежностью: первая живёт в
        /// оболочке `KazistovVvUIManager` или на панели шлема, вторая — в собственной заставке
        /// (`KvArCameraGateCanvas`), которая к панелям проекта не относится.
        /// </summary>
        private static bool IsProjectOwned(Transform t)
        {
            if (t == null) return false;

            KazistovVvUIManager ui = KazistovVvUIManager.Instance;
            if (ui != null)
            {
                Transform root = ui.transform;
                if (t == root || t.IsChildOf(root)) return true;
            }

            // Панель шлема строит `KvXrGroupPanel` — она тоже наша, даже если лежит вне менеджера.
            return t.GetComponentInParent<KvXrGroupPanel>() != null;
        }

        /// <summary>Разрушительные элементы — В КОНЕЦ (порядок устойчивый: две группы, не сортировка).</summary>
        private static void ReorderDestructiveLast(List<Candidate> list)
        {
            var normal = new List<Candidate>(list.Count);
            var last = new List<Candidate>();
            for (int i = 0; i < list.Count; i++)
            {
                if (KvUiSweepExemptions.IsDestructive(list[i].Path)) last.Add(list[i]);
                else normal.Add(list[i]);
            }
            list.Clear();
            list.AddRange(normal);
            list.AddRange(last);
        }

        // ------------------------------------------------------------------ отчёт

        private void Header()
        {
            Line("");
            Line("=== САМОПРОГОН ИНТЕРФЕЙСА (KvUiSweep) ===");
            Line("дата: " + DateTime.Now.ToString("dd.MM.yyyy HH:mm:ss", CultureInfo.InvariantCulture));
            Line("сцена: " + sceneName + " · макет: " + run.Layout +
                 " · устройство: " + Application.platform);
            Line("порог элементов: " + KvUiSweepRun.MinElements +
                 " · бюджет элемента: " + ElementBudgetSeconds.ToString("0.0", CultureInfo.InvariantCulture) +
                 " с · общий предел: " + TotalBudgetSeconds.ToString("0", CultureInfo.InvariantCulture) + " с");
            Line("отчёт: " + ReportPath(run.Layout));
            Line("КАК ЧИТАТЬ ОБОРВАННЫЙ ОТЧЁТ: файл дописывается после КАЖДОЙ строки, поэтому");
            Line("  обрыв сразу после строки `press=…` означает «приложение зависло или ушло в фон");
            Line("  внутри ЭТОГО нажатия» — виновник назван в последней строке `press=`.");
            Line("ЧЕСТНО О ГРАНИЦАХ: прогон нажимает ШТАТНЫМ путём (onClick / PressIndex / ShowPanel),");
            Line("  поэтому раскладка панелей может сохраниться такой, как после работы оператора.");
            Line("  Настройки (режим VR/MR, язык, комфорт) возвращаются после каждого элемента.");
            Line("ИСКЛЮЧЕНИЯ (элемент физически не работает без железа — провалом не считается):");
            IReadOnlyList<KvUiSweepExemptions.Rule> rules = KvUiSweepExemptions.Rules;
            for (int i = 0; i < rules.Count; i++)
                Line("  · «" + rules[i].Pattern + "» — " + rules[i].Reason +
                     (rules[i].Press ? "" : " (НЕ нажимается)"));
            Line("  · недоступный элемент — " + KvUiSweepExemptions.DisabledReason);
            Line("НЕ НАЖИМАЮТСЯ СИСТЕМНЫЕ ПУНКТЫ (уводят приложение в фон) — только ВНЕ панелей проекта:");
            IReadOnlyList<KvUiSweepExemptions.Rule> system = KvUiSweepExemptions.SystemRules;
            for (int i = 0; i < system.Count; i++)
                Line("  · «" + system[i].Pattern + "» — " + system[i].Reason);
            Line("НЕ НАЖИМАЮТСЯ СИСТЕМНЫЕ ШЛЮЗЫ (предполётные заглушки) — ВСЕГДА, и их панель не включается:");
            IReadOnlyList<string> gatePatterns = KvUiSweepExemptions.GatePatterns;
            for (int i = 0; i < gatePatterns.Count; i++)
                Line("  · «" + gatePatterns[i] + "» — " + KvUiSweepExemptions.GateReason);
        }

        /// <summary>
        /// СМЕНИТЬ ФАЙЛ ОТЧЁТА (макет уточняется после загрузки сцены и смены режима).
        /// Накопленный текст переносится в новый файл при первой же записи, поэтому в отчёте
        /// не остаётся «половины строк», уехавшей в файл другого макета.
        /// </summary>
        private void SetLayout(string layout)
        {
            if (run == null) return;
            run.Layout = layout;
            string path = ReportPath(layout);
            if (string.Equals(path, reportPath, StringComparison.OrdinalIgnoreCase)) return;
            reportPath = path;
            reportFileReady = false;   // первый Line() после смены файла перепишет его целиком
        }

        /// <summary>
        /// Строка и в журнал (logcat), и в файл отчёта — ДОЗАПИСЬЮ СРАЗУ.
        ///
        /// ЗАЧЕМ ДОЗАПИСЬ. На планшете 12.11.2026 прогон нажал кнопку, открывшую системные
        /// настройки: приложение ушло в фон, кадры остановились, и запись отчёта «в конце» не
        /// состоялась ВООБЩЕ — файла не было, а в журнале не было даже итога. Файл, который
        /// дописывается построчно, переживает и потерю фокуса, и падение процесса: по последней
        /// строке `press=` виден виновник.
        /// </summary>
        private void Line(string text)
        {
            report.Append(text).Append('\n');
            Debug.Log(text.Length == 0 ? "[KvUiSweep]" : text);

            if (reportPath.Length == 0) return;
            try
            {
                if (!reportFileReady)
                {
                    File.WriteAllText(reportPath, report.ToString(), new UTF8Encoding(false));
                    reportFileReady = true;
                }
                else
                {
                    File.AppendAllText(reportPath, text + "\n", new UTF8Encoding(false));
                }
            }
            catch (Exception e)
            {
                Debug.LogWarning("[KvUiSweep] дозапись отчёта «" + reportPath + "»: " + e.Message);
            }
        }

        /// <summary>Файл отчёта: `Application.persistentDataPath/Reports/_ui_sweep_&lt;layout&gt;.txt`.</summary>
        public static string ReportPath(string layout)
        {
            string name = "_ui_sweep_" + (string.IsNullOrEmpty(layout) ? "pc" : layout) + ".txt";
            string dir = Path.Combine(Application.persistentDataPath, "Reports");
            try
            {
                if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
            }
            catch (Exception e)
            {
                Debug.LogWarning("[KvUiSweep] не удалось создать «" + dir + "»: " + e.Message);
            }
            return Path.Combine(dir, name);
        }

        /// <summary>
        /// ЗАВЕРШЕНИЕ: итог, вердикт, файл, выход из приложения. Прогон обязан быть КОНЕЧНЫМ —
        /// иначе «идёт» и «завис» неразличимы, и ожидание по времени невозможно.
        /// </summary>
        private IEnumerator Finish(string forcedFailure)
        {
            // УЖЕ ЗАВЕРШИЛИСЬ — второй раз не пишем. Так бывает после аварийного завершения:
            // корутина стоит на кадре, а приложение уже ушло в фон и отчёт записан.
            if (finished) yield break;
            finished = true;
            float seconds = Time.realtimeSinceStartup - startedAt;

            if (!string.IsNullOrEmpty(forcedFailure))
                Line("[KvUiSweep] ПРИЧИНА: " + forcedFailure);

            Line(run.TotalLine(seconds));
            // ПОКРЫТИЕ — сразу после ИТОГа: «проверено M из найденных K» и, если есть, «НЕ
            // проверено X». Потеря покрытия обязана быть видна числом, а не скрываться за
            // зелёным вердиктом.
            Line(run.CoverageLine(queue != null ? queue.Total : run.Total));
            Line(run.VerdictLine());
            if (run.TimedOut > 0)
                Line("[KvUiSweep] ВНИМАНИЕ: элементов с таймаутом " + run.TimedOut +
                     " — Unity не даёт прервать уже начавшийся вызов, поэтому «завис навсегда» " +
                     "виден как отсутствие этой итоговой строки");
            if (run.Disabled > 0)
                Line("[KvUiSweep] ВНИМАНИЕ: недоступных элементов (interactable=false) " + run.Disabled +
                     " — оператор их тоже нажать не может; если такая кнопка ОБЯЗАНА работать, " +
                     "это дефект заполнения, а не прогона");
            if (run.Missing > 0) ReportMissing();
            if (stuckPanels.Count > 0) ReportStuckPanels();
            // СЧЁТЧИК ВОССТАНОВЛЕНИЯ — ВСЕГДА, даже нулём: «не восстановлено: 0» это доказательство,
            // а отсутствие строки — молчание.
            Line("[KvUiSweep] ВОССТАНОВЛЕНИЕ ПАНЕЛЕЙ: не восстановлено " + restoreFailures +
                 " · контекст (меню/панель) восстановлен " + contextRestores + " раз");
            if (notPressed > 0)
                Line("[KvUiSweep] не нажимались (запрещено правилом): " + notPressed);

            WriteReport();
            yield return null;
            Quit();
        }

        /// <summary>
        /// АВАРИЙНОЕ ЗАВЕРШЕНИЕ (приложение ушло в фон). Выполняется СИНХРОННО, без корутины и без
        /// ожидания кадров: кадров может уже не быть. Пишет ту же итоговую пару строк, что и
        /// обычное завершение, — тестировщик обязан получить КОНЕЧНЫЙ вердикт, а не тишину.
        /// </summary>
        private void EmergencyFinish(string why)
        {
            if (finished) return;
            finished = true;

            try
            {
                string interruptLine = run.Interrupt(why);
                // СНАЧАЛА СТРОКА ЭЛЕМЕНТА: виновник обязан быть виден в списке отчёта, а не только
                // в тексте прерывания и в счётчике.
                if (run.InterruptedElement != null) Line(run.InterruptedElement.Line);
                Line(interruptLine);
                Line(run.TotalLine(Time.realtimeSinceStartup - startedAt));
                Line(run.VerdictLine());
                Line("[KvUiSweep] ПРЕРВАНО: итог записан, приложение завершается — обход продолжать нельзя");
            }
            catch (Exception e)
            {
                Debug.LogError("[KvUiSweep] аварийный отчёт не записан: " + e.GetType().Name + ": " + e.Message);
            }

            WriteReport();
            Quit();
        }

        /// <summary>
        /// СПИСОК ИСЧЕЗНУВШИХ ЭЛЕМЕНТОВ отдельным блоком. Число в ИТОГе говорит «сколько», а
        /// список — «какие»: без него тестировщик не поймёт, перестроение это или настоящая
        /// пропажа кнопки. Печатаются пути, а не «элемент N».
        /// </summary>
        private void ReportMissing()
        {
            Line("[KvUiSweep] ИСЧЕЗЛИ (путь не найден после перепоиска и пересборки списка — " +
                 "проверять было нечего, это НЕ «кнопка не работает»):");
            int shown = 0;
            for (int i = 0; i < run.Elements.Count; i++)
            {
                KvUiSweepElement e = run.Elements[i];
                if (e == null || !e.Missing) continue;
                if (shown >= 20)
                {
                    Line("  · …и ещё " + (run.Missing - shown));
                    break;
                }
                Line("  · " + e.Path);
                shown++;
            }
        }

        /// <summary>
        /// СТРОКА «ПАНЕЛЬ НЕ ОТКРЫВАЕТСЯ НИ ОДНОЙ КНОПКОЙ» — НАСТОЯЩАЯ НАХОДКА, а не «без
        /// эффекта». Если после первого прохода и второго прохода панель так и осталась скрытой,
        /// значит ни одна видимая кнопка её не открывает: её элементы проверить нечем, и об этом
        /// надо сказать прямо, а не обвинять кнопки внутри неё.
        /// </summary>
        private void ReportStuckPanels()
        {
            Line("[KvUiSweep] ПАНЕЛЬ НЕ ОТКРЫВАЕТСЯ НИ ОДНОЙ КНОПКОЙ (элементы внутри не проверены):");
            int shown = 0;
            foreach (string panel in stuckPanels)
            {
                if (shown >= 20)
                {
                    Line("  · …и ещё " + (stuckPanels.Count - shown));
                    break;
                }
                Line("  · " + panel);
                shown++;
            }
        }

        private void WriteReport()
        {
            string path = reportPath.Length > 0
                ? reportPath
                : ReportPath(run != null ? run.Layout : "pc");
            try
            {
                File.WriteAllText(path, report.ToString(), new UTF8Encoding(false));
                reportFileReady = true;
                Debug.Log("[KvUiSweep] отчёт записан: " + path);
            }
            catch (Exception e)
            {
                Debug.LogError("[KvUiSweep] не удалось записать отчёт «" + path + "»: " + e.Message);
            }
        }

        private void Quit()
        {
            started = false;
            Debug.Log("[KvUiSweep] завершение приложения после прогона");
            Application.Quit();
#if UNITY_EDITOR
            // В редакторе `Application.Quit()` ничего не делает — останавливаем PlayMode сами,
            // иначе тестировщик решит, что прогон «повис».
            UnityEditor.EditorApplication.isPlaying = false;
#endif
        }

#if UNITY_EDITOR
        /// <summary>Пункт меню: тот же прогон из PlayMode, без adb.</summary>
        [UnityEditor.MenuItem("KazistovVv/Диагностика/Самопрогон интерфейса (PlayMode)")]
        private static void RunFromMenu()
        {
            RunFromEditor();
        }
#endif

        // ------------------------------------------------------------------ кандидат обхода

        /// <summary>Один будущий элемент обхода (uGUI-элемент или иконка панели шлема).</summary>
        private class Candidate
        {
            public string Path = "";
            /// <summary>
            /// КЛЮЧ ПОИСКА (`KvUiSweepNames.KeyOf(Path)`) — путь БЕЗ подписи. Именно по нему
            /// элемент находится заново после перестроения интерфейса: подпись меняется от
            /// нажатия (переключатель переписывает текст), а иерархия — нет.
            /// </summary>
            public string Key = "";
            public KvUiSweepKind Kind;
            /// <summary>uGUI-элемент.</summary>
            public Selectable Target;
            /// <summary>Панель шлема, которой принадлежит иконка.</summary>
            public KvXrGroupPanel Panel;
            /// <summary>Панель, в чьём дереве лежит uGUI-элемент (для пересборки свёрнутой панели).</summary>
            public KvXrGroupPanel PanelOwner;
            /// <summary>Индексы иконок, которые надо нажать, чтобы попасть на уровень.</summary>
            public int[] PathIndices;
            /// <summary>Номер иконки на своём уровне.</summary>
            public int Index;
            /// <summary>Какой уровень панели должен быть перед нажатием.</summary>
            public int ExpectedLevel;
            public int Depth;
            /// <summary>Уровень панели ПОСЛЕ нажатия (для раскрытия следующего уровня) и число иконок.</summary>
            public int ResultLevel = -1;
            public int ResultIcons;
            /// <summary>Подписи иконок следующего уровня, снятые В МОМЕНТ нажатия.</summary>
            public string[] ResultTitles;
            /// <summary>Панель оболочки, которую пришлось открыть (`""` — не открывали).</summary>
            public string Container = "";
            /// <summary>Элемент принадлежит панелям проекта (а не посторонней заставке/плагину).</summary>
            public bool ProjectOwned = true;
            /// <summary>ОТКРЫВАЕТ ПАНЕЛЬ/ЭКРАН — признак ЯРУСА 1 (см. `KvUiSweepTiers`).</summary>
            public bool OpensPanel;
            /// <summary>Подпись элемента (для правил ярусов): текст кнопки без пути.</summary>
            public string Label = "";
            /// <summary>
            /// ЭЛЕМЕНТ СИСТЕМНОГО ШЛЮЗА (предполётная заглушка разрешений). Такой элемент НЕ
            /// нажимается и его панель НЕ включается принудительно: нажатие вызывает системный
            /// диалог, приложение уходит в фон, и прогон обрывается на первом же элементе —
            /// именно это случилось на планшете со сборкой 10:45.
            /// </summary>
            public bool SystemGate;
            /// <summary>Канвас панели шлема, включённый для проверки (после элемента выключается).</summary>
            public KvXrGroupPanel ShowedPanel;
            /// <summary>Была ли видна панель до показа (возвращается после проверки).</summary>
            public bool ShowedPanelWasVisible = true;
            /// <summary>Стартовое меню показал прогон (после элемента закрывается).</summary>
            public bool ShowedStartMenu;
            /// <summary>КАК элемент пришлось открыть (`ShowPanel(settings)`, `SetActive`…).</summary>
            public string PreparedBy = "";
            /// <summary>
            /// ЭЛЕМЕНТ ПРИНАДЛЕЖИТ ПАНЕЛИ ШЛЕМА (uGUI внутри её дерева или иконка самой панели).
            /// Для таких элементов путь существует ТОЛЬКО на своём уровне панели, поэтому перед
            /// проверкой (и перед «исчез») обход возвращает панель на этот уровень штатными
            /// путями — см. `KvUiSweepPanelNav`. В AR/ПК таких элементов нет, и правило там не
            /// действует.
            /// </summary>
            public bool PanelBound;
            /// <summary>
            /// ЦЕПОЧКА ШТАТНЫХ НАЖАТИЙ ОТ БАЗЫ ДО УРОВНЯ ЭЛЕМЕНТА (подписи иконок). `null` —
            /// цепочки нет: стартовое меню показывается своим `Show`, окно компьютера — своим
            /// окном (это решает рантайм при восстановлении).
            /// </summary>
            public string[] RestoreChain;
            /// <summary>ИМЯ УРОВНЯ для причины «панель не открыта» («экран «Состояние»»…).</summary>
            public string RestoreScreenTitle = "";
            /// <summary>ПОЧЕМУ ЭКРАН НЕ ВОССТАНОВИЛСЯ (`""` — нечего восстанавливать/восстановилось).</summary>
            public string RestoreFail = "";

            public bool IsPanelIcon { get { return Kind == KvUiSweepKind.PanelIcon; } }
        }
    }

    /// <summary>
    /// ВОССТАНОВЛЕНИЕ ЧИСЛА КОМФОРТА В НАСТРОЙКУ. Вынесено отдельно, чтобы правило «сотые →
    /// сила виньетки» было в одном месте и не разъезжалось с <see cref="KvUiSweepRuntime"/>.
    /// </summary>
    public static class KvUiSweepSettings
    {
        /// <summary>Сила виньетки из числа комфорта (признак «включена» отбрасывается).</summary>
        public static float ComfortStrength(int comfort)
        {
            int hundredths = comfort >= 1000 ? comfort - 1000 : comfort;
            if (hundredths < 0) hundredths = 0;
            return Mathf.Clamp(hundredths / 100f, KvXrSettings.MinVignetteStrength,
                KvXrSettings.MaxVignetteStrength);
        }
    }
}
